:root {
  color-scheme: light;
  --bg: #f4f6f9;
  --surface: #ffffff;
  --surface-2: #f8fafc;
  --surface-3: #eef3f9;
  --primary: #0f4fc4;
  --primary-dark: #062d77;
  --primary-deep: #041f56;
  --red: #ed1c24;
  --red-soft: #fee2e2;
  --blue-soft: #eaf2ff;
  --gold: #d99a00;
  --gold-soft: #fff4d8;
  --green: #16a34a;
  --green-soft: #dcfce7;
  --teal: #0f9488;
  --teal-soft: #ccfbf1;
  --orange: #f97316;
  --orange-soft: #ffedd5;
  --purple: #7c3aed;
  --purple-soft: #ede9fe;
  --text: #1f2937;
  --muted: #64748b;
  --border: #dbe3ec;
  --danger: #b42318;
  --shadow: 0 18px 45px rgba(15, 23, 42, 0.08);
  --shadow-soft: 0 12px 30px rgba(15, 23, 42, 0.07);
  --radius: 18px;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --bg: #07111f;
  --surface: #0f172a;
  --surface-2: #162033;
  --surface-3: #1e293b;
  --primary: #60a5fa;
  --primary-dark: #93c5fd;
  --primary-deep: #dbeafe;
  --red: #f87171;
  --red-soft: #3a1d24;
  --blue-soft: #12233f;
  --gold: #fbbf24;
  --gold-soft: #2f2a16;
  --green: #4ade80;
  --green-soft: #12311f;
  --teal: #2dd4bf;
  --teal-soft: #12362f;
  --orange: #fb923c;
  --orange-soft: #392111;
  --purple: #c084fc;
  --purple-soft: #25193c;
  --text: #e5eefb;
  --muted: #9aa7bc;
  --border: #24324a;
  --danger: #fda4af;
  --shadow: 0 24px 50px rgba(2, 8, 23, 0.38);
  --shadow-soft: 0 14px 34px rgba(2, 8, 23, 0.28);
}


* {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  min-width: 100%;
  min-height: 100%;
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
}

html {
  min-height: 100%;
  background: var(--bg);
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: "Segoe UI", Arial, sans-serif;
}

#root {
  min-height: 100vh;
  display: block;
  box-sizing: border-box;
}

.app-root {
  min-height: 100vh;
  position: relative;
}

.theme-toggle-button {
  position: fixed;
  top: 18px;
  right: 18px;
  z-index: 1000;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 10px 14px;
  background: color-mix(in srgb, var(--surface) 88%, transparent);
  color: var(--text);
  box-shadow: var(--shadow-soft);
  backdrop-filter: blur(12px);
}

.theme-toggle-button:hover {
  transform: translateY(-1px);
  box-shadow: var(--shadow);
}

.theme-toggle-icon {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 999px;
  background: var(--primary);
  color: #fff;
  font-size: 16px;
  font-weight: 800;
}

.theme-toggle-copy {
  display: grid;
  line-height: 1.05;
}

.theme-toggle-copy small {
  font-size: 10px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.theme-toggle-copy strong {
  font-size: 13px;
}

button,
input,
select,
textarea {
  font-family: inherit;
}

button {
  cursor: pointer;
}

/* LOGIN */

.login-screen,
.loading-screen {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 28px;
  background: radial-gradient(circle at top left, #e4edf7, transparent 38%),
    linear-gradient(135deg, #f4f6f9, #e9eef5);
}

.login-card {
  width: min(980px, 100%);
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  background: white;
  border-radius: 28px;
  box-shadow: var(--shadow);
  overflow: hidden;
  border: 1px solid var(--border);
}

.login-info {
  padding: 48px;
  background: linear-gradient(180deg, #18324f, #0f253b);
  color: white;
}

.login-info small {
  color: #cbd5e1;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  display: block;
  margin-bottom: 12px;
}

.login-info h1 {
  font-size: 34px;
  line-height: 1.12;
  margin-bottom: 18px;
}

.login-info p {
  color: #d8e1ec;
  line-height: 1.6;
}

.login-bullets {
  display: grid;
  gap: 12px;
  margin-top: 26px;
}

.login-bullets div {
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.14);
  padding: 13px 14px;
  border-radius: 14px;
}

.login-form {
  padding: 48px;
}

.login-form h2 {
  color: var(--primary-dark);
  margin-bottom: 8px;
}

.login-form p {
  color: var(--muted);
  font-size: 14px;
  line-height: 1.45;
  margin-bottom: 22px;
}

label {
  display: block;
  margin: 16px 0 7px;
  font-size: 13px;
  font-weight: 700;
  color: var(--primary-dark);
}

input {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px;
  font-size: 14px;
  outline: none;
}

input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(15, 79, 196, 0.12);
}

.login-form button {
  width: 100%;
  margin-top: 18px;
  background: var(--primary);
  color: white;
  border: none;
  border-radius: 12px;
  padding: 11px 16px;
  cursor: pointer;
  font-weight: 700;
  font-size: 14px;
}

.login-form button:hover {
  background: var(--primary-dark);
}

.login-form button:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}

.error-box {
  margin-top: 14px;
  padding: 12px;
  border-radius: 12px;
  background: #fee2e2;
  color: var(--danger);
  font-size: 14px;
}

/* APP SHELL */

.app-shell {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  min-height: 100vh;
  width: 100%;
  overflow-x: hidden;
}

.sidebar {
  position: relative;
  background:
    radial-gradient(circle at 18% 8%, rgba(255, 255, 255, 0.16), transparent 28%),
    radial-gradient(circle at 95% 18%, rgba(237, 28, 36, 0.22), transparent 34%),
    radial-gradient(circle at 15% 95%, rgba(237, 28, 36, 0.16), transparent 30%),
    linear-gradient(180deg, #123f8c 0%, #0a2f70 45%, #071f4f 100%);
  color: white;
  padding: 26px 18px;
  overflow: hidden;
  border-right: 1px solid rgba(255, 255, 255, 0.12);
}

.sidebar::after {
  content: "";
  position: absolute;
  left: -100px;
  bottom: -120px;
  width: 360px;
  height: 360px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.08);
  pointer-events: none;
}

.sidebar-brand-panel {
  position: relative;
  z-index: 1;
  text-align: center;
  margin-bottom: 34px;
}

.sidebar-logo {
  width: 165px;
  max-width: 100%;
  display: block;
  margin: 0 auto 26px;
  background: rgba(255, 255, 255, 0.92);
  border-radius: 18px;
  padding: 12px;
  box-shadow: 0 12px 26px rgba(2, 12, 32, 0.18);
}

.sidebar-brand-panel h1 {
  font-size: 19px;
  line-height: 1.25;
  margin: 0;
  color: #ffffff;
}

.sidebar-divider {
  width: 100%;
  height: 1px;
  background: rgba(255, 255, 255, 0.22);
  margin: 24px 0;
}

.sidebar-brand-panel h2 {
  font-size: 18px;
  line-height: 1.4;
  margin: 0;
  color: #f1f6ff;
}

.sidebar-nav {
  position: relative;
  z-index: 1;
  display: grid;
  gap: 14px;
  margin-top: 20px;
}

.sidebar-nav button {
  display: flex;
  align-items: center;
  gap: 13px;
  width: 100%;
  border: none;
  border-radius: 12px;
  padding: 15px 15px;
  font-size: 14px;
  font-weight: 700;
  color: #e5efff;
  background: rgba(255, 255, 255, 0.06);
  text-align: left;
  transition: 0.18s ease;
}

.sidebar-nav button:hover {
  background: rgba(255, 255, 255, 0.13);
}

.sidebar-nav button.active {
  background: linear-gradient(135deg, #ffffff 0%, #eef5ff 100%);
  color: #0a2f70;
  box-shadow: 0 12px 24px rgba(2, 12, 32, 0.22);
}

.sidebar-nav button.active .nav-icon {
  color: #ed1c24;
}

.nav-icon {
  width: 24px;
  color: currentColor;
  font-size: 18px;
}

.sidebar-footer {
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: 82px;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 12px;
  color: white;
}

.sidebar-footer-icon {
  font-size: 23px;
}

.sidebar-footer strong {
  display: block;
  font-size: 13px;
}

.sidebar-footer span {
  display: block;
  font-size: 12px;
  color: #d5e3ff;
}

.logout-button {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 24px;
  z-index: 1;
  width: calc(100% - 36px);
  background: rgba(237, 28, 36, 0.14) !important;
  color: #ffffff !important;
  border: 1px solid rgba(255, 160, 160, 0.35) !important;
  border-radius: 12px;
  padding: 11px 16px;
  cursor: pointer;
  font-weight: 700;
  font-size: 14px;
}

.logout-button:hover {
  background: rgba(237, 28, 36, 0.24) !important;
}

.main-content {
  padding: 30px 36px;
  min-width: 0;
  width: 100%;
  max-width: 100%;
  overflow-x: hidden;
}

.main-content h2 {
  color: #0f2442;
  font-size: 30px;
}

/* GENERAL EXISTING COMPONENTS */

.card {
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  margin-top: 20px;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
}

.card h3 {
  color: var(--primary-dark);
}

.card p {
  color: var(--muted);
}

.page-description {
  color: var(--muted);
  max-width: 850px;
  line-height: 1.5;
  margin-top: -8px;
  margin-bottom: 20px;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(220px, 1fr));
  gap: 16px;
}

.form-group.full {
  grid-column: 1 / -1;
}

textarea,
select {
  width: 100%;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 12px;
  font-size: 14px;
  outline: none;
  resize: vertical;
}

textarea {
  min-height: 100px;
}

textarea:focus,
select:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(15, 79, 196, 0.12);
}

.form-group button,
.card button,
.secondary-button {
  border: none;
  border-radius: 12px;
  padding: 11px 16px;
  cursor: pointer;
  font-weight: 700;
  font-size: 14px;
  background: var(--primary);
  color: white;
}

.secondary-button {
  background: #e8edf3;
  color: var(--primary-dark);
  margin-bottom: 14px;
}

.message-box {
  background: #eef6ff;
  color: var(--primary-dark);
  border: 1px solid #bfdbfe;
  border-radius: 14px;
  padding: 12px 14px;
  margin-bottom: 18px;
}

.table-scroll {
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
}

.data-table {
  width: 100%;
  min-width: 620px;
  border-collapse: collapse;
}

.data-table th {
  text-align: left;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--muted);
  background: #f8fafc;
  padding: 13px 12px;
  border-bottom: 1px solid var(--border);
  white-space: nowrap;
}

.data-table td {
  padding: 15px 12px;
  border-bottom: 1px solid var(--border);
  vertical-align: top;
  font-size: 14px;
  color: var(--text);
}

.data-table td strong {
  display: block;
  color: var(--primary-dark);
  margin-bottom: 5px;
  line-height: 1.35;
}

.data-table td span {
  display: block;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.35;
}

.details-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(260px, 1fr));
  gap: 18px;
  margin-bottom: 18px;
}

.stack-list {
  display: grid;
  gap: 12px;
}

.list-item {
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 13px;
  background: #fbfdff;
}

.list-item strong {
  display: block;
  color: var(--primary-dark);
  margin-bottom: 5px;
}

.list-item span,
.list-item small {
  display: block;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.35;
  margin-top: 4px;
}

.list-item a {
  display: block;
  color: #2563eb;
  word-break: break-all;
  margin-bottom: 5px;
}

.evidence-form {
  margin-top: 22px;
  border-top: 1px solid var(--border);
  padding-top: 18px;
}

.file-preview {
  display: block;
  margin-top: 8px;
  color: var(--muted);
  font-size: 13px;
  background: #f8fafc;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 8px 10px;
}

.admin-review-card {
  border-left: 5px solid var(--accent);
  margin-bottom: 18px;
}

.admin-review-actions {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 16px;
}

.danger-button {
  background: #fee2e2 !important;
  color: #991b1b !important;
}

/* EXECUTIVE DASHBOARD */

.executive-dashboard {
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.dashboard-loading-card {
  background: white;
  border: 1px solid var(--border);
  border-radius: 22px;
  box-shadow: var(--shadow-soft);
  padding: 26px;
  color: var(--muted);
}

.dashboard-topbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  margin-bottom: 24px;
}

.dashboard-topbar h2 {
  margin: 0 0 6px;
  color: #0f2442;
  font-size: 30px;
  letter-spacing: -0.03em;
}

.dashboard-topbar p {
  margin: 0;
  color: #536176;
  font-size: 15px;
}

.dashboard-top-actions {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.last-updated {
  color: #536176;
  font-size: 13px;
  white-space: nowrap;
}

.dashboard-refresh-button {
  border: none;
  border-radius: 7px;
  background: var(--primary);
  color: white;
  padding: 13px 18px;
  font-weight: 800;
  box-shadow: 0 10px 20px rgba(15, 79, 196, 0.22);
}

.dashboard-refresh-button:hover {
  background: var(--primary-dark);
}

.dashboard-metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 22px;
}

.visual-metrics-grid {
  grid-template-columns: repeat(8, minmax(120px, 1fr));
}

.metric-card {
  background: var(--surface);
  border: 1px solid #edf1f7;
  border-radius: 10px;
  box-shadow: var(--shadow-soft);
  padding: 18px;
  min-width: 0;
}

.visual-metric {
  position: relative;
  display: flex;
  align-items: center;
  gap: 15px;
  min-height: 112px;
  overflow: hidden;
}

.visual-metric::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 4px;
}

.metric-icon {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 24px;
  font-weight: 900;
}

.visual-metric strong {
  display: block;
  color: #0f2442;
  font-size: 30px;
  line-height: 1;
  margin-bottom: 7px;
}

.visual-metric span {
  color: #344256;
  font-size: 13px;
  font-weight: 800;
}

.metric-blue .metric-icon {
  color: var(--primary);
  background: var(--blue-soft);
}

.metric-blue::after {
  background: var(--primary);
}

.metric-red .metric-icon {
  color: var(--red);
  background: var(--red-soft);
}

.metric-red::after {
  background: var(--red);
}

.metric-gold .metric-icon {
  color: var(--gold);
  background: var(--gold-soft);
}

.metric-gold::after {
  background: var(--gold);
}

.metric-purple .metric-icon {
  color: var(--purple);
  background: var(--purple-soft);
}

.metric-purple::after {
  background: var(--purple);
}

.metric-orange .metric-icon {
  color: var(--orange);
  background: var(--orange-soft);
}

.metric-orange::after {
  background: var(--orange);
}

.metric-green .metric-icon {
  color: var(--green);
  background: var(--green-soft);
}

.metric-green::after {
  background: var(--green);
}

.metric-teal .metric-icon {
  color: var(--teal);
  background: var(--teal-soft);
}

.metric-teal::after {
  background: var(--teal);
}

.dashboard-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
  margin-bottom: 18px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.dashboard-grid-large {
  grid-template-columns: 1fr 1.08fr;
}

.visual-card {
  background: white;
  border: 1px solid #e9eef6;
  border-radius: 16px;
  box-shadow: var(--shadow-soft);
  padding: 20px;
  min-width: 0;
  overflow: hidden;
}

.visual-card-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 18px;
}

.visual-card-header h3 {
  color: #0f2442;
  margin: 0;
  font-size: 18px;
}

.visual-card-header span {
  color: #9aa7b7;
}

.general-status-content {
  position: relative;
  display: grid;
  grid-template-columns: 0.85fr 1fr 90px;
  gap: 28px;
  align-items: center;
  min-height: 130px;
}

.status-label {
  display: block;
  color: #41516a;
  font-size: 13px;
  margin-bottom: 2px;
}

.status-percentage {
  display: block;
  color: var(--primary);
  font-size: 43px;
  line-height: 1;
  margin-bottom: 17px;
}

.progress-track {
  height: 10px;
  border-radius: 100px;
  background: #e8edf3;
  overflow: hidden;
}

.progress-fill {
  height: 100%;
  background: var(--primary);
  border-radius: inherit;
}

.progress-scale {
  display: flex;
  justify-content: space-between;
  margin-top: 7px;
  color: #6b778c;
  font-size: 12px;
}

.general-status-content p {
  color: #526176;
  line-height: 1.45;
  font-size: 14px;
  margin: 0;
}

.status-watermark {
  color: #eef2f7;
  font-size: 88px;
  line-height: 1;
}

.alerts-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.alert-card {
  border-radius: 12px;
  padding: 18px;
  min-height: 125px;
}

.alert-top {
  display: flex;
  align-items: center;
  gap: 13px;
}

.alert-top span {
  font-size: 25px;
}

.alert-top strong {
  font-size: 31px;
  line-height: 1;
}

.alert-card h4 {
  margin: 7px 0 18px;
  font-size: 14px;
}

.alert-card p {
  margin: 0;
  color: #536176;
  font-size: 14px;
  line-height: 1.35;
}

.alert-red {
  background: linear-gradient(135deg, #fff1f1, #ffe3e3);
  border: 1px solid #ffd0d0;
  color: var(--red);
}

.alert-gold {
  background: linear-gradient(135deg, #fff9e9, #fff0c7);
  border: 1px solid #ffe3a3;
  color: var(--gold);
}

.alert-orange {
  background: linear-gradient(135deg, #fff6ee, #ffead8);
  border: 1px solid #ffd2ad;
  color: var(--orange);
}

.section-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 14px;
}

.section-title-row h3 {
  margin: 0;
  color: #0f2442;
  font-size: 18px;
}

.section-title-icon {
  font-size: 22px;
  font-weight: 900;
}

.section-title-red {
  color: var(--red);
}

.section-title-gold {
  color: var(--gold);
}

.section-title-green {
  color: var(--green);
}

.section-title-blue {
  color: var(--primary);
}

