/* RESPONSIVE */

@media (max-width: 1450px) {
  .visual-metrics-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

@media (max-width: 1200px) {
  .dashboard-grid,
  .dashboard-grid-large {
    grid-template-columns: 1fr;
  }

  .general-status-content {
    grid-template-columns: 1fr;
  }

  .status-watermark {
    display: none;
  }
}

@media (max-width: 1100px) {
  .dashboard-metrics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .visual-metrics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .alerts-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 900px) {
  .form-grid,
  .details-grid {
    grid-template-columns: 1fr;
  }

  .project-mini-card {
    grid-template-columns: 1fr;
  }

  .project-mini-meta {
    grid-template-columns: 1fr 1fr;
  }

  .project-mini-badge {
    width: max-content;
  }
}

@media (max-width: 800px) {
  .login-card,
  .app-shell {
    grid-template-columns: 1fr;
  }

  .login-info,
  .login-form {
    padding: 30px;
  }

  .sidebar {
    position: relative;
    min-height: auto;
    padding: 22px;
  }

  .sidebar-footer,
  .logout-button {
    position: static;
    width: 100%;
    margin-top: 24px;
  }

  .main-content {
    padding: 22px;
  }

  .dashboard-topbar {
    flex-direction: column;
  }

  .dashboard-top-actions {
    justify-content: flex-start;
  }
}

@media (max-width: 620px) {
  .visual-metrics-grid {
    grid-template-columns: 1fr;
  }

  .project-mini-meta {
    grid-template-columns: 1fr;
  }

  .last-updated {
    white-space: normal;
  }
}

