  grid-template-columns: 38px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
}

.recent-icon {
  background: #eaf2ff;
  color: #0f4fc4;
}

.side-alert {
  border-radius: 14px;
  padding: 14px;
  margin-top: 10px;
}

.side-alert strong {
  display: block;
  margin-bottom: 4px;
}

.side-alert p {
  margin: 0;
  font-size: 13px;
}

.red-side-alert {
  background: #fff1f1;
  color: #ed1c24;
}

.orange-side-alert {
  background: #fff6ee;
  color: #f97316;
}

/* ALTA DE PROYECTO */

.form-section-card {
  margin-bottom: 18px;
}

.form-section-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 18px;
}

.form-section-header > span {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #0f4fc4;
  color: white;
  font-weight: 900;
}

.form-section-header h3 {
  margin: 0;
  color: #0f2442;
  font-size: 19px;
}

.form-section-header p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
}

.visual-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px 22px;
}

.visual-field {
  margin: 0;
  display: grid;
  gap: 8px;
}

.visual-field.full {
  grid-column: 1 / -1;
}

.visual-field > span {
  color: #0f2442;
  font-size: 13px;
  font-weight: 900;
}

.visual-field b {
  color: #ed1c24;
}

.visual-field input,
.visual-field select,
.visual-field textarea {
  background: white;
  border: 1px solid #d9e2ef;
  border-radius: 10px;
  padding: 13px 14px;
  font-size: 14px;
}

.visual-field textarea {
  min-height: 92px;
}

.field-counter {
  justify-self: end;
  color: #64748b;
  margin-top: -28px;
  margin-right: 12px;
  position: relative;
  z-index: 1;
}

.selected-chips {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.selected-chips button {
  border: none;
  background: #eef4ff;
  color: #0f4fc4;
  padding: 7px 10px;
  border-radius: 100px;
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  font-weight: 800;
}

.selected-chips span {
  width: 22px;
  height: 22px;
  background: #0f4fc4;
  color: white;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 10px;
}

.progress-stepper {
  display: grid;
  grid-template-columns: 48px 1fr 48px;
  border: 1px solid #d9e2ef;
  border-radius: 10px;
  overflow: hidden;
}

.progress-stepper button {
  border: none;
  background: #f8fafc;
  color: #0f2442;
  font-weight: 900;
  font-size: 18px;
}

.progress-stepper input {
  border: none;
  text-align: center;
  border-left: 1px solid #d9e2ef;
  border-right: 1px solid #d9e2ef;
  border-radius: 0;
}

.attachments-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(300px, 0.7fr);
  gap: 22px;
}

.dropzone {
  border: 2px dashed #cbd7e6;
  border-radius: 16px;
  min-height: 150px;
  display: grid;
  place-items: center;
  text-align: center;
  padding: 24px;
  margin: 0;
  cursor: pointer;
}

.dropzone input {
  display: none;
}

.dropzone span {
  color: #0f4fc4;
  font-size: 36px;
}

.dropzone strong {
  color: #0f2442;
}

.dropzone p {
  color: #0f4fc4;
  margin: 3px 0;
  font-weight: 800;
}

.dropzone small {
  color: #64748b;
  font-size: 12px;
}

.attached-files {
  display: grid;
  align-content: start;
  gap: 10px;
}

.attached-file-item {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 11px;
}

.attached-file-item > span {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #fee2e2;
  color: #ed1c24;
  font-size: 11px;
  font-weight: 900;
}

.attached-file-item strong {
  color: #0f2442;
  font-size: 13px;
}

.attached-file-item small {
  display: block;
  color: #64748b;
  margin-top: 3px;
}

.project-preview-card {
  border: 1px solid #dbe3ec;
  border-radius: 14px;
  padding: 18px;
  background: linear-gradient(180deg, #ffffff, #fbfdff);
}

.preview-label {
  display: inline-block;
  color: #0f4fc4;
  background: #eaf2ff;
  border-radius: 7px;
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 900;
  margin-bottom: 12px;
}

.project-preview-card h3 {
  margin: 0 0 6px;
  color: #0f2442;
}

.project-preview-card p {
  color: #64748b;
  margin: 0 0 12px;
  font-size: 13px;
}

.preview-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 14px;
}

.preview-details {
  display: grid;
  gap: 10px;
}

.preview-details > div:not(.area-progress) {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.preview-details span {
  color: #64748b;
  font-size: 13px;
}

.preview-details strong {
  color: #0f2442;
  font-size: 13px;
}

.required-list div {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #526176;
  font-size: 13px;
}

.required-list span {
  color: #94a3b8;
}

.required-list div.complete span {
  color: #16a34a;
}

.required-list div.complete {
  color: #0f2442;
  font-weight: 800;
}

.tip-item {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
}

.tip-icon {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-weight: 900;
}

.tip-green {
  background: #dcfce7;
  color: #16a34a;
}

.tip-blue {
  background: #eaf2ff;
  color: #0f4fc4;
}

.tip-orange {
  background: #ffedd5;
  color: #f97316;
}

.tip-item strong {
  color: #0f2442;
  font-size: 13px;
}

.tip-item p {
  color: #64748b;
  margin: 4px 0 0;
  font-size: 12px;
}

.empty-state.small {
  min-height: 80px;
}

/* RESPONSIVE NUEVAS VISTAS */

@media (max-width: 1450px) {
  .projects-layout,
  .all-projects-layout,
  .create-project-layout {
    grid-template-columns: 1fr;
  }

  .projects-side-panel,
  .all-projects-side,
  .create-project-side {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .create-project-side {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 1200px) {
  .my-metrics-grid,
  .all-metrics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .advanced-filters-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .apply-filter-button {
    grid-column: 1 / -1;
  }

  .attachments-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 900px) {
  .visual-page-header {
    flex-direction: column;
  }

  .visual-page-actions,
  .visual-search,
  .visual-search.wide {
    width: 100%;
  }

  .assigned-bottom {
    grid-template-columns: 1fr;
  }

  .assigned-title-row {
    flex-direction: column;
  }

  .status-distribution {
    grid-template-columns: 1fr;
  }

  .projects-side-panel,
  .all-projects-side {
    grid-template-columns: 1fr;
  }

  .visual-form-grid {
    grid-template-columns: 1fr;
  }

  .filters-card-top,
  .list-header {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 620px) {
  .my-metrics-grid,
  .all-metrics-grid {
    grid-template-columns: 1fr;
  }

  .assigned-project-card {
    grid-template-columns: 1fr;
  }

  .advanced-filters-grid {
    grid-template-columns: 1fr;
  }

  .status-bar-row {
    grid-template-columns: 12px 1fr;
  }

  .status-bar-row .mini-track,
  .status-bar-row strong,
  .status-bar-row small {
    grid-column: 2;
  }
}

/* =========================================================
   FIX GENERAL: USAR TODO EL ANCHO DE LA PANTALLA
========================================================= */

html,
body,
#root {
  width: 100%;
  min-width: 100%;
  min-height: 100vh;
  margin: 0;
  padding: 0;
}

body {
  overflow-x: hidden;
}

.app-shell {
  width: 100vw;
  max-width: 100vw;
  min-height: 100vh;
  grid-template-columns: 280px minmax(0, 1fr);
}

.main-content {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  overflow-x: hidden;
}

/* =========================================================
   FIX DASHBOARD EJECUTIVO: EVITAR QUE SE ENCIMEN LAS TARJETAS
========================================================= */

.executive-dashboard {
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.visual-metrics-grid {
  grid-template-columns: repeat(auto-fit, minmax(155px, 1fr));
}

.visual-metric {
  min-width: 0;
}

.visual-metric strong {
  font-size: clamp(24px, 2vw, 30px);
}

.visual-metric span {
  overflow-wrap: anywhere;
}

.dashboard-grid,
.dashboard-grid-large {
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.dashboard-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.dashboard-grid-large {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.08fr);
}

.visual-card {
  min-width: 0;
  max-width: 100%;
}

.general-status-content {
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1fr) 80px;
}

.alerts-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.alert-card {
  min-width: 0;
}

.alert-card h4,
.alert-card p {
  overflow-wrap: anywhere;
}

.project-mini-card {
  grid-template-columns: 52px minmax(0, 1fr) auto;
  min-width: 0;
}

.project-mini-content {
  min-width: 0;
}

.project-mini-content strong {
  overflow-wrap: anywhere;
}

.project-mini-meta {
  grid-template-columns: repeat(4, minmax(90px, 1fr));
  min-width: 0;
}

.project-mini-badge {
  max-width: 150px;
  white-space: normal;
  text-align: center;
}

/* =========================================================
   AJUSTES PARA PANTALLAS MEDIANAS
========================================================= */

@media (max-width: 1350px) {
  .dashboard-grid,
  .dashboard-grid-large {
    grid-template-columns: 1fr;
  }

  .general-status-content {
    grid-template-columns: 1fr;
  }

  .status-watermark {
    display: none;
  }

  .alerts-grid {
    grid-template-columns: repeat(3, minmax(160px, 1fr));
    overflow-x: auto;
    padding-bottom: 4px;
  }
}

@media (max-width: 1050px) {
  .app-shell {
    grid-template-columns: 240px minmax(0, 1fr);
  }

  .main-content {
    padding: 24px;
  }

  .project-mini-card {
    grid-template-columns: 1fr;
  }

  .project-mini-meta {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .project-mini-badge {
    width: fit-content;
    max-width: 100%;
  }
}

@media (max-width: 800px) {
  .app-shell {
    width: 100%;
    max-width: 100%;
    grid-template-columns: 1fr;
  }

  .sidebar {
    min-height: auto;
  }

  .main-content {
    padding: 18px;
  }

  .visual-page-header,
  .dashboard-topbar {
    flex-direction: column;
    align-items: flex-start;
  }

  .visual-page-actions,
  .dashboard-top-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .project-mini-meta {
    grid-template-columns: 1fr;
  }

  .alerts-grid {
    grid-template-columns: 1fr;
    overflow-x: visible;
  }
}

/* =========================================================
   DETALLE DE PROYECTO Y EDITAR PROYECTO
========================================================= */

.project-detail-page,
.edit-project-page {
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.breadcrumb-line {
  display: block;
  color: #0f4fc4;
  font-size: 13px;
  font-weight: 700;
  margin-top: 8px;
}

.status-change-select {
  height: 46px;
  min-width: 185px;
  border: 1px solid #d9e2ef;
  border-radius: 9px;
  background: white;
  color: #0f2442;
  padding: 0 14px;
  font-weight: 800;
}

.project-hero-strip,
.edit-summary-strip {
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.06);
  margin-bottom: 18px;
}

.project-hero-strip {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 20px 22px;
  border-left: 6px solid #0f4fc4;
}

.project-hero-strip h3 {
  margin: 0;
  color: #0f2442;
  font-size: 21px;
}

.project-code {
  color: #0f4fc4;
  font-weight: 900;
  font-size: 14px;
}

.project-hero-badges {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-left: auto;
}

.project-detail-layout,
.edit-project-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 420px;
  gap: 22px;
  align-items: start;
}

.project-detail-main,
.edit-project-main,
.project-detail-side,
.edit-project-side {
  min-width: 0;
}

.project-detail-side,
.edit-project-side {
  display: grid;
  gap: 18px;
}

.project-summary-card {
  padding-top: 0;
}

.project-steps {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  padding: 20px 0;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 18px;
}

.project-step {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
}

.project-step:not(:last-child)::after {
  content: "";
  position: absolute;
  left: calc(100% - 24px);
  right: -6px;
  top: 17px;
  border-top: 2px dashed #cbd5e1;
}

.project-step > span {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #e8edf5;
  color: #475569;
  font-weight: 900;
  position: relative;
  z-index: 1;
}

.project-step.completed > span {
  background: #dcfce7;
  color: #16a34a;
}

.project-step.current > span {
  background: #0f4fc4;
  color: white;
}

.project-step strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
}

.project-step small {
  color: #64748b;
  font-size: 11px;
}

.project-summary-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(220px, 0.8fr) minmax(220px, 0.8fr);
  gap: 22px;
  align-items: stretch;
}

.project-summary-left {
  display: grid;
  grid-template-columns: 76px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
}

.project-document-icon {
  width: 70px;
  height: 70px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: #fee2e2;
  color: #ed1c24;
  font-size: 32px;
  font-weight: 900;
}

.project-summary-left h3 {
  margin: 0 0 8px;
  color: #0f2442;
  font-size: 20px;
}

.project-summary-left p {
  margin: 0;
  color: #526176;
  line-height: 1.5;
  font-size: 14px;
}

.detail-progress-row {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: auto minmax(120px, 1fr) auto;
  gap: 12px;
  align-items: center;
}

.detail-progress-row span {
  color: #526176;
  font-size: 13px;
}

.detail-progress-row strong {
  color: #0f2442;
}

.project-summary-info {
  border-left: 1px solid #e5eaf2;
  padding-left: 22px;
  display: grid;
  gap: 12px;
  align-content: center;
}

.info-item {
  display: grid;
  gap: 5px;
}

.info-item > span {
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
}

.info-item > strong {
  color: #0f2442;
  font-size: 14px;
}

.detail-section-title {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.detail-section-title h3 {
  margin: 0;
  color: #0f2442;
  font-size: 17px;
}

.detail-section-icon {
  font-size: 21px;
  font-weight: 900;
}

.detail-blue {
  color: #0f4fc4;
}

.detail-red {
  color: #ed1c24;
}

.detail-purple {
  color: #7c3aed;
}

.detail-green {
  color: #16a34a;
}

.project-description-text {
  color: #526176;
  line-height: 1.6;
  font-size: 14px;
}

.section-header-with-action {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.upload-evidence-button {
  margin: 0;
  border: 1px solid #dbe7ff;
  background: white;
  color: #0f4fc4;
  border-radius: 9px;
  padding: 10px 15px;
  font-weight: 900;
  font-size: 13px;
  cursor: pointer;
}

.upload-evidence-button input {
  display: none;
}

.detail-files-table {
  min-width: 820px;
}

.file-name-cell {
  display: flex;
  align-items: center;
  gap: 10px;
}

.file-name-cell strong {
  color: #0f2442;
}

.file-type-icon {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  font-size: 10px;
  font-weight: 900;
}

.file-pdf {
  background: #fee2e2;
  color: #ed1c24;
}

.file-xlsx {
  background: #dcfce7;
  color: #16a34a;
}

.file-jpg {
  background: #fff4d8;
  color: #d99a00;
}

.file-file {
  background: #eaf2ff;
  color: #0f4fc4;
}

.table-actions a {
  border: 1px solid #dbe7ff;
  color: #0f4fc4;
  text-decoration: none;
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 12px;
  font-weight: 800;
}

.project-history-list {
  display: grid;
  gap: 16px;
}

.history-row {
  position: relative;
  display: grid;
  grid-template-columns: 14px 34px 120px auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
}

.history-row::before {
  content: "";
  position: absolute;
  left: 6px;
  top: -14px;
  bottom: -14px;
  width: 2px;
  background: #e2e8f0;
}

.history-row:first-child::before {
  top: 50%;
}

.history-row:last-child::before {
  bottom: 50%;
}

.history-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #0f4fc4;
  position: relative;
  z-index: 1;
}

.history-row strong {
  color: #0f2442;
  font-size: 13px;
}

.history-row p {
  margin: 0;
  color: #526176;
  font-size: 13px;
}

.history-row small {
  color: #64748b;
  font-size: 12px;
  white-space: nowrap;
}

.responsible-list,
.next-actions-list,
.comment-list {
  display: grid;
  gap: 12px;
}

.responsible-item {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}

.responsible-item strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
}

.responsible-item p {
  color: #64748b;
  margin: 3px 0 0;
  font-size: 12px;
}

.indicator-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.indicator-card {
  border-radius: 12px;
  padding: 14px 10px;
  text-align: center;
}

.indicator-card span {
  display: block;
  font-size: 22px;
  margin-bottom: 5px;
}

.indicator-card strong {
  display: block;
  font-size: 23px;
  color: #0f2442;
}

.indicator-card small {
  color: #526176;
  font-size: 11px;
}

.indicator-red {
  background: #fff1f1;
  color: #ed1c24;
}

.indicator-blue {
  background: #eaf2ff;
  color: #0f4fc4;
}

.indicator-purple {
  background: #ede9fe;
  color: #7c3aed;
}

.indicator-green {
  background: #dcfce7;
  color: #16a34a;
}

.action-item {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 10px;
}

.action-item > span {
  width: 20px;
  height: 20px;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  display: grid;
  place-items: center;
  color: white;
  font-size: 12px;
}

.action-item.done > span {
  background: #16a34a;
  border-color: #16a34a;
}

.action-item.done p {
  text-decoration: line-through;
  color: #94a3b8;
}

.action-item p {
  color: #0f2442;
  margin: 0;
  font-size: 13px;
}

.action-item small {
  color: #64748b;
  font-size: 12px;
  white-space: nowrap;
}

.comment-item {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 10px;
  padding: 10px;
  border: 1px solid #e5eaf2;
  border-radius: 12px;
}

.comment-item strong {
  color: #0f2442;
  font-size: 13px;
}

.comment-item p {
  color: #526176;
  margin: 3px 0;
  font-size: 12px;
}

.comment-item small {
  color: #64748b;
  font-size: 11px;
}

.admin-review-visual-card,
.impact-card {
  border-radius: 16px;
  padding: 20px;
  border: 1px solid #f3d28a;
  background: linear-gradient(135deg, #fff9ec, #fff1cf);
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.06);
}

.admin-review-visual-card > div,
.impact-card > div {
  display: grid;
  gap: 8px;
}

.admin-review-visual-card h3,
.impact-card h3 {
  margin: 0 0 10px;
  color: #0f2442;
}

.admin-review-visual-card p,
.impact-card p {
  color: #7c5c16;
  font-size: 13px;
}

/* EDITAR PROYECTO */

.edit-summary-strip {
  display: grid;
  grid-template-columns: 52px minmax(150px, 0.75fr) auto minmax(220px, 1.2fr) repeat(4, minmax(110px, 0.7fr));
  gap: 18px;
  align-items: center;
  padding: 18px;
}

.edit-summary-icon {
  width: 48px;
  height: 48px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #ef4444, #ed1c24);
  color: white;
  font-size: 24px;
  font-weight: 900;
}

.edit-summary-strip span {
  display: block;
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
  margin-bottom: 4px;
}

.edit-summary-strip strong {
  color: #0f2442;
  font-size: 14px;
}

.edit-form-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px 22px;
}

.edit-progress-control {
  display: grid;
  grid-template-columns: 44px 70px 44px minmax(160px, 1fr);
  align-items: center;
  gap: 10px;
}

.edit-progress-control button {
  height: 42px;
  border: 1px solid #d9e2ef;
  background: #f8fafc;
  border-radius: 8px;
  font-weight: 900;
}

.edit-progress-control input[type="number"] {
  text-align: center;
}

.edit-progress-control input[type="range"] {
  accent-color: #0f4fc4;
}

.current-progress-label {
  display: block;
  margin-top: 8px;
  color: #64748b;
  font-size: 12px;
}

.current-progress-label strong {
  color: #0f4fc4;
}

.impact-card button {
  border: none;
  background: transparent;
  color: #0f4fc4;
  font-weight: 900;
  padding: 0;
  text-align: left;
}

/* RESPONSIVE DETALLE / EDITAR */

@media (max-width: 1450px) {
  .project-detail-layout,
  .edit-project-layout {
    grid-template-columns: 1fr;
  }

  .project-detail-side,
  .edit-project-side {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .edit-summary-strip {
    grid-template-columns: 52px minmax(150px, 1fr) auto;
  }
}

@media (max-width: 1200px) {
  .project-summary-grid {
    grid-template-columns: 1fr;
  }

  .project-summary-info {
    border-left: none;
    border-top: 1px solid #e5eaf2;
    padding-left: 0;
    padding-top: 18px;
  }

  .edit-form-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .project-steps {
    overflow-x: auto;
    grid-template-columns: repeat(5, minmax(170px, 1fr));
    padding-bottom: 16px;
  }
}

@media (max-width: 900px) {
  .project-hero-strip {
    flex-direction: column;
    align-items: flex-start;
  }

  .project-hero-badges {
    margin-left: 0;
  }

  .project-detail-side,
  .edit-project-side {
    grid-template-columns: 1fr;
  }

  .project-summary-left {
    grid-template-columns: 1fr;
  }

  .detail-progress-row {
    grid-template-columns: 1fr;
  }

  .history-row {
    grid-template-columns: 14px 34px 1fr;
  }

  .history-row p,
  .history-row small,
  .history-row .visual-badge {
    grid-column: 3;
  }

  .indicator-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .edit-form-grid {
    grid-template-columns: 1fr;
  }

  .edit-progress-control {
    grid-template-columns: 44px 70px 44px;
  }

  .edit-progress-control input[type="range"] {
    grid-column: 1 / -1;
  }

  .action-item {
    grid-template-columns: 22px 1fr;
  }

  .action-item small,
  .action-item .visual-badge {
    grid-column: 2;
  }
}

@media (max-width: 620px) {
  .edit-summary-strip {
    grid-template-columns: 1fr;
  }

  .indicator-grid {
    grid-template-columns: 1fr;
  }

  .section-header-with-action {
    flex-direction: column;
    align-items: flex-start;
  }
}

