/* =========================================================
   PERFIL SUPERIOR
========================================================= */

.top-profile-bar {
  width: 100%;
  display: flex;
  justify-content: flex-end;
  align-items: center;
  margin-bottom: 18px;
  position: relative;
  z-index: 20;
}

.top-profile-spacer {
  flex: 1;
}

.profile-menu-wrapper {
  position: relative;
}

.profile-circle-button {
  width: 46px;
  height: 46px;
  border: none;
  border-radius: 50%;
  background: linear-gradient(135deg, #0f4fc4, #ed1c24);
  color: white;
  display: grid;
  place-items: center;
  font-weight: 900;
  font-size: 15px;
  box-shadow: 0 12px 24px rgba(15, 79, 196, 0.24);
  cursor: pointer;
  transition: 0.18s ease;
}

.profile-circle-button:hover {
  transform: translateY(-1px);
  box-shadow: 0 16px 30px rgba(15, 79, 196, 0.28);
}

.profile-circle-button span {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 255, 255, 0.55);
}

.profile-dropdown {
  position: absolute;
  top: 56px;
  right: 0;
  width: 310px;
  background: white;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.16);
  padding: 16px;
  z-index: 50;
}

.profile-dropdown::before {
  content: "";
  position: absolute;
  top: -8px;
  right: 17px;
  width: 16px;
  height: 16px;
  background: white;
  border-left: 1px solid #e2e8f0;
  border-top: 1px solid #e2e8f0;
  transform: rotate(45deg);
}

.profile-dropdown-header {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 12px;
}

.profile-dropdown-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #0f4fc4, #ed1c24);
  color: white;
  font-weight: 900;
}

.profile-dropdown-header strong {
  display: block;
  color: #0f2442;
  font-size: 14px;
  margin-bottom: 4px;
}

.profile-dropdown-header span {
  display: block;
  color: #64748b;
  font-size: 12px;
  word-break: break-word;
}

.profile-dropdown-info {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}

.profile-dropdown-info span {
  background: #eaf2ff;
  color: #0f4fc4;
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 12px;
  font-weight: 800;
}

.profile-dropdown button {
  width: 100%;
  border: none;
  border-radius: 11px;
  background: #f8fafc;
  color: #0f2442;
  padding: 11px 12px;
  text-align: left;
  font-weight: 800;
  margin-top: 8px;
  cursor: pointer;
}

.profile-dropdown button:hover {
  background: #eef4ff;
  color: #0f4fc4;
}

.profile-dropdown .profile-logout {
  background: #fee2e2;
  color: #991b1b;
}

.profile-dropdown .profile-logout:hover {
  background: #fecaca;
  color: #7f1d1d;
}

