/* =========================================================
   LOGIN REDISEÑADO
========================================================= */

.login-redesign-screen {
  min-height: 100vh;
  display: grid;
  grid-template-columns: minmax(420px, 0.95fr) minmax(520px, 1.05fr);
  background:
    radial-gradient(circle at 82% 12%, rgba(15, 79, 196, 0.09), transparent 26%),
    linear-gradient(135deg, #f7faff 0%, #eef5ff 100%);
  overflow: hidden;
}

.login-brand-side {
  position: relative;
  min-height: 100vh;
  background:
    radial-gradient(circle at 18% 8%, rgba(255, 255, 255, 0.12), transparent 26%),
    radial-gradient(circle at 85% 22%, rgba(237, 28, 36, 0.14), transparent 30%),
    linear-gradient(180deg, #082f73 0%, #06245d 48%, #041943 100%);
  color: white;
  display: flex;
  align-items: center;
  padding: 70px 72px;
  overflow: hidden;
}

.login-brand-side::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 7% 6%, rgba(255, 255, 255, 0.22) 1px, transparent 1px),
    radial-gradient(circle at 88% 84%, rgba(255, 255, 255, 0.16) 1px, transparent 1px);
  background-size: 28px 28px, 30px 30px;
  opacity: 0.5;
}

.login-brand-side::after {
  content: "";
  position: absolute;
  width: 620px;
  height: 620px;
  right: -260px;
  top: -260px;
  border-radius: 50%;
  border: 42px solid rgba(255, 255, 255, 0.16);
}

.login-brand-content {
  position: relative;
  z-index: 2;
  width: min(100%, 620px);
}

.login-logo-card {
  width: 430px;
  max-width: 100%;
  background: transparent;
  border: none;
  border-radius: 0;
  padding: 0;
  box-shadow: none;
  margin-bottom: 48px;
}

.login-brand-logo {
  width: 100%;
  height: auto;
  display: block;
  filter:
    drop-shadow(0 18px 30px rgba(0, 0, 0, 0.34))
