  color: white;
  font-size: clamp(42px, 4.2vw, 64px);
  line-height: 1.05;
  font-weight: 900;
  letter-spacing: -0.04em;
}

.login-red-line {
  width: 76px;
  height: 4px;
  border-radius: 999px;
  background: #ed1c24;
  margin: 28px 0 22px;
}

.login-brand-text p {
  margin: 0;
  color: #e5efff;
  font-size: 18px;
  line-height: 1.55;
  max-width: 560px;
}

.login-feature-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-top: 42px;
}

.login-feature-card {
  min-height: 132px;
  background: rgba(255, 255, 255, 0.11);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 18px;
  padding: 18px;
  backdrop-filter: blur(10px);
}

.login-feature-card div {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.22);
  color: white;
  font-weight: 900;
  font-size: 20px;
  margin-bottom: 14px;
}

.login-feature-card:nth-child(2) div {
  background: rgba(237, 28, 36, 0.72);
}

.login-feature-card strong {
  display: block;
  color: white;
  font-size: 14px;
  margin-bottom: 8px;
}

.login-feature-card p {
  margin: 0;
  color: #dbe8ff;
  font-size: 12px;
  line-height: 1.45;
}

.login-building-graphic {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 72%;
  height: 210px;
  opacity: 0.22;
  background:
    linear-gradient(to top, rgba(255, 255, 255, 0.28), transparent),
    repeating-linear-gradient(
      90deg,
      transparent 0,
      transparent 44px,
      rgba(255, 255, 255, 0.28) 45px,
      rgba(255, 255, 255, 0.28) 46px
    );
  clip-path: polygon(0 42%, 16% 22%, 16% 18%, 43% 18%, 43% 8%, 68% 8%, 68% 22%, 100% 22%, 100% 100%, 0 100%);
}

.login-red-wave {
  position: absolute;
  left: -80px;
  right: -80px;
  bottom: -38px;
  height: 150px;
  background: linear-gradient(135deg, #ed1c24, #ff4b4b);
  transform: rotate(-4deg);
  border-top: 18px solid rgba(255, 255, 255, 0.12);
  opacity: 0.95;
}

.login-form-side {
