  border-radius: 26px;
  box-shadow: 0 30px 80px rgba(15, 23, 42, 0.12);
  padding: 42px;
}

.login-lock-icon {
  width: 78px;
  height: 78px;
  margin: 0 auto 22px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 30px;
}

.login-form-card h2 {
  margin: 0 0 10px;
  text-align: center;
  color: #0f2442;
  font-size: 36px;
  font-weight: 900;
