  box-shadow: none;
  outline: none;
  color: #0f2442;
  font-size: 15px;
  background: transparent;
  padding: 0;
}

.login-input-wrap input:focus {
  border: none;
  box-shadow: none;
}

.login-input-wrap input::placeholder {
  color: #94a3b8;
}

.login-eye-button {
  border: none;
  background: transparent;
  color: #0f4fc4;
  font-weight: 900;
  font-size: 12px;
  padding: 0;
}

.login-options-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin: 8px 0 22px;
}

.login-check {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0;
  color: #344256;
  font-size: 14px;
  font-weight: 600;
}

.login-check input {
  width: 18px;
  height: 18px;
  accent-color: #0f4fc4;
}

.forgot-password-button {
  border: none;
  background: transparent;
  color: #0f4fc4;
  font-weight: 900;
  font-size: 14px;
  padding: 0;
}

.login-error-box {
  background: #fee2e2;
  color: #991b1b;
  border: 1px solid #fecaca;
  border-radius: 12px;
  padding: 12px 14px;
  font-size: 13px;
  margin-bottom: 16px;
}

.login-main-button {
  width: 100%;
  height: 58px;
  border: none;
  border-radius: 12px;
  background: linear-gradient(135deg, #0f4fc4, #0941a5);
  color: white;
  font-size: 16px;
  font-weight: 900;
  box-shadow: 0 16px 30px rgba(15, 79, 196, 0.25);
}

.login-main-button:hover {
  background: linear-gradient(135deg, #ed1c24, #c91820);
  box-shadow: 0 16px 30px rgba(237, 28, 36, 0.23);
}

.login-main-button:disabled {
  opacity: 0.68;
  cursor: not-allowed;
}

.login-help-text {
  margin-top: 28px;
  text-align: center;
  color: #526176;
  font-size: 14px;
}

.login-help-text strong {
  color: #0f4fc4;
}

.login-mini-card {
  position: relative;
  z-index: 1;
  width: min(100%, 540px);
  display: grid;
  grid-template-columns: 62px minmax(0, 1fr) 115px;
  align-items: center;
  gap: 18px;
  background: rgba(255, 255, 255, 0.9);
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  padding: 18px;
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.08);
}

.login-mini-icon {
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 25px;
  font-weight: 900;
}

.login-mini-card strong {
  display: block;
  color: #0f2442;
  font-size: 14px;
  margin-bottom: 5px;
}

.login-mini-card p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.35;
}

.login-mini-illustration {
  height: 58px;
  border: 1px solid #dce6f5;
  border-radius: 10px;
  background: #f8fbff;
  display: flex;
  align-items: end;
  justify-content: center;
  gap: 8px;
  padding: 11px;
}

.login-mini-illustration span {
  width: 16px;
  border-radius: 5px 5px 0 0;
  background: #0f4fc4;
}

.login-mini-illustration span:nth-child(1) {
  height: 22px;
}

.login-mini-illustration span:nth-child(2) {
  height: 35px;
  background: #ed1c24;
}

.login-mini-illustration span:nth-child(3) {
  height: 28px;
}

@media (max-width: 1100px) {
  .login-redesign-screen {
    grid-template-columns: 1fr;
  }

  .login-brand-side {
    min-height: auto;
    padding: 46px 28px;
  }

  .login-feature-grid {
    grid-template-columns: 1fr;
  }

  .login-form-side {
    padding: 34px 22px;
  }
}

@media (max-width: 640px) {
  .login-logo-card {
    width: 100%;
    padding: 20px;
  }

  .login-brand-text h1 {
    font-size: 38px;
  }

  .login-form-card {
    padding: 28px 22px;
    border-radius: 22px;
  }

  .login-form-card h2 {
    font-size: 30px;
  }

  .login-options-row {
    align-items: flex-start;
    flex-direction: column;
  }

  .login-mini-card {
    grid-template-columns: 1fr;
  }

  .login-mini-illustration {
    display: none;
  }
