/* =========================================================
   REDISEÑO MIS PROYECTOS - DASHBOARD COMPACTO
   Compatible con el nuevo MyProjects.jsx
========================================================= */

.metric-action-button {
  width: 100%;
  padding: 0;
  border: none;
  background: transparent;
  text-align: left;
  color: inherit;
}

.metric-action-button .simple-metric {
  height: 100%;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.metric-action-button:hover .simple-metric {
  transform: translateY(-2px);
  border-color: #c8d7ee;
  box-shadow: 0 18px 38px rgba(15, 23, 42, 0.1);
}

.my-metrics-grid {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 18px;
}

.my-metrics-grid .simple-metric {
  min-height: 104px;
  padding: 16px;
  gap: 14px;
  border-radius: 15px;
}

.my-metrics-grid .simple-metric-icon {
  width: 48px;
  height: 48px;
  font-size: 22px;
  flex-shrink: 0;
}

.my-metrics-grid .simple-metric strong {
  font-size: 28px;
  margin-bottom: 5px;
}

.my-metrics-grid .simple-metric h4 {
  font-size: 13px;
  margin-bottom: 4px;
}

.my-metrics-grid .simple-metric p {
  font-size: 11px;
  line-height: 1.35;
}

.my-projects-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 380px;
  gap: 18px;
  align-items: start;
}

.my-projects-main,
.my-projects-side {
  min-width: 0;
}

.my-projects-side {
  display: grid;
  gap: 14px;
  position: sticky;
  top: 24px;
}

.my-projects-workspace {
  padding: 18px;
}

.workspace-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 14px;
}

.workspace-header .section-title-row p {
  margin: 3px 0 0;
  color: #64748b;
  font-size: 13px;
}

.workspace-count {
  min-width: 86px;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 10px 12px;
  background: #f8fbff;
  text-align: center;
}

.workspace-count strong {
  display: block;
  color: #0f4fc4;
  font-size: 24px;
  line-height: 1;
}

.workspace-count span {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
  margin-top: 4px;
}

.workspace-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.project-view-tabs {
  display: inline-flex;
  gap: 6px;
  padding: 5px;
  background: #eef4fb;
  border: 1px solid #dce6f5;
  border-radius: 999px;
}

.project-view-tabs button {
  border: none;
  background: transparent;
  color: #526176;
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 12px;
  font-weight: 900;
}

.project-view-tabs button.active {
  background: white;
  color: #0f4fc4;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
}

.workspace-toolbar .filter-pills {
  gap: 8px;
}

.workspace-toolbar .filter-pills button {
  padding: 8px 14px;
  font-size: 12px;
}

.my-project-card-list,
.compact-project-list {
  display: grid;
  gap: 12px;
}

.my-project-card,
.compact-project-card {
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: linear-gradient(180deg, #ffffff, #fbfdff);
  padding: 15px;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.my-project-card:hover,
.compact-project-card:hover {
  transform: translateY(-1px);
  border-color: #c8d7ee;
  box-shadow: 0 16px 32px rgba(15, 23, 42, 0.08);
}

.my-project-card-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 12px;
}

.project-title-line {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 5px;
}

.project-title-line h3 {
  margin: 0;
  color: #0f2442;
  font-size: 17px;
  line-height: 1.25;
}

.my-project-card-top p {
  margin: 0;
  color: #536176;
  font-size: 13px;
  line-height: 1.45;
  max-width: 820px;
}

.my-project-meta-grid,
.compact-meta-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
  margin: 12px 0;
}

.meta-item {
  border: 1px solid #edf1f7;
  border-radius: 12px;
  background: #ffffff;
  padding: 10px 11px;
  min-width: 0;
}

.meta-item span {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
  margin-bottom: 4px;
}

.meta-item strong {
  display: block;
  color: #0f2442;
  font-size: 12px;
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.my-project-progress-row,
.compact-progress-row {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  margin-top: 10px;
}

.my-project-progress-row > div:first-child {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.my-project-progress-row span {
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
}

.my-project-progress-row strong {
  color: #0f4fc4;
  font-size: 12px;
}

.my-project-card-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 12px;
}

.my-project-card-actions .visual-primary-button {
  padding: 9px 13px;
  font-size: 12px;
  border-radius: 9px;
}

.compact-side-card {
  padding: 16px;
  border-radius: 16px;
}

.compact-side-card .mini-section-header {
  margin-bottom: 12px;
}

.compact-side-card .mini-section-header h3 {
  font-size: 15px;
}

.agenda-button,
.recent-project-button {
  width: 100%;
  text-align: left;
  cursor: pointer;
}

.compact-agenda-list,
.compact-recent-list,
.compact-status-list {
  gap: 9px;
}

.compact-agenda-item {
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  padding: 11px;
  background: #fbfdff;
  transition: 0.18s ease;
}

.compact-agenda-item:hover {
  border-color: #b9cdfa;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.07);
  transform: translateY(-1px);
}

.compact-agenda-item strong {
  display: block;
  font-size: 13px;
  margin-bottom: 3px;
  overflow-wrap: anywhere;
}

.compact-agenda-item span:not(.visual-badge) {
  display: block;
  color: #64748b;
  font-size: 11px;
}

.compact-recent-item {
  padding: 10px;
  border: 1px solid #e5eaf2;
  border-radius: 13px;
  background: #fbfdff;
  transition: 0.18s ease;
}

.compact-recent-item:hover {
  border-color: #b9cdfa;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.07);
  transform: translateY(-1px);
}

.compact-recent-item strong {
  display: block;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.compact-recent-item .recent-icon {
  width: 34px;
  height: 34px;
  border-radius: 9px;
}

.status-distribution-list {
  display: grid;
  gap: 10px;
}

.status-distribution-item,
.compact-status-item {
  display: grid;
  grid-template-columns: minmax(115px, 1fr) minmax(80px, 1.1fr) 38px;
  align-items: center;
  gap: 10px;
}

.status-distribution-item > div:first-child {
  min-width: 0;
}

.status-distribution-item span {
  display: block;
  color: #344256;
  font-size: 12px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.status-distribution-item strong {
  display: block;
  color: #0f2442;
  font-size: 12px;
  margin-top: 2px;
}

.status-distribution-item small {
  color: #64748b;
  font-size: 11px;
  text-align: right;
}

.visual-badge {
  font-size: 11px;
  padding: 6px 9px;
  border-radius: 999px;
}

/* Ajustes para que Mis proyectos no se sienta encimado en pantallas medianas */
@media (max-width: 1500px) {
  .my-metrics-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .my-projects-layout {
    grid-template-columns: minmax(0, 1fr) 340px;
  }
}

@media (max-width: 1250px) {
  .my-projects-layout {
    grid-template-columns: 1fr;
  }

  .my-projects-side {
    position: static;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 1050px) {
  .my-projects-side {
    grid-template-columns: 1fr;
  }

  .my-project-meta-grid,
  .compact-meta-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 800px) {
  .my-metrics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .workspace-header,
  .my-project-card-top {
    flex-direction: column;
  }

  .workspace-count {
    width: 100%;
  }

  .project-view-tabs,
  .workspace-toolbar .filter-pills {
    width: 100%;
  }

  .project-view-tabs button,
  .workspace-toolbar .filter-pills button {
    flex: 1;
  }
}

@media (max-width: 620px) {
  .my-metrics-grid {
    grid-template-columns: 1fr;
  }

  .my-project-meta-grid,
  .compact-meta-grid,
  .my-project-progress-row,
  .compact-progress-row {
    grid-template-columns: 1fr;
  }

  .status-distribution-item,
  .compact-status-item {
    grid-template-columns: 1fr;
  }

  .status-distribution-item small {
    text-align: left;
  }
}



