  color: #0f2442;
  font-size: 30px;
  letter-spacing: -0.03em;
}

.project-detail-topline p {
  margin: 0;
  color: #536176;
  font-size: 15px;
}

.status-pill-select {
  min-width: 190px;
  border-radius: 12px;
  background: #ffffff;
}

.project-hero-overview {
