.hero-meta-item strong {
  display: block;
  color: #0f2442;
  font-size: 12px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.project-hero-illustration {
  position: relative;
  height: 150px;
  border-radius: 36px;
  background:
