}

.illustration-board span:nth-child(2) {
  width: 70%;
}

.illustration-board span:nth-child(3) {
  width: 82%;
}

.illustration-plant {
  position: absolute;
  right: 36px;
  bottom: 34px;
  width: 28px;
  height: 52px;
  border-radius: 999px 999px 6px 6px;
  background: linear-gradient(180deg, #67a7ff, #0f4fc4);
  opacity: 0.75;
}

.redesigned-detail-layout {
  grid-template-columns: minmax(0, 1fr) 380px;
}

.redesigned-detail-side {
  position: sticky;
  top: 24px;
  gap: 14px;
}

.description-focus-card {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr);
  gap: 18px;
  align-items: start;
  border-left: 6px solid #0f4fc4;
  padding: 24px;
}

.description-focus-icon {
  width: 58px;
  height: 58px;
  border-radius: 18px;
  display: grid;
  place-items: center;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 26px;
  font-weight: 900;
}

.prominent-description {
  font-size: 15px;
  line-height: 1.75;
  color: #344256;
  max-width: 1000px;
}

.advances-card {
  padding: 22px;
}

.advances-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
}

.advances-header p {
  margin: -6px 0 0 31px;
  color: #64748b;
  font-size: 13px;
}

.advance-composer {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}

.advance-avatar {
  width: 42px;
  height: 42px;
}

.advance-composer-box {
  border: 1px solid #d9e2ef;
  border-radius: 16px;
  background: #ffffff;
  padding: 13px;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.04);
}

.advance-composer-box textarea {
  min-height: 80px;
  border: none;
  border-radius: 12px;
  padding: 8px;
  resize: vertical;
  box-shadow: none;
}

.advance-composer-box textarea:focus {
  border: none;
  box-shadow: none;
}

.advance-composer-footer {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  border-top: 1px solid #edf1f7;
  padding-top: 12px;
}

.attach-evidence-chip {
  margin: 0;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  width: auto;
  border: 1px solid #b9cdfa;
  border-radius: 10px;
  background: #ffffff;
  color: #0f4fc4;
  padding: 9px 13px;
  font-size: 12px;
  font-weight: 900;
  cursor: pointer;
}

.attach-evidence-chip input {
  display: none;
}

.advance-help-text {
  color: #64748b;
  font-size: 12px;
  margin-right: auto;
}

.publish-advance-button {
  padding: 10px 16px;
  font-size: 12px;
}

.selected-advance-files {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 12px;
}

.selected-advance-files button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid #dbe7ff;
  background: #f8fbff;
  color: #0f2442;
  border-radius: 999px;
  padding: 7px 10px;
  font-size: 12px;
  font-weight: 800;
}

.selected-advance-files span {
  color: #0f4fc4;
  font-size: 10px;
}

.selected-advance-files b {
  color: #ed1c24;
  font-size: 14px;
}

.advance-timeline {
  position: relative;
  display: grid;
  gap: 14px;
  padding-left: 22px;
}

.advance-timeline::before {
  content: "";
  position: absolute;
  left: 5px;
  top: 4px;
  bottom: 12px;
  width: 2px;
  background: #dbe7ff;
}

.advance-item {
  position: relative;
}

.timeline-dot {
  position: absolute;
  left: -22px;
  top: 22px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #0f4fc4;
  box-shadow: 0 0 0 5px #eaf2ff;
}

.advance-entry {
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: linear-gradient(180deg, #ffffff, #fbfdff);
  padding: 15px;
  transition: 0.18s ease;
}

.advance-entry:hover {
  border-color: #c8d7ee;
  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.07);
}

.advance-entry-header {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.advance-entry-header strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
}

.advance-entry-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 4px;
}

.advance-entry-meta small {
  color: #64748b;
  font-size: 11px;
}

.advance-entry > p {
  margin: 0 0 12px 48px;
  color: #344256;
  font-size: 13px;
  line-height: 1.55;
}

.advance-comment-toggle {
  border: 1px solid #dbe7ff;
  border-radius: 10px;
  background: #ffffff;
  color: #0f4fc4;
  padding: 8px 13px;
  font-size: 12px;
  font-weight: 900;
}

.advance-comment-toggle:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.advance-files-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 280px));
  gap: 10px;
  margin: 0 0 12px 48px;
}

.advance-file-chip {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  border: 1px solid #dbe3ec;
  border-radius: 12px;
  background: #ffffff;
  padding: 9px 10px;
  text-decoration: none;
}

.advance-file-chip strong {
  display: block;
  color: #0f2442;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.advance-file-chip small {
  display: block;
  color: #64748b;
  font-size: 11px;
  margin-top: 2px;
}

.advance-entry-actions {
  margin-left: 48px;
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
}

.advance-comment-form {
  display: grid;
  gap: 9px;
  margin: 12px 0 0 48px;
  padding: 12px;
  border-radius: 14px;
  background: #f8fbff;
  border: 1px solid #dbe7ff;
}

.advance-comment-form textarea {
  min-height: 60px;
  font-size: 13px;
}

.advance-comment-form button {
  padding: 9px 12px;
  font-size: 12px;
}

.advance-comments-list {
  display: grid;
  gap: 8px;
  margin: 12px 0 0 48px;
}

.advance-comment {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  gap: 10px;
  border: 1px solid #e5eaf2;
  background: #ffffff;
  border-radius: 12px;
  padding: 10px;
}

.advance-comment .avatar-mini {
  width: 32px;
  height: 32px;
}

.advance-comment strong {
  color: #0f2442;
  font-size: 12px;
}

.advance-comment p {
  margin: 3px 0;
  color: #526176;
  font-size: 12px;
}

.advance-comment small {
  color: #94a3b8;
  font-size: 11px;
}

.formal-log-card {
  padding: 20px;
}

.formal-log-table {
  display: grid;
  gap: 0;
  overflow: hidden;
  border: 1px solid #e5eaf2;
  border-radius: 14px;
}

.formal-log-table-head,
.formal-log-table-row {
  display: grid;
  grid-template-columns: 180px 110px minmax(0, 1fr) 160px;
  gap: 12px;
  align-items: center;
  padding: 12px 14px;
}

.formal-log-table-head {
  background: #f8fafc;
  color: #526176;
  font-size: 12px;
  font-weight: 900;
}

.formal-log-table-row {
  background: #ffffff;
  border-top: 1px solid #e8edf3;
}

.formal-log-table-row > span {
  color: #64748b;
  font-size: 12px;
}

.formal-log-table-row p {
  margin: 0;
  color: #344256;
  font-size: 13px;
  line-height: 1.45;
}

.formal-log-table-row strong {
  color: #0f2442;
  font-size: 12px;
}

.side-compact-card {
  padding: 16px;
  border-radius: 16px;
}

.side-compact-card .detail-section-title {
  margin-bottom: 12px;
}

.side-compact-card .detail-section-title h3 {
  font-size: 15px;
}

.side-card-title-row {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.redesigned-indicator-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.redesigned-indicator-grid .indicator-card {
  min-height: 82px;
  display: grid;
  align-content: center;
  text-align: left;
  padding: 13px;
}

.redesigned-indicator-grid .indicator-card span {
  font-size: 18px;
  margin-bottom: 4px;
}

.redesigned-indicator-grid .indicator-card strong {
  font-size: 22px;
}

.redesigned-indicator-grid .indicator-card small {
  font-weight: 800;
}

.compact-action-header {
  align-items: flex-start;
}

.compact-action-header .visual-outline-button {
  padding: 8px 10px;
  font-size: 12px;
}

.internal-note-preview {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr);
  gap: 10px;
  border: 1px solid #f3d28a;
  border-radius: 14px;
  background: #fffdf6;
  padding: 12px;
}

.internal-note-preview span {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #fff4d8;
  color: #d99a00;
  font-weight: 900;
}

.internal-note-preview p {
  margin: 0;
  color: #6b4d0f;
  font-size: 12px;
  line-height: 1.5;
}

.comment-form-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

@media (max-width: 1500px) {
  .redesigned-detail-layout {
    grid-template-columns: minmax(0, 1fr) 340px;
  }

  .hero-meta-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .project-hero-overview {
    grid-template-columns: minmax(0, 1fr) 180px;
  }
}

@media (max-width: 1250px) {
  .redesigned-detail-layout {
    grid-template-columns: 1fr;
  }

  .redesigned-detail-side {
    position: static;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .project-hero-overview {
    grid-template-columns: 1fr;
  }

  .project-hero-illustration {
    display: none;
  }
}

@media (max-width: 900px) {
  .project-detail-topline,
  .project-title-area,
  .advance-composer {
    grid-template-columns: 1fr;
    flex-direction: column;
  }

  .project-detail-topline {
    display: grid;
  }

  .project-detail-topline .visual-page-actions,
  .project-detail-topline .status-change-select {
    width: 100%;
  }

  .description-focus-card {
    grid-template-columns: 1fr;
  }

  .advance-composer {
    display: grid;
  }

  .advance-entry-header {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  .advance-comment-toggle {
    grid-column: 2;
    width: max-content;
  }

  .advance-entry > p,
  .advance-files-grid,
  .advance-entry-actions,
  .advance-comment-form,
  .advance-comments-list {
    margin-left: 0;
  }

  .formal-log-table-head {
    display: none;
  }

  .formal-log-table-row {
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .redesigned-detail-side {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 620px) {
  .hero-meta-grid,
  .redesigned-indicator-grid {
    grid-template-columns: 1fr;
  }

  .project-hero-overview,
  .description-focus-card,
  .advances-card {
    padding: 16px;
  }

  .advance-composer-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .attach-evidence-chip,
  .publish-advance-button {
    width: 100%;
    justify-content: center;
  }

  .advance-files-grid {
    grid-template-columns: 1fr;
  }
}


