.collaborators-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 370px;
  gap: 20px;
  align-items: start;
}

.collaborators-main-card,
.collaborator-editor-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  box-shadow: 0 16px 38px rgba(15, 23, 42, 0.08);
}

.collaborators-main-card {
  padding: 18px;
  min-width: 0;
}

.collaborators-toolbar {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) 190px 190px 170px auto;
  gap: 12px;
  align-items: center;
  margin-bottom: 18px;
}

.collaborators-toolbar select,
.collaborator-editor-form select {
  height: 46px;
  border: 1px solid #d9e2ef;
  border-radius: 10px;
  background: #ffffff;
  color: #0f2442;
  padding: 0 12px;
  font-weight: 700;
}

.collaborators-search {
  width: 100%;
}

.clear-users-filter {
  height: 46px;
  margin: 0;
}

.collaborators-table {
  min-width: 1040px;
}

.collaborators-table tbody tr {
  cursor: pointer;
  transition: 0.15s ease;
}

.collaborators-table tbody tr:hover {
  background: #f8fbff;
}

.collaborators-table tbody tr.selected-user-row {
  background: #eef5ff;
  outline: 1px solid #b9cdfa;
  outline-offset: -1px;
}

.user-name-cell {
  display: flex;
  align-items: center;
  gap: 10px;
}

.user-name-cell strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
}

.user-name-cell small {
  display: block;
  color: #94a3b8;
  font-size: 10px;
  margin-top: 2px;
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.area-chip,
.role-chip,
.status-chip {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  max-width: 190px;
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.2;
  white-space: normal;
}

.area-blue {
  background: #eaf2ff;
  color: #0f4fc4;
  border: 1px solid #bad0ff;
}

.area-purple {
  background: #ede9fe;
  color: #7c3aed;
  border: 1px solid #ddd6fe;
}

.area-teal {
  background: #ccfbf1;
  color: #0f9488;
  border: 1px solid #99f6e4;
}

.area-red {
  background: #fee2e2;
  color: #ed1c24;
  border: 1px solid #fecaca;
}

.area-orange {
  background: #ffedd5;
  color: #f97316;
  border: 1px solid #fed7aa;
}

.area-gold {
  background: #fff4d8;
  color: #d99a00;
  border: 1px solid #ffe8a3;
}

.area-gray {
  background: #f1f5f9;
  color: #475569;
  border: 1px solid #e2e8f0;
}

.role-admin {
  background: #ede9fe;
  color: #7c3aed;
  border: 1px solid #ddd6fe;
}

.role-collaborator {
  background: #eaf2ff;
  color: #0f4fc4;
  border: 1px solid #bad0ff;
}

.role-requester {
  background: #fff4d8;
  color: #d99a00;
  border: 1px solid #ffe8a3;
}

.status-chip::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  margin-right: 6px;
  background: currentColor;
}

.status-active {
  background: #dcfce7;
  color: #16a34a;
  border: 1px solid #bbf7d0;
}

.status-inactive {
  background: #f1f5f9;
  color: #64748b;
  border: 1px solid #e2e8f0;
}

.status-deleted {
  background: #fee2e2;
  color: #b42318;
  border: 1px solid #fecaca;
}

.table-dot-button {
  border: none;
  background: transparent;
  color: #0f2442;
  font-size: 22px;
  font-weight: 900;
  padding: 4px 8px;
  border-radius: 8px;
}

.table-dot-button:hover {
  background: #eef4ff;
  color: #0f4fc4;
}

.collaborators-table-footer {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
  padding: 14px 4px 2px;
}

.collaborator-editor-card {
  padding: 20px;
  position: sticky;
  top: 24px;
}

.collaborator-editor-header {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 14px;
  align-items: center;
  padding-bottom: 16px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 16px;
}

.collaborator-editor-header h3 {
  margin: 0 0 6px;
  color: #0f2442;
  font-size: 18px;
}

.collaborator-editor-header strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
  margin-bottom: 3px;
}

.collaborator-editor-header span {
  display: block;
  color: #64748b;
  font-size: 12px;
  word-break: break-word;
}

.small-avatar {
  width: 58px;
  height: 58px;
  font-size: 17px;
}

.collaborator-editor-form {
  display: grid;
  gap: 12px;
}

.collaborator-editor-form label {
  margin: 0;
  color: #0f2442;
  font-size: 12px;
  font-weight: 900;
}

.collaborator-editor-form input,
.collaborator-editor-form textarea {
  margin-top: 7px;
  width: 100%;
  border: 1px solid #d9e2ef;
  border-radius: 10px;
  background: white;
  color: #0f2442;
  padding: 12px;
  font-size: 13px;
}

.collaborator-editor-form textarea {
  min-height: 88px;
  resize: vertical;
}

.collaborator-editor-actions {
  display: grid;
  gap: 10px;
  margin-top: 16px;
}

.collaborator-editor-actions button {
  width: 100%;
  justify-content: center;
}

.deactivate-user-button,
.restore-user-button,
.delete-user-button {
  border-radius: 10px;
  padding: 12px 14px;
  font-weight: 900;
  font-size: 13px;
  background: white;
}

.deactivate-user-button {
  color: #f97316;
  border: 1px solid #fed7aa;
}

.deactivate-user-button:hover {
  background: #fff7ed;
}

.restore-user-button {
  color: #16a34a;
  border: 1px solid #bbf7d0;
}

.restore-user-button:hover {
  background: #f0fdf4;
}

.delete-user-button {
  color: #b42318;
  border: 1px solid #fecaca;
}

.delete-user-button:hover {
  background: #fff5f5;
}

.new-user-hint-card {
  margin-top: 16px;
  border: 1px dashed #bad0ff;
  border-radius: 14px;
  background: #f8fbff;
  padding: 13px;
}

.new-user-hint-card strong {
  display: block;
  color: #0f4fc4;
  font-size: 13px;
  margin-bottom: 5px;
}

.new-user-hint-card p {
  margin: 0;
  color: #526176;
  font-size: 12px;
  line-height: 1.45;
}

@media (max-width: 1450px) {
  .collaborators-layout {
    grid-template-columns: 1fr;
  }

  .collaborator-editor-card {
    position: static;
  }

  .collaborators-toolbar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .collaborators-search {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1100px) {
  .collaborator-metrics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 700px) {
  .collaborator-metrics-grid,
  .collaborators-toolbar {
    grid-template-columns: 1fr;
  }

  .collaborators-table-footer {
    flex-direction: column;
  }
}

/* =========================================================
   MODAL CREAR USUARIO
========================================================= */

.modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(15, 23, 42, 0.45);
  backdrop-filter: blur(4px);
}

.create-user-modal {
  width: min(760px, 100%);
  max-height: 92vh;
  overflow-y: auto;
  background: #ffffff;
  border-radius: 22px;
  border: 1px solid #e2e8f0;
  box-shadow: 0 30px 90px rgba(15, 23, 42, 0.26);
  padding: 24px;
}

.create-user-modal-header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
  border-bottom: 1px solid #e5eaf2;
  padding-bottom: 16px;
  margin-bottom: 18px;
}

.create-user-modal-header h3 {
  margin: 0 0 5px;
  color: #0f2442;
  font-size: 22px;
}

.create-user-modal-header p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.45;
}

.create-user-modal-header button {
  width: 36px;
  height: 36px;
  border: none;
  border-radius: 50%;
  background: #f1f5f9;
  color: #0f2442;
  font-size: 24px;
  line-height: 1;
}

.create-user-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.create-user-form label {
  margin: 0;
  display: grid;
  gap: 8px;
  color: #0f2442;
  font-size: 13px;
  font-weight: 900;
}

.create-user-form label.full {
  grid-column: 1 / -1;
}

.create-user-form input,
.create-user-form select,
.create-user-form textarea {
  width: 100%;
  border: 1px solid #d9e2ef;
  border-radius: 11px;
  padding: 12px;
  background: white;
  color: #0f2442;
  font-size: 14px;
}

.create-user-form textarea {
  min-height: 90px;
  resize: vertical;
}

.temporary-password-box {
  margin-top: 18px;
  border: 1px solid #bbf7d0;
  background: #f0fdf4;
  color: #166534;
  border-radius: 14px;
  padding: 14px;
}

.temporary-password-box strong {
  display: block;
  margin-bottom: 8px;
}

.temporary-password-box code {
  display: block;
  width: fit-content;
  max-width: 100%;
  overflow-x: auto;
  background: #ffffff;
  border: 1px solid #bbf7d0;
  border-radius: 10px;
  padding: 10px 12px;
  color: #0f2442;
  font-size: 16px;
  font-weight: 900;
}

.temporary-password-box p {
  margin: 10px 0 0;
  color: #166534;
  font-size: 12px;
  line-height: 1.45;
}

.create-user-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  flex-wrap: wrap;
  border-top: 1px solid #e5eaf2;
  padding-top: 18px;
  margin-top: 20px;
}

@media (max-width: 700px) {
  .create-user-form {
    grid-template-columns: 1fr;
  }

  .create-user-modal-actions {
    flex-direction: column;
  }

  .create-user-modal-actions button {
    width: 100%;
  }
}

/* =========================================================
   REDISEÑO VISUAL: DEPARTAMENTOS
========================================================= */

.departments-admin-redesign {
  display: grid;
  gap: 18px;
}

.departments-hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 4px;
}

.departments-hero h2 {
  margin: 4px 0 6px;
  color: #0f2442;
  font-size: 30px;
  letter-spacing: -0.03em;
}

.departments-hero p {
  margin: 0;
  color: #536176;
  font-size: 15px;
  line-height: 1.45;
}

.departments-hero-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  flex-wrap: wrap;
}

.departments-metrics-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.department-metric-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 18px;
  min-height: 116px;
  background: #ffffff;
  border: 1px solid #e9eef6;
  border-radius: 18px;
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.07);
  padding: 20px;
  overflow: hidden;
}

.department-metric-card::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 5px;
}

.department-metric-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 27px;
  font-weight: 900;
  flex-shrink: 0;
}

.department-metric-card span {
  display: block;
  color: #344256;
  font-size: 13px;
  font-weight: 900;
  margin-bottom: 6px;
}

.department-metric-card strong {
  display: block;
  color: #0f2442;
  font-size: 34px;
  line-height: 1;
  margin-bottom: 8px;
}

.department-metric-card p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
}

.department-metric-blue .department-metric-icon {
  background: #eaf2ff;
  color: #0f4fc4;
}

.department-metric-blue::after {
  background: #0f4fc4;
}

.department-metric-green .department-metric-icon {
  background: #dcfce7;
  color: #16a34a;
}

.department-metric-green::after {
  background: #16a34a;
}

.department-metric-red .department-metric-icon {
  background: #fee2e2;
  color: #ed1c24;
}

.department-metric-red::after {
  background: #ed1c24;
}

.departments-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 420px;
  gap: 20px;
  align-items: start;
}

.departments-list-panel,
.department-editor-panel,
.departments-distribution-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  box-shadow: 0 16px 38px rgba(15, 23, 42, 0.08);
}

.departments-list-panel {
  padding: 18px;
  min-width: 0;
}

.department-editor-panel {
  padding: 20px;
  position: sticky;
  top: 24px;
}

.departments-toolbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding-bottom: 16px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 16px;
}

.departments-toolbar h3,
.departments-mini-header h3,
.department-editor-header h3 {
  margin: 0 0 5px;
  color: #0f2442;
  font-size: 18px;
}

.departments-toolbar p,
.departments-mini-header p,
.department-editor-header p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.45;
}

.departments-toolbar-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.departments-search {
  width: 290px;
}

.departments-toolbar select {
  width: 150px;
  height: 46px;
  border: 1px solid #d9e2ef;
  border-radius: 10px;
  background: #ffffff;
  color: #0f2442;
  padding: 0 12px;
  font-weight: 800;
}

.department-card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(280px, 1fr));
  gap: 14px;
}

.department-card-visual {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: linear-gradient(180deg, #ffffff, #fbfdff);
  padding: 14px;
  transition: 0.18s ease;
  cursor: pointer;
}

.department-card-visual:hover {
  border-color: #b9cdfa;
  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.08);
  transform: translateY(-1px);
}

.department-card-visual.selected {
  border-color: #0f4fc4;
  box-shadow: 0 0 0 3px rgba(15, 79, 196, 0.12),
    0 14px 30px rgba(15, 23, 42, 0.08);
}

.department-card-visual.preview {
  cursor: default;
  box-shadow: none;
  transform: none;
}

.department-card-visual.preview:hover {
  border-color: #e2e8f0;
  box-shadow: none;
  transform: none;
}

.department-card-icon,
.department-editor-icon {
  display: grid;
  place-items: center;
  border-radius: 16px;
  color: #ffffff;
  font-weight: 900;
  flex-shrink: 0;
}

.department-card-icon {
  width: 58px;
  height: 58px;
  font-size: 27px;
}

.department-editor-icon {
  width: 60px;
  height: 60px;
  font-size: 28px;
}

.department-purple {
  background: linear-gradient(135deg, #8b5cf6, #6d28d9);
}

.department-blue {
  background: linear-gradient(135deg, #38bdf8, #0f4fc4);
}

.department-orange {
  background: linear-gradient(135deg, #fb923c, #f97316);
}

.department-pink {
  background: linear-gradient(135deg, #fb7185, #db2777);
}

.department-teal {
  background: linear-gradient(135deg, #2dd4bf, #0f9488);
}

.department-indigo {
  background: linear-gradient(135deg, #6366f1, #3730a3);
}

.department-gold {
  background: linear-gradient(135deg, #facc15, #d99a00);
}

.department-gray {
  background: linear-gradient(135deg, #94a3b8, #475569);
}

.department-card-content {
  min-width: 0;
}

.department-card-title-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 7px;
}

.department-card-title-row h4 {
  margin: 0;
  color: #0f2442;
  font-size: 15px;
  line-height: 1.25;
}

.department-status-badge {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.department-status-badge.active {
  background: #dcfce7;
  color: #16a34a;
}

.department-status-badge.inactive {
  background: #fee2e2;
  color: #ed1c24;
}

.department-card-content p {
  margin: 0 0 10px;
  color: #526176;
  font-size: 12px;
  line-height: 1.45;
  display: -webkit-box;
  line-clamp: 2;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.department-card-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.department-card-meta span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: #64748b;
  background: #f8fafc;
  border: 1px solid #e5eaf2;
  border-radius: 999px;
  padding: 5px 8px;
  font-size: 11px;
  font-weight: 800;
}

.department-card-actions {
  display: grid;
  gap: 8px;
}

.department-card-actions button {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border: 1px solid #dbe7ff;
  background: #ffffff;
  color: #0f4fc4;
  border-radius: 10px;
  font-weight: 900;
  transition: 0.16s ease;
}

.department-card-actions button:hover {
  background: #eef5ff;
}

.departments-empty-card {
  min-height: 280px;
  display: grid;
  place-items: center;
  text-align: center;
  color: #64748b;
}

.departments-empty-card div {
  color: #d1d8e2;
  font-size: 58px;
  line-height: 1;
}

.departments-empty-card p {
  margin: 8px 0 0;
  color: #64748b;
}

.departments-distribution-card {
  margin-top: 16px;
  padding: 18px;
}

.departments-mini-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
}

.departments-mini-header > span {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  background: #eaf2ff;
  color: #0f4fc4;
  padding: 7px 11px;
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
}

.departments-distribution-list {
  display: grid;
  gap: 11px;
}

.departments-distribution-row {
  display: grid;
  grid-template-columns: minmax(130px, 0.8fr) minmax(120px, 1fr) 76px;
  align-items: center;
  gap: 12px;
}

.departments-distribution-row span {
  color: #344256;
  font-size: 12px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.departments-distribution-row strong {
  color: #64748b;
  font-size: 11px;
  text-align: right;
}

.departments-distribution-track {
  height: 8px;
  border-radius: 999px;
  background: #e5eaf2;
  overflow: hidden;
}

.departments-distribution-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #0f4fc4, #38bdf8);
}

.departments-distribution-fill.inactive {
  background: linear-gradient(90deg, #94a3b8, #cbd5e1);
}

.departments-muted-text {
  margin: 0;
  color: #64748b;
  font-size: 13px;
}

.department-editor-header {
  display: grid;
  grid-template-columns: 60px minmax(0, 1fr);
  gap: 14px;
  align-items: center;
  padding-bottom: 16px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 16px;
}

.department-editor-form {
  display: grid;
  gap: 14px;
}

.department-editor-form label {
  margin: 0;
  display: grid;
  gap: 8px;
}

.department-editor-form label > span,
.department-toggle-row span,
.department-editor-preview > span {
  color: #0f2442;
  font-size: 12px;
  font-weight: 900;
}

.department-editor-form input,
.department-editor-form textarea {
  width: 100%;
  border: 1px solid #d9e2ef;
  border-radius: 11px;
  background: #ffffff;
  color: #0f2442;
  padding: 12px;
  font-size: 13px;
}

.department-editor-form textarea {
  min-height: 94px;
  resize: vertical;
}

.department-toggle-row {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px !important;
  border: 1px solid #e5eaf2;
  background: #fbfdff;
  border-radius: 14px;
  padding: 13px;
}

.department-toggle-row small {
  display: block;
  margin-top: 4px;
  color: #64748b;
  font-size: 11px;
  line-height: 1.35;
}

.department-toggle-row input[type="checkbox"] {
  width: 44px;
  height: 24px;
  accent-color: #0f4fc4;
}

.department-editor-preview {
  display: grid;
  gap: 10px;
  border: 1px dashed #bad0ff;
  border-radius: 16px;
  background: #f8fbff;
  padding: 13px;
}

.department-editor-preview .department-card-visual {
  grid-template-columns: 50px minmax(0, 1fr);
  padding: 12px;
}

.department-editor-preview .department-card-icon {
  width: 50px;
  height: 50px;
  font-size: 22px;
}

.department-editor-preview .department-card-actions {
  display: none;
}

.department-editor-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding-top: 4px;
}

.department-editor-actions button {
  justify-content: center;
}

@media (max-width: 1450px) {
  .departments-workspace {
    grid-template-columns: 1fr;
  }

  .department-editor-panel {
    position: static;
  }
}

@media (max-width: 1200px) {
  .departments-metrics-grid {
    grid-template-columns: repeat(3, minmax(180px, 1fr));
    overflow-x: auto;
    padding-bottom: 4px;
  }

  .departments-toolbar {
    flex-direction: column;
  }

  .departments-toolbar-actions,
  .departments-search {
    width: 100%;
  }

  .departments-toolbar select {
    width: 180px;
  }
}

@media (max-width: 900px) {
  .departments-hero {
    flex-direction: column;
  }

  .departments-hero-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .department-card-grid {
    grid-template-columns: 1fr;
  }

  .department-card-visual {
    grid-template-columns: 54px minmax(0, 1fr);
  }

  .department-card-actions {
    grid-column: 1 / -1;
    display: flex;
    justify-content: flex-end;
  }

  .departments-distribution-row {
    grid-template-columns: 1fr;
    gap: 7px;
  }

  .departments-distribution-row strong {
    text-align: left;
  }
}

@media (max-width: 650px) {
  .departments-metrics-grid {
    grid-template-columns: 1fr;
    overflow-x: visible;
  }

  .departments-hero-actions,
  .departments-toolbar-actions,
  .department-editor-actions {
    grid-template-columns: 1fr;
    display: grid;
  }

  .departments-toolbar select {
    width: 100%;
  }

  .department-editor-header {
    grid-template-columns: 1fr;
  }

  .department-editor-icon {
    width: 56px;
    height: 56px;
  }
}

/* =========================
   SOPORTE TÉCNICO
========================= */

.technical-support-page {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.technical-hero {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: center;
  padding: 28px;
  border-radius: 28px;
  background:
    radial-gradient(circle at top left, rgba(37, 99, 235, 0.18), transparent 36%),
    linear-gradient(135deg, #0f172a, #1e3a8a 52%, #7f1d1d);
  color: white;
  box-shadow: 0 24px 55px rgba(15, 23, 42, 0.22);
}

.technical-hero h1 {
  margin: 4px 0 8px;
  font-size: clamp(26px, 4vw, 40px);
  letter-spacing: -0.04em;
}

.technical-hero p {
  max-width: 720px;
  margin: 0;
  color: rgba(255, 255, 255, 0.78);
  line-height: 1.6;
}

.section-kicker {
  margin: 0;
  color: #bfdbfe !important;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.primary-button {
  border: none;
  border-radius: 999px;
  padding: 12px 18px;
  background: white;
  color: #1e3a8a;
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
  white-space: nowrap;
  box-shadow: 0 16px 30px rgba(15, 23, 42, 0.24);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.primary-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 20px 34px rgba(15, 23, 42, 0.3);
}

.technical-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.technical-summary-card {
  padding: 20px;
  border: 1px solid rgba(226, 232, 240, 0.95);
  border-radius: 24px;
  background: white;
  box-shadow: 0 16px 38px rgba(15, 23, 42, 0.08);
}

.technical-summary-card span {
  display: block;
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.technical-summary-card strong {
  display: block;
  margin-top: 8px;
  color: #0f172a;
  font-size: 34px;
  line-height: 1;
}

.technical-summary-card p {
  margin: 10px 0 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.45;
}

.technical-summary-card.warning {
  background: linear-gradient(180deg, #fff7ed, white);
  border-color: #fed7aa;
}

.technical-summary-card.muted {
  background: linear-gradient(180deg, #f8fafc, white);
}

.technical-panel {
  padding: 22px;
  border: 1px solid rgba(226, 232, 240, 0.95);
  border-radius: 28px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.08);
}

.technical-panel-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 18px;
}

.technical-panel-header h2 {
  margin: 0;
  color: #0f172a;
  font-size: 22px;
  letter-spacing: -0.03em;
}

.technical-panel-header p {
  margin: 6px 0 0;
  color: #64748b;
  font-size: 14px;
}

.technical-filters {
  display: grid;
  grid-template-columns: 1.7fr 0.8fr 0.8fr;
  gap: 12px;
  margin-bottom: 20px;
}

.technical-filters input,
.technical-filters select {
  width: 100%;
  min-height: 44px;
  border: 1px solid #dbe3ef;
  border-radius: 16px;
  background: #f8fafc;
  color: #0f172a;
  padding: 0 14px;
  font-size: 14px;
  outline: none;
}

.technical-filters input:focus,
.technical-filters select:focus {
  border-color: #2563eb;
  box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
}

.technical-assets-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.technical-asset-card {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 18px;
  border: 1px solid #e2e8f0;
  border-radius: 24px;
  background:
    linear-gradient(180deg, rgba(248, 250, 252, 0.92), white);
  box-shadow: 0 14px 32px rgba(15, 23, 42, 0.07);
}

.technical-asset-top {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: flex-start;
}

.asset-tag {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: 5px 9px;
  border-radius: 999px;
  background: #e0ecff;
  color: #1d4ed8;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.05em;
}

.technical-asset-card h3 {
  margin: 9px 0 0;
  color: #0f172a;
  font-size: 17px;
  line-height: 1.25;
  letter-spacing: -0.03em;
}

.asset-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: fit-content;
  padding: 6px 10px;
  border-radius: 999px;
  background: #e2e8f0;
  color: #334155;
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.asset-status.activo {
  background: #dcfce7;
  color: #166534;
}

.asset-status.en-reparación,
.asset-status.en-mantenimiento {
  background: #ffedd5;
  color: #9a3412;
}

.asset-status.prestado {
  background: #dbeafe;
  color: #1d4ed8;
}

.asset-status.guardado {
  background: #f1f5f9;
  color: #475569;
}

.asset-status.dado-de-baja {
  background: #fee2e2;
  color: #991b1b;
}

.technical-asset-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.technical-asset-meta span {
  padding: 5px 8px;
  border-radius: 999px;
  background: #f1f5f9;
  color: #475569;
  font-size: 12px;
  font-weight: 700;
}

.technical-asset-details {
  display: grid;
  gap: 6px;
}

.technical-asset-details p {
  margin: 0;
  color: #475569;
  font-size: 13px;
  line-height: 1.35;
}

.technical-asset-details strong {
  color: #0f172a;
}

.technical-notes {
  margin: 0;
  padding: 12px;
  border-radius: 16px;
  background: #f8fafc;
  color: #64748b;
  font-size: 13px;
  line-height: 1.45;
}

.technical-asset-actions {
  display: flex;
  gap: 8px;
  margin-top: auto;
}

.technical-asset-actions button {
  flex: 1;
  border: 1px solid #dbe3ef;
  border-radius: 14px;
  background: white;
  color: #334155;
  padding: 9px 10px;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease;
}

.technical-asset-actions button:hover {
  background: #f8fafc;
  border-color: #bfdbfe;
  transform: translateY(-1px);
}

.empty-state {
  padding: 36px 18px;
  text-align: center;
  color: #64748b;
}

.empty-state h3 {
  margin: 0 0 6px;
  color: #0f172a;
}

.empty-state p {
  margin: 0;
}

@media (max-width: 1100px) {
  .technical-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .technical-assets-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .technical-filters {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .technical-hero {
    flex-direction: column;
    align-items: flex-start;
    padding: 22px;
  }

  .technical-summary-grid,
  .technical-assets-grid {
    grid-template-columns: 1fr;
  }

  .primary-button {
    width: 100%;
  }
}

/* =========================================================
   SOPORTE TÉCNICO - BITÁCORA VISUAL Y MOVIMIENTOS
========================================================= */

.technical-history-panel {
  position: relative;
  overflow: hidden;
}

.technical-history-panel::before {
  content: "";
  position: absolute;
  top: -120px;
  right: -120px;
  width: 320px;
  height: 320px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(37, 99, 235, 0.09), transparent 68%);
  pointer-events: none;
}

.technical-history-panel > * {
  position: relative;
  z-index: 1;
}

.technical-history-panel .technical-panel-header {
  align-items: center;
}

.technical-history-panel .technical-form-actions {
  margin: 0;
  padding: 0;
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
}

.technical-history-panel .technical-asset-details {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 20px;
}

.technical-history-panel .technical-asset-details p {
  padding: 12px;
  border: 1px solid #e5eaf2;
  border-radius: 16px;
  background: #f8fafc;
}

.technical-timeline {
  position: relative;
  display: grid;
  gap: 16px;
  padding-left: 36px;
  margin-top: 18px;
}

.technical-timeline::before {
  content: "";
  position: absolute;
  left: 15px;
  top: 10px;
  bottom: 10px;
  width: 3px;
  border-radius: 999px;
  background: linear-gradient(180deg, #0f4fc4, #dbeafe);
}

.technical-timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr);
  gap: 14px;
  align-items: flex-start;
}

.technical-timeline-marker {
  position: relative;
  z-index: 2;
  width: 34px;
  height: 34px;
  margin-left: -36px;
  border: 4px solid #ffffff;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #0f4fc4, #1e3a8a);
  color: white;
  font-size: 14px;
  font-weight: 900;
  box-shadow: 0 10px 22px rgba(15, 79, 196, 0.22);
}

.technical-timeline-content {
  min-width: 0;
  padding: 16px;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: linear-gradient(180deg, #ffffff, #fbfdff);
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
}

.technical-timeline-top {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: flex-start;
  margin-bottom: 10px;
}

.technical-timeline-top h3 {
  margin: 6px 0 0;
  color: #0f172a;
  font-size: 16px;
  line-height: 1.25;
  letter-spacing: -0.02em;
}

.technical-log-type {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border-radius: 999px;
  background: #eaf2ff;
  color: #0f4fc4;
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 900;
}

.technical-log-date {
  flex-shrink: 0;
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
  text-align: right;
  white-space: nowrap;
}

.technical-log-description {
  margin: 0 0 12px;
  color: #475569;
  font-size: 13px;
  line-height: 1.55;
}

.technical-change-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  width: fit-content;
  max-width: 100%;
  margin-top: 8px;
  padding: 8px 10px;
  border: 1px solid #dbeafe;
  border-radius: 999px;
  background: #f8fbff;
  color: #334155;
  font-size: 12px;
  font-weight: 800;
}

.technical-change-row strong {
  color: #0f172a;
}

.technical-change-row span:nth-child(2),
.technical-change-row span:nth-child(4) {
  padding: 4px 8px;
  border-radius: 999px;
  background: #eef4ff;
  color: #0f4fc4;
}

.technical-change-row span:nth-child(3) {
  color: #94a3b8;
  font-weight: 900;
}

.technical-history-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 12px;
}

.technical-history-meta span {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border-radius: 999px;
  background: #f1f5f9;
  color: #64748b;
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 800;
}

.technical-form {
  display: grid;
  gap: 18px;
}

.technical-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.technical-form-grid label {
  margin: 0;
  display: grid;
  gap: 8px;
  color: #0f172a;
  font-size: 13px;
  font-weight: 900;
}

.technical-form-grid input,
.technical-form-grid select,
.technical-form-grid textarea {
  width: 100%;
  border: 1px solid #dbe3ef;
  border-radius: 14px;
  background: #ffffff;
  color: #0f172a;
  padding: 12px 14px;
  font-size: 14px;
}

.technical-form-grid input:focus,
.technical-form-grid select:focus,
.technical-form-grid textarea:focus {
  outline: none;
  border-color: #2563eb;
  box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
}

.technical-form-full {
  grid-column: 1 / -1;
}

.technical-form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 4px;
}

.technical-form-actions button:not(.primary-button):not(.visual-outline-button) {
  border: 1px solid #dbe3ef;
  border-radius: 999px;
  background: white;
  color: #334155;
  padding: 12px 18px;
  font-size: 14px;
  font-weight: 800;
}

.technical-form-actions button:disabled,
.technical-asset-actions button:disabled,
.visual-outline-button:disabled,
.primary-button:disabled {
  opacity: 0.62;
  cursor: not-allowed;
  transform: none;
}

.form-error {
  padding: 12px 14px;
  border: 1px solid #fecaca;
  border-radius: 14px;
  background: #fee2e2;
  color: #991b1b;
  font-size: 13px;
  font-weight: 700;
}

@media (max-width: 1200px) {
  .technical-history-panel .technical-asset-details {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .technical-timeline-top {
    flex-direction: column;
  }

  .technical-log-date {
    text-align: left;
    white-space: normal;
  }
}

@media (max-width: 850px) {
  .technical-form-grid {
    grid-template-columns: 1fr;
  }

  .technical-form-full {
    grid-column: auto;
  }

  .technical-history-panel .technical-panel-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .technical-history-panel .technical-form-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .technical-history-panel .technical-form-actions button {
    width: 100%;
  }

  .technical-history-panel .technical-asset-details {
    grid-template-columns: 1fr;
  }

  .technical-timeline {
    padding-left: 26px;
  }

  .technical-timeline::before {
    left: 11px;
  }

  .technical-timeline-item {
    grid-template-columns: 32px minmax(0, 1fr);
    gap: 8px;
  }

  .technical-timeline-marker {
    width: 30px;
    height: 30px;
    margin-left: -26px;
    font-size: 12px;
  }
}

@media (max-width: 640px) {
  .technical-asset-actions {
    flex-direction: column;
  }

  .technical-change-row {
    width: 100%;
    border-radius: 16px;
  }

  .technical-change-row span:nth-child(2),
  .technical-change-row span:nth-child(4) {
    max-width: 100%;
    overflow-wrap: anywhere;
  }

  .technical-form-actions {
    flex-direction: column;
  }

  .technical-form-actions button,
  .technical-form-actions .primary-button {
    width: 100%;
  }
}

/* =========================================================
   SOPORTE TÉCNICO - ALERTAS Y CHECKLISTS DE MANTENIMIENTO
========================================================= */

.technical-alert-strip {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  padding: 18px 20px;
  border: 1px solid #fecaca;
  border-left: 7px solid #ed1c24;
  border-radius: 22px;
  background:
    radial-gradient(circle at top right, rgba(237, 28, 36, 0.12), transparent 28%),
    linear-gradient(135deg, #fff5f5, #fff7ed);
  box-shadow: 0 18px 42px rgba(127, 29, 29, 0.12);
}

.technical-alert-main {
  display: flex;
  align-items: center;
  gap: 14px;
}

.technical-alert-main > span {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #fee2e2;
  color: #b42318;
  font-size: 26px;
  flex-shrink: 0;
}

.technical-alert-main strong {
  display: block;
  color: #7f1d1d;
  font-size: 16px;
  margin-bottom: 4px;
}

.technical-alert-main p {
  margin: 0;
  color: #9a3412;
  font-size: 13px;
  line-height: 1.45;
}

.technical-alert-stats {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.technical-alert-stats div {
  min-width: 92px;
  border-radius: 16px;
  padding: 10px 12px;
  text-align: center;
  border: 1px solid transparent;
  background: #ffffff;
}

.technical-alert-stats strong {
  display: block;
  font-size: 26px;
  line-height: 1;
  margin-bottom: 5px;
}

.technical-alert-stats span {
  display: block;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.technical-alert-stats .critical {
  color: #b42318;
  border-color: #fecaca;
  background: #fff1f1;
}

.technical-alert-stats .today {
  color: #c2410c;
  border-color: #fed7aa;
  background: #fff7ed;
}

.technical-alert-stats .soon {
  color: #b45309;
  border-color: #fde68a;
  background: #fffbeb;
}

.danger-summary {
  background: linear-gradient(180deg, #fff1f1, #ffffff) !important;
  border-color: #fecaca !important;
}

.maintenance-panel-highlight {
  border-color: #dbeafe;
  background:
    radial-gradient(circle at top right, rgba(15, 79, 196, 0.05), transparent 28%),
    rgba(255, 255, 255, 0.96);
}

.maintenance-card {
  position: relative;
  overflow: hidden;
}

.maintenance-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 6px;
  background: #94a3b8;
}

.maintenance-card.urgency-overdue {
  border-color: #fecaca;
  background: linear-gradient(180deg, #fff5f5, #ffffff);
  box-shadow: 0 18px 38px rgba(180, 35, 24, 0.12);
}

.maintenance-card.urgency-overdue::before {
  background: #ed1c24;
}

.maintenance-card.urgency-today {
  border-color: #fed7aa;
  background: linear-gradient(180deg, #fff7ed, #ffffff);
  box-shadow: 0 18px 38px rgba(249, 115, 22, 0.12);
}

.maintenance-card.urgency-today::before {
  background: #f97316;
}

.maintenance-card.urgency-soon {
  border-color: #fde68a;
  background: linear-gradient(180deg, #fffbeb, #ffffff);
}

.maintenance-card.urgency-soon::before {
  background: #d99a00;
}

.maintenance-card.urgency-future::before {
  background: #0f4fc4;
}

.maintenance-urgency-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: fit-content;
  max-width: 140px;
  border-radius: 999px;
  padding: 7px 10px;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.2;
  text-align: center;
  white-space: normal;
}

.maintenance-urgency-badge.overdue {
  background: #fee2e2;
  color: #991b1b;
  border: 1px solid #fecaca;
}

.maintenance-urgency-badge.today {
  background: #ffedd5;
  color: #9a3412;
  border: 1px solid #fed7aa;
}

.maintenance-urgency-badge.soon {
  background: #fff4d8;
  color: #92400e;
  border: 1px solid #fde68a;
}

.maintenance-urgency-badge.future,
.maintenance-urgency-badge.unknown {
  background: #eaf2ff;
  color: #0f4fc4;
  border: 1px solid #bad0ff;
}

.maintenance-template-preview {
  border: 1px dashed #bad0ff;
  border-radius: 14px;
  background: #f8fbff;
  padding: 10px 12px;
}

.maintenance-template-preview strong {
  display: block;
  color: #0f4fc4;
  font-size: 12px;
  margin-bottom: 3px;
}

.maintenance-template-preview span {
  display: block;
  color: #64748b;
  font-size: 11px;
  line-height: 1.4;
}

.maintenance-checklist-box {
  margin-top: 18px;
  border: 1px solid #dbe7ff;
  border-radius: 20px;
  background: #f8fbff;
  padding: 16px;
}

.maintenance-checklist-header {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: flex-start;
  margin-bottom: 14px;
}

.maintenance-checklist-header h3 {
  margin: 0 0 5px;
  color: #0f2442;
  font-size: 17px;
}

.maintenance-checklist-header p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.45;
}

.maintenance-checklist-header strong {
  min-width: 62px;
  border-radius: 999px;
  padding: 8px 11px;
  background: #0f4fc4;
  color: #ffffff;
  font-size: 13px;
  text-align: center;
}

.maintenance-checklist-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.maintenance-checklist-item {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  margin: 0;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  background: #ffffff;
  padding: 11px 12px;
  color: #344256;
  font-size: 13px;
  line-height: 1.35;
  cursor: pointer;
  transition: 0.16s ease;
}

.maintenance-checklist-item:hover {
  border-color: #b9cdfa;
  box-shadow: 0 8px 18px rgba(15, 79, 196, 0.07);
}

.maintenance-checklist-item input {
  width: 18px;
  height: 18px;
  margin: 0;
  accent-color: #16a34a;
}

.maintenance-checklist-item.checked {
  border-color: #bbf7d0;
  background: #f0fdf4;
  color: #166534;
}

.technical-log-checklist {
  margin-top: 12px;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  background: #f8fafc;
  padding: 12px;
}

.technical-log-checklist > strong {
  display: block;
  margin-bottom: 9px;
  color: #0f2442;
  font-size: 12px;
}

.technical-log-checklist > div {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.technical-log-checklist span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  border-radius: 999px;
  padding: 6px 9px;
  font-size: 11px;
  font-weight: 800;
}

.technical-log-checklist span.done {
  background: #dcfce7;
  color: #166534;
  border: 1px solid #bbf7d0;
}

.technical-log-checklist span.pending {
  background: #fee2e2;
  color: #991b1b;
  border: 1px solid #fecaca;
}

@media (max-width: 1050px) {
  .technical-alert-strip {
    grid-template-columns: 1fr;
  }

  .technical-alert-stats {
    justify-content: flex-start;
  }

  .maintenance-checklist-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .technical-alert-main {
    align-items: flex-start;
  }

  .technical-alert-stats {
    display: grid;
    grid-template-columns: 1fr;
  }

  .technical-alert-stats div {
    width: 100%;
  }

  .maintenance-checklist-header {
    flex-direction: column;
  }

  .maintenance-checklist-header strong {
    width: 100%;
  }
}

/* =========================================================
   SOPORTE TÉCNICO - MEJORAS VISUALES CHECKLIST + NOTAS
========================================================= */

.technical-alert-strip {
  position: relative;
  overflow: hidden;
  border: 1px solid #fecaca;
  border-radius: 26px;
  padding: 18px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  background:
    radial-gradient(circle at 6% 18%, rgba(237, 28, 36, 0.16), transparent 28%),
    radial-gradient(circle at 92% 28%, rgba(249, 115, 22, 0.12), transparent 28%),
    linear-gradient(135deg, #fff7f7, #fffaf0 55%, #ffffff);
  box-shadow: 0 22px 48px rgba(180, 35, 24, 0.12);
}

.technical-alert-strip::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 6px;
  background: linear-gradient(90deg, #ed1c24, #f97316, #d99a00);
}

.technical-alert-main {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 15px;
  align-items: center;
}

.technical-alert-main > span {
  width: 58px;
  height: 58px;
  display: grid;
  place-items: center;
  border-radius: 18px;
  background: linear-gradient(135deg, #ed1c24, #f97316);
  color: white;
  font-size: 28px;
  box-shadow: 0 14px 28px rgba(237, 28, 36, 0.22);
}

.technical-alert-main strong {
  display: block;
  color: #7f1d1d;
  font-size: 20px;
  margin-bottom: 5px;
}

.technical-alert-main p {
  margin: 0;
  color: #9a3412;
  line-height: 1.45;
  font-size: 13px;
}

.visual-checklist-box {
  border: 1px solid #bad0ff;
  background:
    radial-gradient(circle at 95% 10%, rgba(15, 79, 196, 0.08), transparent 30%),
    linear-gradient(180deg, #f8fbff, #ffffff);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.72);
}

.checklist-score-card {
  min-width: 118px;
  border-radius: 18px;
  padding: 10px 12px;
  text-align: center;
  background: linear-gradient(135deg, #0f4fc4, #1d4ed8);
  color: white;
  box-shadow: 0 14px 26px rgba(15, 79, 196, 0.22);
}

.checklist-score-card strong {
  display: block;
  min-width: auto;
  padding: 0;
  background: transparent;
  color: white;
  font-size: 22px;
  line-height: 1;
}

.checklist-score-card span {
  display: block;
  margin-top: 5px;
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  opacity: 0.88;
}

.checklist-progress-wrap {
  margin: 4px 0 16px;
  border: 1px solid #dbe7ff;
  border-radius: 16px;
  background: #ffffff;
  padding: 12px;
}

.checklist-progress-info {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 8px;
}

.checklist-progress-info span {
  color: #526176;
  font-size: 12px;
  font-weight: 900;
}

.checklist-progress-info strong {
  color: #0f4fc4;
  font-size: 13px;
}

.checklist-progress-track {
  height: 10px;
  border-radius: 999px;
  background: #e8eef8;
  overflow: hidden;
}

.checklist-progress-fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ed1c24, #f97316, #16a34a);
  transition: width 0.22s ease;
}

.visual-checklist-grid {
  align-items: start;
}

.visual-checklist-item {
  grid-template-columns: 1fr;
  padding: 0;
  overflow: hidden;
}

.visual-checklist-item.pending {
  border-color: #fed7aa;
  background: #fffaf5;
}

.visual-checklist-main {
  display: grid;
  grid-template-columns: 20px 34px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  margin: 0;
  padding: 12px;
  cursor: pointer;
}

.visual-checklist-main input {
  width: 18px;
  height: 18px;
}

.visual-check-icon {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  background: #ffedd5;
  color: #9a3412;
  font-weight: 900;
}

.visual-checklist-item.checked .visual-check-icon {
  background: #dcfce7;
  color: #166534;
}

.visual-check-label {
  color: #0f2442;
  font-size: 13px;
  font-weight: 900;
  line-height: 1.35;
}

.checklist-note-field {
  display: grid;
  gap: 7px;
  margin: 0;
  padding: 12px;
  border-top: 1px solid #fed7aa;
  background: #fff7ed;
  color: #9a3412;
  font-size: 12px;
  font-weight: 900;
}

.checklist-note-field textarea {
  min-height: 62px;
  border-color: #fed7aa;
  background: #ffffff;
  color: #0f2442;
  font-size: 12px;
  line-height: 1.45;
}

.checklist-note-field textarea:focus {
  border-color: #f97316;
  box-shadow: 0 0 0 3px rgba(249, 115, 22, 0.12);
}

.visual-log-checklist {
  background: linear-gradient(180deg, #ffffff, #f8fbff);
  border-color: #dbe7ff;
}

.log-checklist-header {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  margin-bottom: 12px;
}

.log-checklist-header strong {
  color: #0f2442;
  font-size: 13px;
}

.log-checklist-header span {
  border-radius: 999px;
  padding: 6px 9px;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 11px;
  font-weight: 900;
}

.log-checklist-grid {
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px !important;
}

.log-checklist-item {
  display: grid !important;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 9px !important;
  align-items: start;
  border-radius: 14px !important;
  padding: 10px !important;
  border: 1px solid #e2e8f0;
}

.log-checklist-item > span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  padding: 0 !important;
  font-size: 13px;
}

.log-checklist-item.done {
  background: #f0fdf4;
  border-color: #bbf7d0;
}

.log-checklist-item.done > span {
  background: #dcfce7;
  color: #166534;
}

.log-checklist-item.pending {
  background: #fff7ed;
  border-color: #fed7aa;
}

.log-checklist-item.pending > span {
  background: #ffedd5;
  color: #9a3412;
}

.log-checklist-item strong {
  display: block;
  color: #0f2442;
  font-size: 12px;
  line-height: 1.35;
}

.log-checklist-item p {
  margin: 5px 0 0;
  color: #9a3412;
  font-size: 11px;
  line-height: 1.45;
}

@media (max-width: 1050px) {
  .technical-alert-strip {
    grid-template-columns: 1fr;
  }

  .log-checklist-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .visual-checklist-main {
    grid-template-columns: 20px 30px minmax(0, 1fr);
  }

  .checklist-score-card {
    width: 100%;
  }
}

/* =========================================================
