.technical-tabs {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border: 1px solid #dbe7ff;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.86);
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
  overflow-x: auto;
}

.technical-tabs button {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: 14px;
  background: transparent;
  color: #526176;
  padding: 10px 16px;
  font-size: 13px;
  font-weight: 900;
  white-space: nowrap;
  transition: 0.18s ease;
}

.technical-tabs button span {
  width: 24px;
  height: 24px;
  display: inline-grid;
  place-items: center;
  border-radius: 50%;
  background: #eef4ff;
  color: #0f4fc4;
  font-size: 13px;
}

.technical-tabs button:hover {
  background: #f8fbff;
  border-color: #dbe7ff;
  color: #0f4fc4;
}

.technical-tabs button.active {
