/* =========================================================
   SOPORTE TÉCNICO V2 - PANEL MÁS COMPACTO
   Reduce las tarjetas superiores y acerca la vista a la propuesta visual.
========================================================= */

.technical-command-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.technical-command-card {
  position: relative;
  display: grid;
  grid-template-columns: 64px minmax(0, 1fr);
  gap: 16px;
  align-items: center;
  min-height: 128px;
  padding: 20px 20px 42px;
  border: 1px solid #e2e8f0;
  border-radius: 24px;
  background: #ffffff;
  text-align: left;
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.07);
  overflow: hidden;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.technical-command-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 24px 44px rgba(15, 23, 42, 0.1);
}

.technical-command-card::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 5px;
  background: #0f4fc4;
}

.technical-command-icon {
  width: 62px;
  height: 62px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  color: #ffffff;
  font-size: 26px;
  font-weight: 900;
  box-shadow: 0 14px 28px rgba(15, 23, 42, 0.14);
}

.technical-command-card strong {
  display: block;
  margin: 0 0 4px;
  color: #0f2442;
  font-size: 32px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.technical-command-card h3 {
  margin: 0 0 5px;
  color: #0f2442;
  font-size: 15px;
  line-height: 1.22;
}

.technical-command-card p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.35;
}

.technical-command-card b {
  position: absolute;
  left: 98px;
  right: 16px;
  bottom: 13px;
  color: #0f4fc4;
  font-size: 12px;
  font-weight: 900;
  line-height: 1.2;
}

.technical-command-card.danger {
  border-color: #fecaca;
  background: linear-gradient(135deg, #fff5f5, #ffffff);
}

.technical-command-card.danger::after,
.technical-command-card.danger .technical-command-icon {
  background: linear-gradient(135deg, #ed1c24, #b42318);
}

.technical-command-card.danger b,
.technical-command-card.danger strong {
  color: #b42318;
}

.technical-command-card.warning {
  border-color: #fed7aa;
  background: linear-gradient(135deg, #fff7ed, #ffffff);
}

.technical-command-card.warning::after,
.technical-command-card.warning .technical-command-icon {
  background: linear-gradient(135deg, #f97316, #d99a00);
}

.technical-command-card.warning b,
.technical-command-card.warning strong {
  color: #c2410c;
}

.technical-command-card.info {
  border-color: #bad0ff;
  background: linear-gradient(135deg, #f8fbff, #ffffff);
}

.technical-command-card.info::after,
.technical-command-card.info .technical-command-icon {
  background: linear-gradient(135deg, #0f4fc4, #1e3a8a);
}

.technical-command-card.info b,
.technical-command-card.info strong {
  color: #0f4fc4;
}

.technical-command-card.success {
  border-color: #bbf7d0;
  background: linear-gradient(135deg, #f0fdf4, #ffffff);
}

.technical-command-card.success::after,
.technical-command-card.success .technical-command-icon {
  background: linear-gradient(135deg, #16a34a, #0f9488);
}

.technical-command-card.success b,
.technical-command-card.success strong {
  color: #047857;
}

.technical-tabs {
  margin-top: -2px;
}

.technical-overview-layout {
  margin-top: 0;
}

