.technical-quick-asset-panel {
  position: relative;
  overflow: hidden;
  border-color: #bad0ff;
  background:
    radial-gradient(circle at 4% 0%, rgba(15, 79, 196, 0.08), transparent 28%),
    radial-gradient(circle at 96% 20%, rgba(237, 28, 36, 0.06), transparent 26%),
    linear-gradient(180deg, #ffffff, #fbfdff);
}

.technical-quick-asset-panel::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 6px;
  background: linear-gradient(90deg, #0f4fc4, #38bdf8, #ed1c24);
}

.technical-quick-asset-hero {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr) auto;
  gap: 18px;
  align-items: center;
  margin-bottom: 18px;
}

.technical-quick-asset-icon {
  width: 72px;
  height: 72px;
  display: grid;
  place-items: center;
  border-radius: 24px;
  background: linear-gradient(135deg, #0f4fc4, #1e3a8a);
  color: white;
  font-size: 30px;
  font-weight: 900;
  box-shadow: 0 18px 34px rgba(15, 79, 196, 0.2);
}

.technical-quick-asset-title {
  min-width: 0;
}

.technical-quick-asset-title h2 {
  margin: 8px 0 6px;
  color: #0f2442;
  font-size: clamp(22px, 3vw, 30px);
  line-height: 1.1;
  letter-spacing: -0.04em;
}

.technical-quick-asset-title p {
  margin: 0;
  color: #526176;
  font-size: 14px;
  line-height: 1.45;
}

.technical-quick-layout {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 370px;
  gap: 18px;
  align-items: start;
}

.technical-quick-main {
  display: grid;
  gap: 16px;
}

.technical-quick-info-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.technical-quick-info-grid article {
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #ffffff;
  padding: 14px;
  min-width: 0;
}

.technical-quick-info-grid span {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 6px;
}

.technical-quick-info-grid strong {
  display: block;
  color: #0f2442;
  font-size: 14px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.technical-quick-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  padding: 14px;
  border: 1px solid #dbe7ff;
  border-radius: 18px;
  background: #f8fbff;
}

.technical-quick-actions .primary-button {
  background: linear-gradient(135deg, #0f4fc4, #0941a5);
  color: white;
  box-shadow: 0 14px 28px rgba(15, 79, 196, 0.2);
}

.technical-quick-actions .visual-outline-button,
.technical-quick-actions .primary-button {
  border-radius: 12px;
  padding: 11px 14px;
}

.technical-quick-maintenance-card {
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: #ffffff;
  padding: 16px;
  box-shadow: 0 14px 32px rgba(15, 23, 42, 0.07);
}

.technical-quick-maintenance-card .technical-panel-header {
  margin-bottom: 12px;
}

.technical-quick-maintenance-card .technical-panel-header h3 {
  margin: 0;
  color: #0f2442;
  font-size: 17px;
}

.technical-quick-maintenance-card .technical-panel-header p {
  margin: 4px 0 0;
  color: #64748b;
  font-size: 12px;
}

.technical-quick-maintenance-card .technical-panel-header > strong {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 18px;
  font-weight: 900;
  flex-shrink: 0;
}

.technical-quick-maintenance-list {
  display: grid;
  gap: 10px;
}

.technical-quick-maintenance-item {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  border: 1px solid #e5eaf2;
  border-radius: 14px;
  background: #fbfdff;
  padding: 10px;
}

.technical-quick-maintenance-item > span {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 17px;
}

.technical-quick-maintenance-item.urgency-overdue {
  border-color: #fecaca;
  background: #fff7f7;
}

.technical-quick-maintenance-item.urgency-overdue > span {
  background: #fee2e2;
  color: #b42318;
}

.technical-quick-maintenance-item.urgency-today {
  border-color: #fed7aa;
  background: #fff7ed;
}

.technical-quick-maintenance-item.urgency-today > span {
  background: #ffedd5;
  color: #c2410c;
}

.technical-quick-maintenance-item.urgency-soon {
  border-color: #fde68a;
  background: #fffbeb;
}

.technical-quick-maintenance-item.urgency-soon > span {
  background: #fff4d8;
  color: #b45309;
}

.technical-quick-maintenance-item strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
  line-height: 1.25;
}

.technical-quick-maintenance-item p {
  margin: 3px 0 0;
  color: #0f4fc4;
  font-size: 12px;
  font-weight: 900;
}

.technical-quick-maintenance-item small {
  display: block;
  color: #64748b;
  font-size: 11px;
  margin-top: 2px;
}

.technical-quick-maintenance-item button {
  border: 1px solid #b9cdfa;
  border-radius: 10px;
  background: #ffffff;
  color: #0f4fc4;
  padding: 8px 10px;
  font-size: 12px;
  font-weight: 900;
}

.technical-quick-maintenance-item button:hover {
  background: #eef5ff;
}

@media (max-width: 1250px) {
  .technical-quick-layout {
    grid-template-columns: 1fr;
  }

  .technical-quick-info-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .technical-quick-asset-hero {
    grid-template-columns: 1fr;
  }

  .technical-quick-asset-icon {
    width: 62px;
    height: 62px;
  }

  .technical-quick-asset-hero .visual-outline-button {
    width: 100%;
  }

  .technical-quick-info-grid {
    grid-template-columns: 1fr;
  }

  .technical-quick-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .technical-quick-actions .visual-outline-button,
  .technical-quick-actions .primary-button {
    width: 100%;
  }

  .technical-quick-maintenance-item {
    grid-template-columns: 38px minmax(0, 1fr);
  }

  .technical-quick-maintenance-item button {
    grid-column: 2;
    width: fit-content;
  }
}

/* =========================================================
   SOPORTE TÉCNICO - TARJETAS CLICABLES Y FICHA RÁPIDA V2
========================================================= */

.technical-asset-card-clickable {
  cursor: pointer;
  outline: none;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.technical-asset-card-clickable:hover,
.technical-asset-card-clickable:focus-visible {
  border-color: #93c5fd;
  box-shadow: 0 20px 44px rgba(15, 79, 196, 0.12);
  transform: translateY(-2px);
}

.technical-asset-card-clickable:focus-visible {
  box-shadow: 0 0 0 4px rgba(15, 79, 196, 0.14),
    0 20px 44px rgba(15, 79, 196, 0.12);
}

.technical-asset-card-clickable .technical-asset-top h3::after {
  content: "  · ver detalles";
  color: #0f4fc4;
  font-size: 11px;
  font-weight: 900;
  opacity: 0;
  transition: opacity 0.18s ease;
}

.technical-asset-card-clickable:hover .technical-asset-top h3::after,
.technical-asset-card-clickable:focus-visible .technical-asset-top h3::after {
  opacity: 1;
}

