/* =========================================================
   SOPORTE TÉCNICO - MODO TÉCNICO EN CAMPO
========================================================= */

.field-mode-page {
  min-height: 100vh;
  padding: 0;
  background:
    radial-gradient(circle at 20% 0%, rgba(15, 79, 196, 0.12), transparent 34%),
    linear-gradient(180deg, #f8fbff 0%, #eef4fb 100%);
}

.field-mode-shell {
  width: min(100%, 760px);
  margin: 0 auto;
  padding: 18px;
  display: grid;
  gap: 14px;
}

.field-mode-hero,
.field-mode-location-card,
.field-mode-actions-card,
.field-mode-maintenance-card,
.field-mode-history-card {
  border: 1px solid #dbe7ff;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 16px 38px rgba(15, 23, 42, 0.08);
  overflow: hidden;
}

.field-mode-hero {
  position: relative;
  padding: 20px;
  color: white;
  background:
    radial-gradient(circle at 82% 10%, rgba(255, 255, 255, 0.18), transparent 28%),
    linear-gradient(135deg, #0b2c6f 0%, #0f4fc4 56%, #7f1d1d 100%);
  border: none;
}

.field-mode-hero::after {
  content: "";
  position: absolute;
  right: -58px;
  bottom: -74px;
  width: 170px;
  height: 170px;
  border-radius: 50%;
  border: 30px solid rgba(255, 255, 255, 0.12);
  pointer-events: none;
}

.field-mode-topline {
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.field-mode-kicker {
  display: inline-flex;
  width: fit-content;
  border-radius: 999px;
  padding: 7px 11px;
  background: rgba(255, 255, 255, 0.16);
  color: #dbeafe;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.field-mode-close-button {
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
  color: white;
  padding: 9px 12px;
  font-size: 12px;
  font-weight: 900;
}

.field-mode-asset-title {
  position: relative;
  z-index: 1;
}

.field-mode-code {
  display: inline-flex;
  width: fit-content;
  border-radius: 12px;
  padding: 7px 10px;
  background: rgba(255, 255, 255, 0.95);
  color: #0f4fc4;
  font-size: 13px;
  font-weight: 950;
  letter-spacing: 0.05em;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.14);
}

.field-mode-asset-title h1 {
  margin: 12px 0 6px;
  font-size: clamp(28px, 9vw, 44px);
  line-height: 1.04;
  letter-spacing: -0.05em;
}

.field-mode-asset-title p {
  margin: 0;
  color: #dbeafe;
  font-size: 15px;
  font-weight: 800;
}

.field-mode-status-row {
  position: relative;
  z-index: 1;
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-top: 18px;
}

.field-mode-status,
.field-mode-condition {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border-radius: 999px;
  padding: 9px 12px;
  font-size: 13px;
  font-weight: 900;
}

.field-mode-status {
  background: #dcfce7;
  color: #166534;
}

.field-mode-status.en-reparación,
.field-mode-status.en-mantenimiento {
  background: #ffedd5;
  color: #9a3412;
}

.field-mode-status.dado-de-baja {
  background: #fee2e2;
  color: #991b1b;
}

.field-mode-condition {
  background: rgba(255, 255, 255, 0.16);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.22);
}

.field-mode-location-card,
.field-mode-actions-card,
.field-mode-maintenance-card,
.field-mode-history-card {
  padding: 16px;
}

.field-mode-location-card h2,
.field-mode-section-header h2 {
  margin: 0;
  color: #0f2442;
  font-size: 18px;
  letter-spacing: -0.02em;
}

.field-mode-location-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 12px;
}

.field-mode-location-grid article {
  min-width: 0;
  border: 1px solid #e5eaf2;
  border-radius: 16px;
  padding: 12px;
  background: #f8fbff;
}

.field-mode-location-grid span {
  display: block;
  margin-bottom: 5px;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.field-mode-location-grid strong {
  display: block;
  color: #0f2442;
  font-size: 14px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.field-mode-actions-card {
  display: grid;
  gap: 12px;
}

.field-mode-primary-action {
  min-height: 68px;
  border: none;
  border-radius: 18px;
  background: linear-gradient(135deg, #0f4fc4, #0a3b94);
  color: white;
  padding: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 11px;
  font-size: 17px;
  font-weight: 950;
  box-shadow: 0 16px 30px rgba(15, 79, 196, 0.24);
}

.field-mode-primary-action span {
  font-size: 24px;
}

.field-mode-secondary-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.field-mode-secondary-actions button {
  min-height: 64px;
  border: 1px solid #dbe7ff;
  border-radius: 16px;
  background: white;
  color: #0f2442;
  padding: 10px;
  display: grid;
  place-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 900;
}

.field-mode-secondary-actions span {
  display: block;
  color: #0f4fc4;
  font-size: 20px;
}

.field-mode-section-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 12px;
}

.field-mode-section-header p {
  margin: 4px 0 0;
  color: #64748b;
  font-size: 12px;
}

.field-mode-section-header > strong {
  min-width: 38px;
  height: 34px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 14px;
  font-weight: 950;
}

.field-mode-maintenance-list,
.field-mode-history-list {
  display: grid;
  gap: 10px;
}

.field-mode-maintenance-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  border: 1px solid #e2e8f0;
  border-left: 6px solid #0f4fc4;
  border-radius: 18px;
  background: #ffffff;
  padding: 12px;
}

.field-mode-maintenance-item.urgency-overdue {
  border-left-color: #ed1c24;
  background: #fff5f5;
}

.field-mode-maintenance-item.urgency-today {
  border-left-color: #f97316;
  background: #fff7ed;
}

.field-mode-maintenance-item.urgency-soon {
  border-left-color: #d99a00;
  background: #fffbeb;
}

.field-mode-maintenance-item div {
  min-width: 0;
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 4px 8px;
  align-items: center;
}

.field-mode-maintenance-item div > span {
  grid-row: 1 / 3;
  width: 30px;
  height: 30px;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: #eef4ff;
}

.field-mode-maintenance-item strong {
  color: #0f2442;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.field-mode-maintenance-item p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
}

.field-mode-maintenance-item button {
  border: none;
  border-radius: 999px;
  background: #0f4fc4;
  color: white;
  padding: 10px 13px;
  font-size: 12px;
  font-weight: 950;
}

.field-mode-history-list article {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  border: 1px solid #e5eaf2;
  border-radius: 16px;
  padding: 11px;
  background: #fbfdff;
}

.field-mode-history-list article > span {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: #eaf2ff;
  color: #0f4fc4;
  font-weight: 950;
}

.field-mode-history-list strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
}

.field-mode-history-list p {
  margin: 3px 0 0;
  color: #64748b;
  font-size: 11px;
}

.field-mode-empty-card {
  border: 1px dashed #cbd7e6;
  border-radius: 16px;
  background: #f8fbff;
  padding: 14px;
  text-align: center;
}

.field-mode-empty-card strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
  margin-bottom: 4px;
}

.field-mode-empty-card p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.45;
}

@media (max-width: 768px) {
  .main-content:has(.field-mode-page) {
    padding: 0;
  }

  .field-mode-page {
    margin: -18px;
    min-height: calc(100vh + 36px);
  }

  .field-mode-shell {
    padding: 14px;
  }
}

@media (max-width: 520px) {
  .field-mode-topline {
    align-items: flex-start;
    flex-direction: column;
  }

  .field-mode-close-button {
    width: 100%;
  }

  .field-mode-location-grid,
  .field-mode-secondary-actions {
    grid-template-columns: 1fr;
  }

  .field-mode-secondary-actions button {
    min-height: 56px;
    grid-template-columns: 28px minmax(0, 1fr);
    justify-content: start;
    place-items: center start;
    text-align: left;
    padding: 12px 14px;
  }

  .field-mode-maintenance-item {
    grid-template-columns: 1fr;
  }

  .field-mode-maintenance-item button {
    width: 100%;
  }
}

/* =========================================================
   SOPORTE TÉCNICO - FIX MODO TÉCNICO DESDE QR EN CELULAR
   Oculta el shell administrativo para que el técnico vea
   directamente la ficha del equipo al escanear.
========================================================= */

body.technical-field-mode-active,
body:has(.field-mode-page) {
  background: #eef4ff;
}

body.technical-field-mode-active .app-shell,
body:has(.field-mode-page) .app-shell {
  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  min-height: 100vh !important;
}

body.technical-field-mode-active .sidebar,
body.technical-field-mode-active .top-profile-bar,
body:has(.field-mode-page) .sidebar,
body:has(.field-mode-page) .top-profile-bar {
  display: none !important;
}

body.technical-field-mode-active .main-content,
body:has(.field-mode-page) .main-content {
  width: 100% !important;
  max-width: 100% !important;
  min-height: 100vh !important;
  padding: 0 !important;
  overflow-x: hidden !important;
  background: #eef4ff !important;
}

.field-mode-page {
  min-height: 100vh;
  width: 100%;
  padding: 0;
  margin: 0;
  background:
    radial-gradient(circle at 15% 0%, rgba(15, 79, 196, 0.16), transparent 30%),
    radial-gradient(circle at 90% 10%, rgba(237, 28, 36, 0.08), transparent 28%),
    #eef4ff;
}

.field-mode-page .field-mode-shell {
  width: min(760px, 100%);
  margin: 0 auto;
  padding: 16px;
}

.field-mode-error {
  width: min(760px, calc(100% - 32px));
  margin: 16px auto 0;
}

.field-mode-loading-card {
  min-height: calc(100vh - 32px);
  display: grid;
  place-items: center;
  align-content: center;
  gap: 12px;
  text-align: center;
  background: white;
  border: 1px solid #dbe7ff;
  border-radius: 28px;
  box-shadow: 0 22px 54px rgba(15, 23, 42, 0.12);
  padding: 28px;
}

.field-mode-loading-card span {
  width: 64px;
  height: 64px;
  display: grid;
  place-items: center;
  border-radius: 22px;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 30px;
}

.field-mode-loading-card h1 {
  margin: 0;
  color: #0f2442;
  font-size: 24px;
  letter-spacing: -0.03em;
}

.field-mode-loading-card p {
  margin: 0;
  color: #64748b;
  line-height: 1.45;
}

@media (max-width: 900px) {
  body.technical-field-mode-active .main-content,
  body:has(.field-mode-page) .main-content {
    padding: 0 !important;
  }

  .field-mode-page .field-mode-shell {
    padding: 12px;
  }
}

/* =========================================================
   SOPORTE TÉCNICO - FIX ACCIONES DESDE QR EN MÓVIL
   Mantiene el modo de campo al abrir formularios desde la ficha QR,
   sin mostrar menú lateral, tarjetas generales ni pestañas.
========================================================= */

.technical-support-page.field-action-mode {
  min-height: 100vh;
  width: 100%;
  padding: 14px;
  margin: 0;
  background:
    radial-gradient(circle at 15% 0%, rgba(15, 79, 196, 0.16), transparent 30%),
    radial-gradient(circle at 90% 10%, rgba(237, 28, 36, 0.08), transparent 28%),
