.technical-support-page.field-action-mode > .technical-equipment-dashboard,
.technical-support-page.field-action-mode > .technical-equipment-section,
.technical-support-page.field-action-mode > .technical-register-dashboard,
.technical-support-page.field-action-mode > .technical-quick-asset-panel {
  display: none !important;
}

.technical-support-page.field-action-mode > .technical-panel,
.technical-support-page.field-action-mode > .form-error {
  width: min(760px, 100%);
  margin-left: auto;
  margin-right: auto;
}

.technical-support-page.field-action-mode > .technical-panel {
  border-radius: 24px;
  box-shadow: 0 22px 54px rgba(15, 23, 42, 0.12);
}

.technical-support-page.field-action-mode .technical-panel-header {
  gap: 12px;
}

@media (max-width: 900px) {
  .technical-support-page.field-action-mode {
    padding: 12px;
  }

  .technical-support-page.field-action-mode .technical-panel {
    padding: 16px;
  }

  .technical-support-page.field-action-mode .technical-panel-header {
    flex-direction: column;
    align-items: stretch;
  }

  .technical-support-page.field-action-mode .technical-form-actions {
