/* =========================================================
   SOPORTE TÉCNICO - MANTENIMIENTO PERIÓDICO DE UBICACIONES
========================================================= */

.technical-command-grid {
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
}

.scheduled-location-maintenance-section {
  margin: 4px 0 22px;
  padding: 18px;
  border: 1px solid #dbeafe;
  border-radius: 24px;
  background:
    radial-gradient(circle at top right, rgba(15, 79, 196, 0.08), transparent 30%),
    linear-gradient(180deg, #ffffff, #f8fbff);
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.06);
}

.scheduled-location-maintenance-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 14px;
}

.scheduled-location-maintenance-header h3 {
  margin: 0 0 6px;
  color: #0f2442;
  font-size: 18px;
}

.scheduled-location-maintenance-header p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.45;
}

.scheduled-location-maintenance-header > span {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  background: #eaf2ff;
  color: #0f4fc4;
  padding: 7px 11px;
  font-size: 12px;
  font-weight: 900;
  white-space: nowrap;
}

.scheduled-location-maintenance-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 12px;
}

.scheduled-location-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  border: 1px solid #e2e8f0;
  border-left: 6px solid #0f4fc4;
  border-radius: 18px;
  background: #ffffff;
  padding: 14px;
