.scheduled-location-card.urgency-overdue {
  border-left-color: #ed1c24;
  background: linear-gradient(180deg, #fff5f5, #ffffff);
}

.scheduled-location-card.urgency-today {
  border-left-color: #f97316;
  background: linear-gradient(180deg, #fff7ed, #ffffff);
}

.scheduled-location-card.urgency-soon {
  border-left-color: #d99a00;
  background: linear-gradient(180deg, #fffbeb, #ffffff);
}

.scheduled-location-card h4 {
  margin: 8px 0 4px;
  color: #0f2442;
  font-size: 15px;
}

.scheduled-location-card p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
}

.scheduled-location-meta {
  display: grid;
  gap: 4px;
