}

.scheduled-location-meta small {
  color: #64748b;
  font-size: 11px;
}

.scheduled-location-card button {
  grid-column: 1 / -1;
  width: 100%;
  justify-content: center;
}

.location-review-empty-card {
  display: grid;
  gap: 8px;
  padding: 14px;
  border: 1px dashed #bad0ff;
  border-radius: 16px;
  background: #f8fbff;
  margin-bottom: 12px;
}

.location-review-empty-card strong {
  color: #0f2442;
  font-size: 14px;
}

.location-review-empty-card p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
}

@media (max-width: 720px) {
  .scheduled-location-maintenance-header,
  .scheduled-location-card {
    grid-template-columns: 1fr;
  }

  .scheduled-location-maintenance-header > span,
  .scheduled-location-meta {
    text-align: left;
  }
}


