  }

  .location-review-checklist-v2 {
    grid-template-columns: 1fr !important;
  }

  .location-review-card-controls-v2,
  .asset-checklist-editor-card .editable-checklist-row {
    grid-template-columns: 1fr !important;
  }

  .asset-checklist-editor-card .editable-checklist-row > input[type="text"],
  .asset-checklist-editor-card .editable-checklist-row input[type="text"],
