}
/* =========================================================
   MÓDULO DE IMPRENTA - VISTA INICIAL
========================================================= */

.printshop-page {
  display: grid;
  gap: 18px;
  width: 100%;
  max-width: 100%;
  min-width: 0;
}

.printshop-topbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  padding: 0 2px 6px;
}

.printshop-kicker {
  color: #0f4fc4 !important;
  letter-spacing: 0.1em;
}

.printshop-topbar h1 {
  margin: 3px 0 6px;
  color: #0f2442;
  font-size: 30px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.printshop-topbar p:not(.section-kicker) {
  margin: 0;
  max-width: 850px;
  color: #536176;
  font-size: 15px;
  line-height: 1.55;
}

.printshop-search {
  width: min(430px, 100%);
  min-height: 50px;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 0 16px;
  border: 1px solid #d9e2ef;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.05);
}

.printshop-search span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #eef4ff;
  color: #0f4fc4;
  font-size: 18px;
  font-weight: 900;
}

.printshop-search input {
  height: 100%;
  border: none;
  border-radius: 0;
  box-shadow: none;
  padding: 0;
  background: transparent;
  color: #0f2442;
  font-size: 14px;
}

.printshop-search input:focus {
  border: none;
  box-shadow: none;
}

.printshop-metrics-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 14px;
}

.printshop-metric-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 122px;
  padding: 17px;
  border: 1px solid #e9eef6;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.07);
  overflow: hidden;
}

.printshop-metric-card::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 5px;
}

.printshop-metric-icon {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-size: 22px;
  font-weight: 900;
  flex-shrink: 0;
}

.printshop-metric-card span {
  display: block;
  color: #344256;
  font-size: 12px;
  font-weight: 900;
  margin-bottom: 6px;
}

.printshop-metric-card strong {
  display: block;
  color: #0f2442;
  font-size: 30px;
  line-height: 1;
  margin-bottom: 7px;
}

.printshop-metric-card p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.35;
}

.printshop-metric-card.blue .printshop-metric-icon,
.printshop-status-badge.blue {
  background: #eaf2ff;
  color: #0f4fc4;
}

.printshop-metric-card.blue::after,
.printshop-progress-fill.blue {
  background: #0f4fc4;
}

.printshop-metric-card.teal .printshop-metric-icon,
.printshop-status-badge.teal {
  background: #ccfbf1;
  color: #0f9488;
}

.printshop-metric-card.teal::after,
.printshop-progress-fill.teal {
  background: #0f9488;
}

.printshop-metric-card.orange .printshop-metric-icon,
.printshop-status-badge.orange {
  background: #ffedd5;
  color: #f97316;
}

.printshop-metric-card.orange::after,
.printshop-progress-fill.orange {
  background: #f97316;
}

.printshop-metric-card.green .printshop-metric-icon,
.printshop-status-badge.green {
  background: #dcfce7;
  color: #16a34a;
}

.printshop-metric-card.green::after,
.printshop-progress-fill.green {
  background: #16a34a;
}

.printshop-metric-card.red .printshop-metric-icon,
.printshop-status-badge.red {
  background: #fee2e2;
  color: #ed1c24;
}

.printshop-metric-card.red::after,
.printshop-progress-fill.red {
  background: #ed1c24;
}

.printshop-metric-card.purple .printshop-metric-icon,
.printshop-status-badge.purple {
  background: #ede9fe;
  color: #7c3aed;
}

.printshop-metric-card.purple::after,
.printshop-progress-fill.purple {
  background: #7c3aed;
}

.printshop-action-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.printshop-action-card {
  position: relative;
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr) 24px;
  gap: 15px;
  align-items: center;
  min-height: 88px;
  padding: 16px 18px;
  border: 1px solid #bad0ff;
  border-radius: 18px;
  background:
    radial-gradient(circle at top right, rgba(15, 79, 196, 0.06), transparent 32%),
    #ffffff;
  color: #0f2442;
  text-align: left;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.05);
  transition: 0.18s ease;
}

.printshop-action-card:hover {
  transform: translateY(-1px);
  border-color: #0f4fc4;
  box-shadow: 0 16px 34px rgba(15, 79, 196, 0.11);
}

.printshop-action-card > span {
  width: 54px;
  height: 54px;
  display: grid;
  place-items: center;
  border-radius: 15px;
  background: linear-gradient(135deg, #0f4fc4, #1e3a8a);
  color: #ffffff;
  font-size: 24px;
  font-weight: 900;
}

.printshop-action-card strong {
  display: block;
  color: #0f4fc4;
  font-size: 15px;
  margin-bottom: 5px;
}

.printshop-action-card p {
  margin: 0;
  color: #526176;
  font-size: 13px;
  line-height: 1.35;
}

.printshop-action-card b {
  color: #0f2442;
  font-size: 27px;
  line-height: 1;
}

.printshop-main-grid,
.printshop-bottom-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 420px;
  gap: 18px;
  align-items: start;
}

.printshop-main-column,
.printshop-side-column {
  display: grid;
  gap: 18px;
  min-width: 0;
}

.printshop-panel {
  min-width: 0;
  border: 1px solid #e2e8f0;
  border-radius: 22px;
  background: #ffffff;
  box-shadow: 0 16px 38px rgba(15, 23, 42, 0.08);
  padding: 18px;
  overflow: hidden;
}

.printshop-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 14px;
}

.printshop-panel-header > div {
  display: flex;
  align-items: center;
  gap: 9px;
}

.printshop-panel-header span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: #eaf2ff;
  color: #0f4fc4;
  font-weight: 900;
}

.printshop-panel-header h2 {
  margin: 0;
  color: #0f2442;
  font-size: 17px;
}

.printshop-panel-header button {
  border: none;
  background: transparent;
  color: #0f4fc4;
  padding: 4px 0;
  font-size: 12px;
  font-weight: 900;
}

.printshop-table-wrap {
  width: 100%;
  overflow-x: auto;
}

.printshop-table {
  width: 100%;
  min-width: 740px;
  border-collapse: collapse;
}

.printshop-batches-table {
  min-width: 850px;
}

.printshop-table th {
  text-align: left;
  color: #5d6b7c;
  font-size: 11px;
  font-weight: 900;
  padding: 10px 9px;
  border-bottom: 1px solid #e2e8f0;
  white-space: nowrap;
}

.printshop-table td {
  color: #334155;
  font-size: 13px;
  padding: 12px 9px;
  border-bottom: 1px solid #e8edf3;
  vertical-align: middle;
}

.printshop-table td strong {
  color: #0f2442;
  font-size: 12px;
}

.printshop-status-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: fit-content;
  max-width: 160px;
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.2;
  text-align: center;
  white-space: normal;
}

.printshop-progress-cell {
  display: grid;
  grid-template-columns: minmax(90px, 1fr) 42px;
  gap: 9px;
  align-items: center;
}

.printshop-progress-track {
  height: 9px;
  border-radius: 999px;
  background: #e8edf3;
  overflow: hidden;
}

.printshop-progress-fill {
  height: 100%;
  border-radius: inherit;
}

.printshop-progress-cell strong {
  color: #0f2442;
  font-size: 12px;
}

.finished-inventory-list,
.critical-supplies-list,
.printshop-roadmap-list,
.certificate-students-list {
  display: grid;
  gap: 10px;
}

.finished-inventory-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  border: 1px solid #e5eaf2;
  border-radius: 14px;
  background: #fbfdff;
  padding: 12px;
}

.finished-inventory-row strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
  margin-bottom: 3px;
}

.finished-inventory-row span:not(.printshop-status-badge) {
  display: block;
  color: #64748b;
  font-size: 12px;
}

.critical-supply-row {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto auto;
  gap: 10px;
  align-items: center;
  border: 1px solid #e5eaf2;
  border-radius: 15px;
  background: #fbfdff;
  padding: 11px;
}

.critical-supply-icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  font-weight: 900;
}

.critical-supply-icon.red {
  background: #fee2e2;
  color: #ed1c24;
}

.critical-supply-icon.orange {
  background: #ffedd5;
  color: #f97316;
}

.critical-supply-info strong,
.critical-supply-stock strong {
  display: block;
  color: #0f2442;
  font-size: 12px;
  line-height: 1.25;
}

.critical-supply-info span,
.critical-supply-stock span {
  display: block;
  color: #64748b;
  font-size: 11px;
  margin-top: 3px;
}

.critical-supply-stock {
  text-align: right;
  white-space: nowrap;
}

.certificate-workflow-layout {
  display: grid;
  grid-template-columns: minmax(250px, 0.9fr) minmax(260px, 1fr) minmax(230px, 0.8fr);
  gap: 18px;
  align-items: stretch;
}

.certificate-form-preview {
  display: grid;
  gap: 12px;
  align-content: start;
}

.certificate-form-preview label {
  margin: 0;
  display: grid;
  gap: 7px;
}

.certificate-form-preview label span {
  color: #0f2442;
  font-size: 12px;
  font-weight: 900;
}

.certificate-form-preview select {
  height: 42px;
  border: 1px solid #d9e2ef;
  border-radius: 10px;
  background: white;
  color: #0f2442;
  padding: 0 12px;
  font-size: 13px;
  font-weight: 700;
}

.certificate-counts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.certificate-counts div {
  border: 1px solid #e5eaf2;
  border-radius: 12px;
  background: #f8fbff;
  padding: 10px;
  text-align: center;
}

.certificate-counts span {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
  margin-bottom: 4px;
}

.certificate-counts strong {
  color: #0f4fc4;
  font-size: 22px;
}

.certificate-button {
  width: 100%;
  margin-top: 2px;
}

.certificate-card-preview {
  display: grid;
  place-items: center;
  border: 1px solid #dbe7ff;
  border-radius: 18px;
  background:
    radial-gradient(circle at top right, rgba(15, 79, 196, 0.06), transparent 30%),
    #f8fbff;
  padding: 16px;
}

.certificate-border {
  width: min(100%, 310px);
  min-height: 390px;
  border: 7px double #bad0ff;
  border-radius: 8px;
  background: #fffdf8;
  padding: 20px 18px;
  text-align: center;
  color: #0f2442;
  box-shadow: 0 18px 38px rgba(15, 23, 42, 0.08);
}

.certificate-logo {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  margin: 0 auto 6px;
  border-radius: 50%;
  background: linear-gradient(135deg, #0f4fc4, #ed1c24);
  color: white;
  font-size: 11px;
  font-weight: 900;
}

.certificate-border > small {
  display: block;
  color: #64748b;
  font-size: 10px;
  margin-bottom: 16px;
}

.certificate-border h3 {
  margin: 0 0 12px;
  color: #0f2442;
  font-size: 24px;
  letter-spacing: 0.08em;
}

.certificate-border p {
  margin: 0 0 8px;
  color: #64748b;
  font-size: 12px;
}

.certificate-border > strong {
  display: block;
  color: #0f4fc4;
  font-size: 23px;
  line-height: 1.15;
  margin-bottom: 13px;
  font-family: Georgia, "Times New Roman", serif;
  font-style: italic;
}

.certificate-border > span {
  display: block;
  color: #526176;
  font-size: 11px;
  line-height: 1.45;
  margin-bottom: 22px;
}

.certificate-signature {
  width: 150px;
  margin: 0 auto 18px;
  border-bottom: 1px solid #0f2442;
  color: #0f2442;
  font-family: Georgia, "Times New Roman", serif;
  font-style: italic;
  font-size: 13px;
  padding-bottom: 5px;
}

.certificate-footer {
  display: grid;
  grid-template-columns: 1fr 82px;
  gap: 12px;
  align-items: end;
  text-align: left;
}

.certificate-footer small {
  display: block;
  color: #64748b;
  font-size: 9px;
  margin-bottom: 3px;
}

.certificate-footer b {
  display: block;
  color: #0f2442;
  font-size: 10px;
  overflow-wrap: anywhere;
}

.qr-placeholder {
  width: 78px;
  height: 78px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px;
  border: 2px solid #0f2442;
  background: white;
  padding: 5px;
}

.qr-placeholder i {
  display: block;
  background: #0f2442;
}

.qr-placeholder i:nth-child(2),
.qr-placeholder i:nth-child(4),
.qr-placeholder i:nth-child(8) {
  background: #ffffff;
}

.certificate-students-card {
  border: 1px solid #e5eaf2;
  border-radius: 16px;
  background: #fbfdff;
  padding: 14px;
}

.certificate-student-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  border: 1px solid #e5eaf2;
  border-radius: 12px;
  background: #ffffff;
  padding: 10px;
}

.certificate-student-row strong {
  color: #0f2442;
  font-size: 12px;
  line-height: 1.25;
}

.printshop-roadmap-item {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr);
  gap: 12px;
  align-items: start;
  border: 1px solid #e5eaf2;
  border-radius: 14px;
  background: #fbfdff;
  padding: 12px;
}

.printshop-roadmap-item > span {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #e8edf3;
  color: #526176;
  font-weight: 900;
}

.printshop-roadmap-item.active {
  border-color: #bad0ff;
  background: #f8fbff;
}

.printshop-roadmap-item.active > span {
  background: #0f4fc4;
  color: white;
}

.printshop-roadmap-item strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
  margin-bottom: 4px;
}

.printshop-roadmap-item p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.45;
}

@media (max-width: 1550px) {
  .printshop-metrics-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .certificate-workflow-layout {
    grid-template-columns: minmax(0, 0.9fr) minmax(0, 1fr);
  }

  .certificate-students-card {
    grid-column: 1 / -1;
  }
}

@media (max-width: 1250px) {
  .printshop-main-grid,
  .printshop-bottom-grid {
    grid-template-columns: 1fr;
  }

  .printshop-side-column {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1000px) {
  .printshop-topbar {
    flex-direction: column;
  }

  .printshop-search {
    width: 100%;
  }

  .printshop-metrics-grid,
  .printshop-action-grid,
  .printshop-side-column,
  .certificate-workflow-layout {
    grid-template-columns: 1fr;
  }

  .certificate-students-card {
    grid-column: auto;
  }
