/* =========================================================
   IMPRENTA - SOLICITUDES: DETALLE AMPLIO
   Corrige la tarjeta angosta de alumnos/certificados.
   Pegar al FINAL de src/app.css para que sobrescriba estilos previos.
========================================================= */

/* En solicitudes, el detalle y el formulario bajan a una zona amplia
   en vez de quedar comprimidos en la columna lateral de 390px. */
.request-layout.printshop-batches-layout {
  grid-template-columns: minmax(0, 1fr);
}

.request-layout .printshop-batches-side {
  position: static;
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(360px, 0.85fr);
  gap: 18px;
  align-items: start;
}

/* Cuando no hay solicitud seleccionada, el formulario no queda demasiado ancho. */
.request-layout .printshop-batches-side > .printshop-panel:only-child,
.request-layout .printshop-batches-side > .visual-card:only-child,
.request-layout .printshop-batches-side > .card:only-child {
  max-width: 720px;
}

/* La tarjeta de detalle debe poder respirar. */
.request-layout .request-detail-card,
.request-layout .request-detail-certificate,
.request-layout .request-students-card {
  width: 100%;
  min-width: 0;
}

/* Mejor distribución de datos de certificados. */
.request-layout .request-detail-grid.compact {
  grid-template-columns: repeat(3, minmax(150px, 1fr));
}

/* Formularios de alumnos en columnas cómodas. */
.request-layout .request-student-inline-form {
  grid-template-columns: minmax(280px, 1fr) minmax(160px, 220px) auto;
}

.request-layout .request-student-bulk-form {
  grid-template-columns: minmax(360px, 1fr) minmax(160px, 220px) auto;
}

.request-layout .request-student-inline-form button,
.request-layout .request-student-bulk-form button {
  min-height: 44px;
  align-self: end;
}

.request-layout .request-student-bulk-form textarea {
  min-height: 120px;
}

/* Resumen de alumnos con más espacio. */
.request-layout .request-students-summary {
  grid-template-columns: repeat(3, minmax(150px, 1fr));
}

/* Evita que textos largos se encimen. */
.request-layout .request-students-header,
.request-layout .request-detail-certificate-header {
  min-width: 0;
}

.request-layout .request-students-header p,
.request-layout .request-detail-note p,
.request-layout .request-detail-item strong,
.request-layout .request-detail-item small {
  overflow-wrap: anywhere;
}

@media (max-width: 1500px) {
  .request-layout .printshop-batches-side {
    grid-template-columns: minmax(0, 1fr);
  }

  .request-layout .printshop-batches-side > .printshop-panel:only-child,
  .request-layout .printshop-batches-side > .visual-card:only-child,
  .request-layout .printshop-batches-side > .card:only-child {
    max-width: 100%;
  }
}

@media (max-width: 1050px) {
  .request-layout .request-detail-grid.compact,
  .request-layout .request-students-summary,
  .request-layout .request-student-inline-form,
  .request-layout .request-student-bulk-form {
    grid-template-columns: 1fr;
  }

  .request-layout .request-student-inline-form button,
  .request-layout .request-student-bulk-form button {
    width: 100%;
  }
}

