/* Validacion publica de certificados: rediseño visual */
.certificate-validation-page {
  padding: 26px;
  align-items: stretch;
  background:
    radial-gradient(circle at 8% 10%, rgba(237, 28, 36, 0.12), transparent 24%),
    radial-gradient(circle at 92% 14%, rgba(15, 79, 196, 0.16), transparent 28%),
    linear-gradient(180deg, #f8fbff 0%, #eef4fb 100%);
}

.certificate-validation-shell {
  width: min(1120px, 100%);
  margin: auto;
  display: grid;
  gap: 18px;
}

.certificate-validation-shell > .certificate-validation-state {
  border-radius: 24px;
  background: #ffffff;
  box-shadow: 0 20px 48px rgba(15, 35, 72, 0.1);
}

.certificate-validation-brand {
  min-height: 74px;
  padding: 14px 18px;
  border: 1px solid #dbe7ff;
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.06);
}

.certificate-validation-brand-logo {
  width: 128px;
  max-width: 34vw;
  height: auto;
  object-fit: contain;
}

.certificate-validation-card {
  width: 100%;
  border-radius: 26px;
  background:
    linear-gradient(#ffffff, #ffffff) padding-box,
    linear-gradient(135deg, rgba(15, 79, 196, 0.34), rgba(237, 28, 36, 0.2)) border-box;
  border: 1px solid transparent;
  box-shadow: 0 24px 60px rgba(15, 35, 72, 0.13);
}

.certificate-validation-content-card {
  grid-template-columns: minmax(320px, 0.9fr) minmax(0, 1.1fr);
  grid-template-areas:
    "state details"
    "state footer";
  gap: 18px;
  align-items: stretch;
}

.certificate-validation-loading-card {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 34px;
}

.certificate-validation-loading-card h1 {
  margin: 0 0 6px;
  color: #061b3d;
}

.certificate-validation-loading-card p {
  margin: 0;
  color: #526176;
}

.certificate-validation-result-card {
  padding: 0;
}

.certificate-validation-content-card .certificate-validation-state {
  grid-area: state;
  min-height: 430px;
  align-content: center;
  position: relative;
  overflow: hidden;
}

.certificate-validation-content-card .certificate-validation-state::after {
  content: "";
  position: absolute;
  inset: auto -70px -110px auto;
  width: 260px;
  height: 260px;
  border: 34px solid rgba(255, 255, 255, 0.28);
  border-radius: 50%;
}

.certificate-validation-state.success,
.certificate-validation-state.info {
  color: #ffffff;
  border: 0;
  background:
    radial-gradient(circle at 82% 16%, rgba(255, 255, 255, 0.22), transparent 24%),
    linear-gradient(135deg, #06327a 0%, #0f4fc4 56%, #0f9488 100%);
}

.certificate-validation-state.danger {
  color: #ffffff;
  border: 0;
  background:
    radial-gradient(circle at 86% 18%, rgba(255, 255, 255, 0.18), transparent 24%),
    linear-gradient(135deg, #7f1d1d 0%, #b42318 58%, #ed1c24 100%);
}

.certificate-validation-state h1,
.certificate-validation-state p,
.certificate-validation-state small {
  position: relative;
  z-index: 1;
}

.certificate-validation-content-card .certificate-validation-state h1,
.certificate-validation-content-card .certificate-validation-state p,
.certificate-validation-state.danger h1,
.certificate-validation-state.danger p,
.certificate-validation-state.danger small {
  color: #ffffff;
}

.certificate-validation-icon {
  position: relative;
  z-index: 1;
  width: 76px;
  height: 76px;
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.28);
  color: #ffffff;
  box-shadow: none;
}

.certificate-validation-icon svg {
  width: 38px;
  height: 38px;
  fill: currentColor;
}

.certificate-validation-pill {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 0 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.16);
  color: #ffffff;
  font-size: 12px;
  font-weight: 850;
}

.certificate-validation-details {
  grid-area: details;
  align-self: start;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.certificate-validation-details div {
  border-radius: 16px;
  background: #f8fbff;
  border: 1px solid #dbe6f4;
  min-height: 86px;
}

.certificate-validation-footer {
  grid-area: footer;
  align-self: end;
  border-radius: 16px;
  border-color: #b9cdfa;
  background: #eef5ff;
}

@media (max-width: 820px) {
  .certificate-validation-page {
    padding: 18px;
