  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.installation-templates-metrics-grid article {
  position: relative;
  min-height: 112px;
  padding: 18px;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: #ffffff;
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.07);
  overflow: hidden;
}

.installation-templates-metrics-grid article::after {
