}

.installation-template-status {
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.installation-template-status.active {
  background: #dcfce7;
  color: #166534;
}

.installation-template-status.inactive {
  background: #fee2e2;
  color: #991b1b;
}

.installation-template-description {
  margin: 0;
  color: #526176;
  font-size: 13px;
  line-height: 1.5;
}

.installation-template-card-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.installation-template-card-metrics div {
  border: 1px solid #edf1f7;
  border-radius: 12px;
  background: #ffffff;
  padding: 10px;
}

.installation-template-card-metrics span {
  display: block;
  color: #64748b;
  font-size: 10px;
  font-weight: 900;
  line-height: 1.2;
  min-height: 24px;
}

.installation-template-card-metrics strong {
  display: block;
  color: #0f4fc4;
  font-size: 20px;
  margin-top: 4px;
}

.installation-template-card-footer {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding-top: 12px;
  border-top: 1px solid #e5eaf2;
}

.installation-template-card-footer > span {
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
}

.installation-template-card-footer > div {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.installation-template-card-footer button {
  border: 1px solid #dbe7ff;
  border-radius: 9px;
  background: #ffffff;
  color: #0f4fc4;
  padding: 8px 11px;
  font-size: 12px;
  font-weight: 900;
}

@media (max-width: 1200px) {
  .installation-templates-metrics-grid,
  .installation-template-card-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .installation-templates-toolbar {
    grid-template-columns: 1fr 1fr;
  }

  .installation-template-search {
    grid-column: 1 / -1;
    width: 100%;
  }
}

@media (max-width: 850px) {
  .installation-templates-header,
  .spare-parts-header,
  .installation-template-section-header,
  .installation-template-card-footer {
    flex-direction: column;
    align-items: flex-start;
