/* =========================================================
   SOPORTE TÉCNICO - INSTALACIONES REALES DESDE PLANTILLA
========================================================= */

.installations-workspace {
  display: grid;
  gap: 18px;
}

.installation-subtabs {
  display: inline-flex;
  width: fit-content;
  gap: 7px;
  padding: 6px;
  border: 1px solid #dce6f5;
  border-radius: 999px;
  background: #eef4fb;
}

.installation-subtabs button {
  border: none;
  border-radius: 999px;
  background: transparent;
  color: #526176;
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 900;
}

.installation-subtabs button.active {
  background: #ffffff;
  color: #0f4fc4;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
}

.installation-runs-workspace {
  display: grid;
  gap: 18px;
}

.installation-runs-header,
.installation-run-detail-header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
}

.installation-runs-header h2,
.installation-run-detail-header h3,
.installation-run-form-panel h3 {
  margin: 0;
  color: #0f172a;
  letter-spacing: -0.03em;
}

.installation-runs-header p,
.installation-run-detail-header p,
.installation-run-form-panel p {
  margin: 6px 0 0;
  color: #64748b;
  line-height: 1.45;
}

.installation-runs-header-actions,
.installation-run-detail-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.installation-alert-strip {
  border-left-color: #0f4fc4;
  border-color: #bad0ff;
  background:
    radial-gradient(circle at 6% 18%, rgba(15, 79, 196, 0.12), transparent 28%),
    linear-gradient(135deg, #f8fbff, #ffffff);
}

.installation-runs-metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.installation-runs-metrics-grid article {
  position: relative;
  min-height: 112px;
  padding: 18px;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: #ffffff;
  box-shadow: 0 14px 34px rgba(15, 23, 42, 0.07);
  overflow: hidden;
}

.installation-runs-metrics-grid article::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 5px;
  background: #0f4fc4;
}

.installation-runs-metrics-grid article.warning::after {
  background: #d99a00;
}

.installation-runs-metrics-grid article.success::after {
  background: #16a34a;
}

.installation-runs-metrics-grid span,
.installation-run-progress-card span,
.installation-run-card-progress span,
.installation-run-card-meta strong {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.installation-runs-metrics-grid strong {
  display: block;
  margin-top: 8px;
  color: #0f172a;
  font-size: 32px;
  line-height: 1;
}

.installation-runs-metrics-grid p {
  margin: 9px 0 0;
  color: #64748b;
  font-size: 13px;
}

.installation-run-form-panel,
.installation-run-detail-panel,
.installation-runs-list-panel {
  padding: 22px;
  border: 1px solid #e2e8f0;
  border-radius: 26px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.08);
}

.installation-run-detail-panel {
  display: grid;
  gap: 18px;
  border-left: 6px solid #0f4fc4;
}

.installation-run-status {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border-radius: 999px;
  padding: 7px 11px;
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.installation-run-status.progress {
  background: #eaf2ff;
  color: #0f4fc4;
  border: 1px solid #bad0ff;
}

.installation-run-status.completed {
  background: #dcfce7;
  color: #166534;
  border: 1px solid #bbf7d0;
}

.installation-run-status.paused,
.installation-run-status.draft {
  background: #fff4d8;
  color: #92400e;
  border: 1px solid #fde68a;
}

.installation-run-status.cancelled {
  background: #fee2e2;
  color: #991b1b;
  border: 1px solid #fecaca;
}

.installation-run-progress-card {
  display: grid;
  grid-template-columns: 230px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
  border: 1px solid #dbe7ff;
  border-radius: 18px;
  background: #f8fbff;
  padding: 16px;
}

.installation-run-progress-card strong {
  display: block;
  color: #0f4fc4;
  font-size: 34px;
  line-height: 1;
  margin-top: 4px;
}

.installation-run-progress-card p {
  margin: 7px 0 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.35;
}

.installation-run-status-row {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: 16px;
  align-items: start;
}

.installation-run-status-row label {
  margin: 0;
  display: grid;
  gap: 8px;
  color: #0f172a;
  font-size: 13px;
  font-weight: 900;
}

.installation-run-status-row textarea {
  min-height: 74px;
}

.installation-run-checklist {
  display: grid;
  gap: 14px;
}

.installation-run-section {
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: linear-gradient(180deg, #ffffff, #fbfdff);
  padding: 15px;
}

.installation-run-section-header {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding-bottom: 12px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 12px;
}

.installation-run-section-header > span {
  width: 42px;
  height: 42px;
  border-radius: 13px;
  display: grid;
  place-items: center;
  background: #eaf2ff;
  color: #0f4fc4;
  font-weight: 900;
  font-size: 18px;
}

.installation-run-section-header h4 {
  margin: 0;
  color: #0f172a;
  font-size: 15px;
}

.installation-run-section-header p {
  margin: 3px 0 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.35;
}

.installation-run-item-list {
  display: grid;
  gap: 10px;
}

.installation-run-item {
  display: grid;
  gap: 10px;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #ffffff;
  padding: 12px;
  transition: 0.16s ease;
}

.installation-run-item.completed {
  border-color: #bbf7d0;
  background: #f0fdf4;
}

.installation-run-check-row {
  margin: 0;
  display: grid;
  grid-template-columns: 20px 30px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  cursor: pointer;
}

.installation-run-check-row input {
  width: 18px;
  height: 18px;
  margin-top: 4px;
  accent-color: #16a34a;
}

.installation-run-check-row > span {
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #f1f5f9;
  color: #16a34a;
  font-weight: 900;
}

.installation-run-check-row strong {
  display: block;
  color: #0f172a;
  font-size: 14px;
  line-height: 1.3;
}

.installation-run-check-row small {
  display: block;
  color: #64748b;
  font-size: 11px;
  margin-top: 3px;
}

.installation-run-item textarea {
  min-height: 58px;
  background: #fbfdff;
}

.installation-run-save-actions {
  border-top: 1px solid #e5eaf2;
  padding-top: 16px;
}

.installation-runs-toolbar {
  display: grid;
  grid-template-columns: minmax(280px, 1fr) 220px;
  gap: 12px;
  margin-bottom: 16px;
}

.installation-run-card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.installation-run-card {
  display: grid;
  gap: 13px;
  padding: 16px;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: linear-gradient(180deg, #ffffff, #fbfdff);
  box-shadow: 0 14px 32px rgba(15, 23, 42, 0.07);
}

.installation-run-card-top {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: flex-start;
}

.installation-run-icon {
  width: 46px;
  height: 46px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #0f4fc4, #38bdf8);
  color: #ffffff;
  font-weight: 900;
}

.installation-run-card-top strong {
  display: block;
  color: #0f172a;
  font-size: 15px;
  line-height: 1.25;
}

.installation-run-card-top p {
  margin: 4px 0 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.35;
}

.installation-run-card-meta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.installation-run-card-meta span {
  display: block;
  border: 1px solid #edf1f7;
  border-radius: 12px;
  background: #ffffff;
  padding: 9px;
  color: #0f172a;
  font-size: 12px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.installation-run-card-progress {
  display: grid;
  grid-template-columns: 70px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
}

.installation-run-card-progress strong {
  color: #0f4fc4;
  font-size: 18px;
}

.installation-run-card-footer {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
  padding-top: 12px;
  border-top: 1px solid #e5eaf2;
}

.installation-run-card-footer span {
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
}

.installation-run-card-footer button {
  border: 1px solid #dbe7ff;
  border-radius: 9px;
  background: #ffffff;
  color: #0f4fc4;
  padding: 8px 11px;
  font-size: 12px;
  font-weight: 900;
}

@media (max-width: 1200px) {
  .installation-runs-metrics-grid,
  .installation-run-card-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 850px) {
  .installation-subtabs,
  .installation-runs-header,
  .installation-run-detail-header,
  .installation-run-card-footer {
    width: 100%;
    flex-direction: column;
    align-items: flex-start;
  }

  .installation-subtabs {
    display: grid;
    grid-template-columns: 1fr;
    border-radius: 18px;
  }

  .installation-runs-header-actions,
  .installation-run-detail-actions,
  .installation-run-detail-actions button,
  .installation-run-detail-actions .installation-run-status {
    width: 100%;
  }

  .installation-runs-metrics-grid,
  .installation-run-card-grid,
  .installation-runs-toolbar,
  .installation-run-progress-card,
  .installation-run-status-row,
  .installation-run-card-top,
  .installation-run-card-meta,
  .installation-run-card-progress {
    grid-template-columns: 1fr;
  }

  .installation-run-check-row {
    grid-template-columns: 20px 28px minmax(0, 1fr);
  }
}

