@media (max-width: 760px) {
  .installation-equipment-header,
  .installation-equipment-linked-card,
  .installation-equipment-option,
  .installation-equipment-filters,
  .installation-run-card-meta {
    grid-template-columns: 1fr;
  }

  .installation-equipment-header > span,
  .installation-equipment-linked-card button,
  .installation-equipment-option button {
