}

.installation-spare-part-used-card p,
.installation-spare-part-option p {
  margin: 4px 0;
  color: #475569;
  font-size: 12px;
  line-height: 1.35;
}

.installation-spare-part-used-card small,
.installation-spare-part-option small {
  display: block;
  color: #64748b;
  font-size: 11px;
  line-height: 1.35;
}

.installation-spare-parts-selector {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid #d9f8ef;
}

.installation-spare-parts-selector-header {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.installation-spare-parts-selector-header h5 {
  margin: 0 0 4px;
  color: #0f172a;
  font-size: 15px;
}

.installation-spare-parts-selector-header p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
}

.installation-spare-parts-filters {
  display: grid;
  grid-template-columns: minmax(260px, 1.4fr) minmax(170px, 0.6fr) minmax(170px, 0.6fr);
  gap: 10px;
  align-items: center;
  margin-bottom: 12px;
}

.installation-spare-parts-filters select {
  min-height: 46px;
  border: 1px solid #d9e2ef;
  border-radius: 10px;
  background: #ffffff;
  color: #0f2442;
  padding: 0 12px;
  font-weight: 800;
}

.installation-spare-parts-search {
  width: 100%;
}

.installation-spare-part-option-actions {
  display: grid;
  grid-template-columns: 76px auto;
  gap: 8px;
  align-items: center;
}

.installation-spare-part-option-actions input {
  height: 40px;
  border: 1px solid #d9e2ef;
  border-radius: 10px;
  padding: 0 10px;
  text-align: center;
