}

.installation-run-card-meta {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

@media (max-width: 1100px) {
  .installation-spare-parts-filters,
  .installation-run-card-meta {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .installation-spare-parts-header,
  .installation-spare-part-used-card,
  .installation-spare-part-option,
  .installation-spare-parts-filters,
  .installation-spare-part-option-actions,
  .installation-run-card-meta {
    grid-template-columns: 1fr;
  }

  .installation-spare-parts-header > span,
  .installation-spare-part-used-card button,
  .installation-spare-part-option-actions button {
    width: 100%;
  }
}

/* =========================================================
   SOPORTE TÉCNICO - HISTORIAL DE INSTALACIONES RELACIONADAS
========================================================= */

.technical-related-installations-card,
.location-installations-card {
  margin-top: 18px;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: linear-gradient(180deg, #ffffff, #fbfdff);
  padding: 18px;
  box-shadow: 0 14px 32px rgba(15, 23, 42, 0.06);
}

.related-installations-list {
  display: grid;
  gap: 12px;
}

.related-installation-card {
  border: 1px solid #e5eaf2;
  border-radius: 16px;
  background: #ffffff;
  padding: 14px;
  transition: 0.18s ease;
}

.related-installation-card:hover {
  border-color: #b9cdfa;
  box-shadow: 0 12px 26px rgba(15, 23, 42, 0.07);
  transform: translateY(-1px);
}

.related-installation-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
  margin-bottom: 12px;
}

.related-installation-top h4 {
  margin: 8px 0 4px;
  color: #0f2442;
  font-size: 15px;
  line-height: 1.3;
}

.related-installation-top p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.4;
}

.related-installation-button {
  flex-shrink: 0;
  padding: 8px 11px !important;
  font-size: 12px !important;
}

.related-installation-meta {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 9px;
  margin-bottom: 11px;
}

.related-installation-meta span {
  border: 1px solid #edf1f7;
  border-radius: 12px;
  background: #f8fbff;
  padding: 9px;
  min-width: 0;
}

.related-installation-meta small {
  display: block;
  color: #64748b;
  font-size: 10px;
  font-weight: 900;
  margin-bottom: 4px;
}

.related-installation-meta strong {
  display: block;
  color: #0f2442;
  font-size: 11px;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.related-installation-foot {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.related-installation-foot span {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  border-radius: 999px;
  background: #eaf2ff;
  color: #0f4fc4;
  padding: 6px 9px;
  font-size: 11px;
  font-weight: 900;
}

.related-installation-foot span:nth-child(2) {
  background: #fff4d8;
  color: #d99a00;
}

.related-installation-foot span:nth-child(3) {
  background: #dcfce7;
  color: #16a34a;
}

@media (max-width: 900px) {
  .related-installation-top {
    flex-direction: column;
  }

  .related-installation-button {
    width: 100%;
  }

  .related-installation-meta {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 620px) {
  .related-installation-meta {
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   SOPORTE TÉCNICO - FASE 5D UBICACIÓN DE EQUIPOS
========================================================= */

.installation-location-update-card {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  gap: 14px;
  align-items: flex-start;
  border-radius: 18px;
  padding: 16px;
  margin-top: 16px;
  border: 1px solid #dbe7ff;
  background: linear-gradient(180deg, #ffffff, #f8fbff);
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.06);
}

.installation-location-update-card > div:first-child {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  font-size: 20px;
  font-weight: 900;
}

.installation-location-update-card strong {
  display: block;
  color: #0f2442;
  font-size: 14px;
  margin-bottom: 5px;
}

.installation-location-update-card p {
  margin: 0;
  color: #526176;
  font-size: 13px;
  line-height: 1.5;
}

.installation-location-update-card.info {
  border-color: #bad0ff;
  background: linear-gradient(135deg, #ffffff, #f1f6ff);
}

.installation-location-update-card.info > div:first-child {
  background: #eaf2ff;
  color: #0f4fc4;
}

.installation-location-update-card.success {
  border-color: #bbf7d0;
  background: linear-gradient(135deg, #ffffff, #f0fdf4);
}

.installation-location-update-card.success > div:first-child {
  background: #dcfce7;
  color: #16a34a;
}

.installation-location-update-card.warning {
  border-color: #fed7aa;
  background: linear-gradient(135deg, #ffffff, #fff7ed);
}

.installation-location-update-card.warning > div:first-child {
  background: #ffedd5;
  color: #f97316;
}

@media (max-width: 700px) {
  .installation-location-update-card {
    grid-template-columns: 1fr;
  }
}


/* =========================================================
   SOPORTE TÉCNICO - EVIDENCIAS DE INSTALACIÓN
========================================================= */

.installation-evidence-panel {
  display: grid;
  gap: 16px;
  padding: 18px;
  margin-top: 18px;
  border: 1px solid #dbe7ff;
  border-radius: 22px;
  background: linear-gradient(180deg, #ffffff, #f8fbff);
  box-shadow: 0 14px 32px rgba(15, 23, 42, 0.06);
}

.installation-evidence-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

.installation-evidence-header h3 {
  margin: 2px 0 6px;
  color: #0f2442;
  font-size: 18px;
}

.installation-evidence-header p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.45;
}

.installation-evidence-counter {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: fit-content;
  border-radius: 999px;
  background: #eaf2ff;
  color: #0f4fc4;
  padding: 7px 11px;
  font-size: 12px;
  font-weight: 900;
}

.installation-evidence-uploader {
  display: grid;
  grid-template-columns: minmax(260px, 0.7fr) minmax(0, 1fr);
  gap: 16px;
  align-items: stretch;
}

.installation-evidence-dropzone {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  min-height: 190px;
  margin: 0;
  padding: 22px;
  border: 2px dashed #bad0ff;
  border-radius: 18px;
  background: #f8fbff;
  color: #0f4fc4;
  text-align: center;
  cursor: pointer;
  transition: 0.18s ease;
}

.installation-evidence-dropzone:hover {
  border-color: #0f4fc4;
  background: #eef5ff;
}

.installation-evidence-dropzone input {
  display: none;
}

.installation-evidence-dropzone span {
  display: grid;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 24px;
  font-weight: 900;
}

.installation-evidence-dropzone strong {
  color: #0f2442;
  font-size: 14px;
}

.installation-evidence-dropzone p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
}

.installation-evidence-form-side {
  display: grid;
  gap: 12px;
  align-content: start;
}

.installation-evidence-form-side label {
  margin: 0;
  display: grid;
  gap: 8px;
  color: #0f2442;
  font-size: 12px;
  font-weight: 900;
}

.installation-evidence-selected-files {
  display: grid;
  gap: 7px;
  border: 1px solid #dbe7ff;
  border-radius: 14px;
  background: #ffffff;
  padding: 12px;
}

.installation-evidence-selected-files strong {
  color: #0f2442;
  font-size: 12px;
}

.installation-evidence-selected-files span {
  display: block;
  color: #64748b;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.installation-evidence-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.installation-evidence-actions button {
  border-radius: 10px;
  padding: 10px 13px;
  font-size: 12px;
  font-weight: 900;
}

.installation-evidence-note {
  margin: 0;
  color: #b45309;
  font-size: 12px;
  line-height: 1.45;
}

.installation-evidence-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 14px;
}

.installation-evidence-card {
  overflow: hidden;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.05);
}

.installation-evidence-preview {
  position: relative;
  min-height: 180px;
  background: #0f172a;
  display: grid;
  place-items: center;
}

.installation-evidence-preview img,
.installation-evidence-preview video {
  width: 100%;
  height: 210px;
  display: block;
  object-fit: cover;
  background: #0f172a;
}

.installation-evidence-type {
  position: absolute;
  top: 10px;
  left: 10px;
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 900;
  color: #ffffff;
  background: rgba(15, 79, 196, 0.9);
  backdrop-filter: blur(6px);
}

.installation-evidence-type.video {
  background: rgba(237, 28, 36, 0.9);
}

.installation-evidence-placeholder {
  color: #ffffff;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.installation-evidence-content {
  display: grid;
  gap: 7px;
  padding: 13px;
}

.installation-evidence-content strong {
  color: #0f2442;
  font-size: 13px;
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.installation-evidence-content p {
  margin: 0;
  color: #526176;
  font-size: 12px;
  line-height: 1.45;
}

.installation-evidence-content small {
  color: #64748b;
  font-size: 11px;
  line-height: 1.35;
}

.installation-evidence-card-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 0 13px 13px;
}

.installation-evidence-card-actions a,
.installation-evidence-card-actions button {
  border: 1px solid #dbe7ff;
  border-radius: 9px;
  background: #ffffff;
  color: #0f4fc4;
  padding: 8px 11px;
  text-decoration: none;
  font-size: 12px;
  font-weight: 900;
}

.installation-evidence-empty {
  border: 1px dashed #cbd7e6;
  border-radius: 18px;
  background: #fbfdff;
  padding: 18px;
  text-align: center;
}

.installation-evidence-empty strong {
  color: #0f2442;
  font-size: 14px;
}

.installation-evidence-empty p {
  margin: 5px 0 0;
  color: #64748b;
  font-size: 13px;
}

@media (max-width: 900px) {
  .installation-evidence-header,
  .installation-evidence-uploader {
    grid-template-columns: 1fr;
    display: grid;
  }

  .installation-evidence-counter {
    width: fit-content;
  }

  .installation-evidence-actions {
    justify-content: stretch;
  }

  .installation-evidence-actions button {
    flex: 1;
  }
}

/* =========================================================
   SOPORTE TÉCNICO - BLOQUEO Y CORRECCIÓN ADMINISTRATIVA
========================================================= */

.installation-admin-lock-card,
.installation-admin-correction-note {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  gap: 14px;
  align-items: flex-start;
  border-radius: 16px;
  padding: 15px 16px;
  margin: 14px 0;
  border: 1px solid #dbe7ff;
  background: linear-gradient(135deg, #f8fbff, #ffffff);
  color: #0f2442;
}

.installation-admin-lock-card > div:first-child,
.installation-admin-correction-note::before {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: #eaf2ff;
  color: #0f4fc4;
  font-weight: 900;
}

.installation-admin-lock-card > div:first-child span {
  font-size: 18px;
}

.installation-admin-lock-card strong,
.installation-admin-correction-note strong {
  display: block;
  color: #0f2442;
  font-size: 14px;
  margin-bottom: 5px;
}

.installation-admin-lock-card p,
.installation-admin-lock-card small,
.installation-admin-correction-note {
  color: #526176;
  font-size: 13px;
  line-height: 1.45;
}

.installation-admin-lock-card small {
  display: block;
  margin-top: 6px;
  color: #0f4fc4;
  font-weight: 800;
}

.installation-admin-lock-card.locked {
  border-color: #cbd5e1;
  background: linear-gradient(135deg, #f8fafc, #ffffff);
}

.installation-admin-lock-card.locked > div:first-child {
  background: #f1f5f9;
  color: #475569;
}

.installation-admin-lock-card.editing {
  border-color: #fed7aa;
  background: linear-gradient(135deg, #fff7ed, #ffffff);
}

.installation-admin-lock-card.editing > div:first-child {
  background: #ffedd5;
  color: #f97316;
}

.installation-admin-correction-note {
  grid-template-columns: minmax(0, 1fr);
  border-color: #bad0ff;
  background: #f8fbff;
  margin: 12px 0;
}

.installation-admin-correction-note::before {
  content: "i";
  display: inline-grid;
  margin-bottom: 4px;
}

.installation-admin-correction-note.warning {
  border-color: #fed7aa;
  background: #fff7ed;
  color: #9a3412;
}

.installation-admin-correction-note.warning::before {
  content: "!";
  background: #ffedd5;
  color: #f97316;
}

.installation-run-save-actions button:disabled {
  opacity: 0.68;
  cursor: not-allowed;
}


/* =========================================================
   SOPORTE TÉCNICO - FILTROS AVANZADOS DE INSTALACIONES
========================================================= */

.installation-advanced-filters {
  display: grid;
  gap: 16px;
  margin-bottom: 18px;
  padding: 18px;
  border: 1px solid #dbe7ff;
  border-radius: 24px;
  background:
    radial-gradient(circle at top right, rgba(15, 79, 196, 0.08), transparent 30%),
    linear-gradient(180deg, #ffffff, #f8fbff);
  box-shadow: 0 16px 34px rgba(15, 23, 42, 0.07);
}

.installation-advanced-filters-header {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  align-items: flex-start;
  padding-bottom: 13px;
  border-bottom: 1px solid #e5eaf2;
}

.installation-advanced-filters-header strong {
  display: block;
  color: #0f2442;
  font-size: 16px;
  margin-bottom: 4px;
}

.installation-advanced-filters-header p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.4;
}

.installation-advanced-filters-grid {
  display: grid;
  grid-template-columns: minmax(280px, 1.6fr) repeat(4, minmax(150px, 1fr));
  gap: 12px;
  align-items: end;
}

.installation-advanced-filters-grid label {
  margin: 0;
  display: grid;
  gap: 7px;
  color: #0f2442;
  font-size: 12px;
  font-weight: 900;
}

.installation-advanced-filters-grid input,
.installation-advanced-filters-grid select {
  width: 100%;
  min-height: 44px;
  border: 1px solid #d9e2ef;
  border-radius: 12px;
  background: #ffffff;
  color: #0f2442;
  padding: 0 12px;
  font-size: 13px;
  font-weight: 700;
}

.installation-advanced-filters-grid input:focus,
.installation-advanced-filters-grid select:focus {
  outline: none;
  border-color: #0f4fc4;
  box-shadow: 0 0 0 4px rgba(15, 79, 196, 0.11);
}

.installation-filter-search {
  grid-column: span 2;
}

.installation-filter-search .visual-search {
  width: 100%;
  height: 44px;
  background: #ffffff;
}

.installation-filter-search .visual-search input {
  min-height: auto;
  border: none;
  border-radius: 0;
  padding: 0;
  font-weight: 600;
  background: transparent;
}

.installation-filter-summary-row {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
}

.installation-filter-summary-row span {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  width: fit-content;
  border: 1px solid #dbe7ff;
  border-radius: 999px;
  background: #ffffff;
  color: #526176;
  padding: 7px 10px;
  font-size: 12px;
  font-weight: 800;
}

.installation-filter-summary-row strong {
  display: inline-grid;
  place-items: center;
  min-width: 24px;
  height: 24px;
  border-radius: 999px;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 12px;
}

@media (max-width: 1450px) {
  .installation-advanced-filters-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .installation-filter-search {
    grid-column: 1 / -1;
  }
}

@media (max-width: 900px) {
  .installation-advanced-filters-header {
    flex-direction: column;
  }

  .installation-advanced-filters-header button {
    width: 100%;
  }

  .installation-advanced-filters-grid {
    grid-template-columns: 1fr;
  }

  .installation-filter-search {
    grid-column: auto;
  }

  .installation-filter-summary-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .installation-filter-summary-row span {
    width: 100%;
  }
}

@media (max-width: 620px) {
  .installation-filter-summary-row {
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   SOLICITUDES DE COMPRA
========================================================= */

.purchase-requests-page {
  display: grid;
  gap: 18px;
}

.purchase-page-header {
  margin-bottom: 2px;
}

.purchase-metrics-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
}

.purchase-metrics-grid .simple-metric {
  min-height: 112px;
  padding: 17px;
  gap: 15px;
}

.purchase-form-card {
  margin-top: 0;
}

.purchase-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px 18px;
}

.purchase-form .full {
  grid-column: 1 / -1;
}

.purchase-form-actions {
  grid-column: 1 / -1;
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  flex-wrap: wrap;
  padding-top: 6px;
}

.purchase-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 410px;
  gap: 20px;
  align-items: start;
}

.purchase-list-card,
.purchase-detail-card {
  margin-top: 0;
}

.purchase-toolbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
  padding-bottom: 16px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 16px;
}

.purchase-toolbar h3 {
  margin: 0 0 5px;
  color: #0f2442;
  font-size: 18px;
}

.purchase-toolbar p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
}

.purchase-filters {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.purchase-filters select {
  width: 180px;
  height: 46px;
  border: 1px solid #d9e2ef;
  border-radius: 10px;
  background: #ffffff;
  color: #0f2442;
  padding: 0 12px;
  font-weight: 800;
}

.purchase-search {
  width: 270px;
}

.purchase-request-list {
  display: grid;
  gap: 12px;
}

.purchase-request-card {
  width: 100%;
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 14px;
  align-items: start;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: linear-gradient(180deg, #ffffff, #fbfdff);
  padding: 14px;
  text-align: left;
  color: inherit;
  transition: 0.18s ease;
}

.purchase-request-card:hover {
  border-color: #b9cdfa;
  box-shadow: 0 16px 32px rgba(15, 23, 42, 0.08);
  transform: translateY(-1px);
}

.purchase-request-card.selected {
  border-color: #0f4fc4;
  box-shadow: 0 0 0 3px rgba(15, 79, 196, 0.11), 0 16px 32px rgba(15, 23, 42, 0.08);
}

.purchase-request-icon,
.purchase-detail-avatar {
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: linear-gradient(135deg, #0f4fc4, #ed1c24);
  color: white;
  font-weight: 900;
  box-shadow: 0 12px 24px rgba(15, 79, 196, 0.18);
}

.purchase-request-icon {
  width: 58px;
  height: 58px;
  font-size: 16px;
}

.purchase-detail-avatar {
  width: 62px;
  height: 62px;
  font-size: 18px;
}

.purchase-request-content {
  min-width: 0;
}

.purchase-request-title-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
  margin-bottom: 10px;
}

.purchase-request-title-row h4 {
  margin: 0 0 4px;
  color: #0f2442;
  font-size: 16px;
  line-height: 1.25;
}

.purchase-request-title-row span,
.purchase-request-meta span {
  color: #64748b;
  font-size: 12px;
}

.purchase-request-badges,
.purchase-detail-badges {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.purchase-request-card p {
  margin: 0 0 12px;
  color: #526176;
  font-size: 13px;
  line-height: 1.5;
}

.purchase-request-meta {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.purchase-request-meta span {
  display: inline-flex;
  border: 1px solid #e5eaf2;
  border-radius: 999px;
  background: #f8fafc;
  padding: 5px 8px;
  font-weight: 800;
}

.purchase-card-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 12px;
}

.danger-outline-button {
  color: #b42318 !important;
  border-color: #fecaca !important;
  background: #fff5f5 !important;
}

.purchase-badge {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  max-width: 170px;
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.2;
  border: 1px solid transparent;
  white-space: normal;
  text-align: center;
}

.purchase-badge.tone-blue {
  background: #eaf2ff;
  color: #0f4fc4;
  border-color: #bad0ff;
}

.purchase-badge.tone-green {
  background: #dcfce7;
  color: #166534;
  border-color: #bbf7d0;
}

.purchase-badge.tone-gold {
  background: #fff4d8;
  color: #92400e;
  border-color: #fde68a;
}

.purchase-badge.tone-orange {
  background: #ffedd5;
  color: #9a3412;
  border-color: #fed7aa;
}

.purchase-badge.tone-purple {
  background: #ede9fe;
  color: #7c3aed;
  border-color: #ddd6fe;
}

.purchase-badge.tone-teal {
  background: #ccfbf1;
  color: #0f766e;
  border-color: #99f6e4;
}

.purchase-badge.tone-red {
  background: #fee2e2;
  color: #991b1b;
  border-color: #fecaca;
}

.purchase-badge.tone-gray {
  background: #f1f5f9;
  color: #475569;
  border-color: #e2e8f0;
}

.purchase-detail-panel {
  position: sticky;
  top: 24px;
  min-width: 0;
}

.purchase-detail-header {
  display: grid;
  grid-template-columns: 62px minmax(0, 1fr);
  gap: 14px;
  align-items: center;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 14px;
}

.purchase-detail-header h3 {
  margin: 2px 0 4px;
  color: #0f2442;
  font-size: 20px;
  line-height: 1.25;
}

.purchase-detail-header p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
}

.purchase-detail-badges {
  justify-content: flex-start;
  margin-bottom: 14px;
}

.purchase-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 14px;
}

.purchase-detail-grid div {
  border: 1px solid #edf1f7;
  border-radius: 12px;
  background: #fbfdff;
  padding: 11px;
}

.purchase-detail-grid span {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
  margin-bottom: 4px;
}

.purchase-detail-grid strong {
  color: #0f2442;
  font-size: 12px;
  line-height: 1.3;
}

.purchase-detail-section {
  border-top: 1px solid #e5eaf2;
  padding-top: 13px;
  margin-top: 13px;
}

.purchase-detail-section strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
  margin-bottom: 6px;
}

.purchase-detail-section p {
  margin: 0;
  color: #526176;
  font-size: 13px;
  line-height: 1.55;
  white-space: pre-wrap;
}

.purchase-detail-section a {
  color: #0f4fc4;
  font-size: 13px;
  font-weight: 900;
  overflow-wrap: anywhere;
}

.purchase-admin-note {
  border: 1px solid #bad0ff;
  background: #f8fbff;
  border-radius: 14px;
  padding: 12px;
}

.purchase-rejection-note {
  border: 1px solid #fecaca;
  background: #fff5f5;
  border-radius: 14px;
  padding: 12px;
}

.purchase-admin-panel {
  display: grid;
  gap: 12px;
  border: 1px solid #e5dcff;
  border-radius: 16px;
  background: #fbf9ff;
  padding: 14px;
  margin-top: 16px;
}

.purchase-admin-panel textarea {
  min-height: 80px;
}

.purchase-log-section {
  margin-top: 16px;
  border-top: 1px solid #e5eaf2;
  padding-top: 14px;
}

.purchase-log-list {
  position: relative;
  display: grid;
  gap: 11px;
  margin-top: 12px;
  padding-left: 16px;
}

.purchase-log-list::before {
  content: "";
  position: absolute;
  left: 5px;
  top: 8px;
  bottom: 8px;
  width: 2px;
  background: #dbe7ff;
}

.purchase-log-item {
  position: relative;
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr);
  gap: 8px;
  align-items: flex-start;
}

.purchase-log-item > span {
  width: 10px;
  height: 10px;
  margin-top: 4px;
  border-radius: 50%;
  background: #0f4fc4;
  box-shadow: 0 0 0 4px #eaf2ff;
  position: relative;
  z-index: 1;
}

.purchase-log-item strong {
  display: block;
  color: #0f2442;
  font-size: 12px;
  line-height: 1.35;
}

.purchase-log-item small {
  display: block;
  color: #64748b;
  font-size: 11px;
  margin-top: 3px;
}

.purchase-log-empty {
  margin-top: 12px;
  border: 1px dashed #dbe7ff;
  border-radius: 12px;
  background: #f8fbff;
  color: #64748b;
  padding: 12px;
  text-align: center;
  font-size: 12px;
}

@media (max-width: 1450px) {
  .purchase-metrics-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .purchase-layout {
    grid-template-columns: 1fr;
  }

  .purchase-detail-panel {
    position: static;
  }
}

@media (max-width: 1000px) {
  .purchase-metrics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .purchase-toolbar {
    flex-direction: column;
  }

  .purchase-filters,
  .purchase-search {
    width: 100%;
  }

  .purchase-filters select {
    flex: 1;
    min-width: 190px;
  }
}

@media (max-width: 760px) {
  .purchase-form,
  .purchase-metrics-grid,
  .purchase-detail-grid {
    grid-template-columns: 1fr;
  }

  .purchase-request-card,
  .purchase-detail-header {
    grid-template-columns: 1fr;
  }

  .purchase-request-title-row {
    flex-direction: column;
  }

  .purchase-request-badges {
    justify-content: flex-start;
  }

  .purchase-form-actions,
  .purchase-card-actions {
    flex-direction: column;
  }

  .purchase-form-actions button,
  .purchase-card-actions button,
  .purchase-admin-panel button {
    width: 100%;
  }
}

/* =========================================================
   SOLICITUDES DE COMPRA - AJUSTE COLOR + ELIMINAR
========================================================= */

.purchase-total-metric {
  border-color: #f2d0d4;
  background:
    radial-gradient(circle at 12% 16%, rgba(237, 28, 36, 0.08), transparent 30%),
    radial-gradient(circle at 92% 18%, rgba(15, 79, 196, 0.08), transparent 34%),
    #ffffff;
}

.purchase-total-metric .simple-metric-icon {
  color: #b42318;
  background: linear-gradient(135deg, #fee2e2, #eaf2ff);
}

.purchase-total-metric::after {
  background: linear-gradient(90deg, #ed1c24, #0f4fc4);
}

.purchase-delete-zone {
  display: grid;
  gap: 8px;
  margin-top: 6px;
  padding: 13px;
  border: 1px solid #fecaca;
  border-radius: 14px;
  background: #fff5f5;
}

.purchase-delete-zone strong {
  color: #991b1b;
  font-size: 13px;
}

.purchase-delete-zone p {
  margin: 0;
  color: #7f1d1d;
  font-size: 12px;
  line-height: 1.45;
}

.purchase-delete-button {
  width: 100%;
  border-radius: 10px;
  padding: 10px 12px;
  font-weight: 900;
}

.purchase-delete-button:disabled {
  opacity: 0.62;
  cursor: not-allowed;
}
