.purchase-list-card .purchase-request-card h4,
.card .purchase-request-card h4,
button.purchase-request-card h4 {
  color: #0f2442 !important;
}

.purchase-list-card .purchase-request-card p,
.card .purchase-request-card p,
button.purchase-request-card p {
  color: #526176 !important;
}

.purchase-list-card .purchase-request-title-row span,
.purchase-list-card .purchase-request-meta span,
.card .purchase-request-title-row span,
.card .purchase-request-meta span,
button.purchase-request-card .purchase-request-title-row span,
button.purchase-request-card .purchase-request-meta span {
  color: #64748b !important;
}

.purchase-list-card .purchase-request-meta span,
.card .purchase-request-meta span,
button.purchase-request-card .purchase-request-meta span {
  background: #f8fafc !important;
