}

.purchase-list-card .purchase-request-icon,
.card .purchase-request-icon,
button.purchase-request-card .purchase-request-icon {
  background: linear-gradient(135deg, #0f4fc4, #ed1c24) !important;
  color: #ffffff !important;
}

.purchase-list-card .purchase-card-actions .visual-outline-button,
.card .purchase-card-actions .visual-outline-button,
button.purchase-request-card .purchase-card-actions .visual-outline-button {
  background: #ffffff !important;
  color: #0f4fc4 !important;
}

.purchase-list-card .purchase-card-actions .danger-outline-button,
.card .purchase-card-actions .danger-outline-button,
button.purchase-request-card .purchase-card-actions .danger-outline-button {
  background: #fff5f5 !important;
  color: #b42318 !important;
  border-color: #fecaca !important;
}

.team-agenda-page {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.team-agenda-header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
  background: linear-gradient(135deg, #f8fbff 0%, #eef5ff 52%, #fff6f6 100%);
  border: 1px solid rgba(57, 86, 128, 0.1);
  border-radius: 26px;
  padding: 26px;
  box-shadow: 0 18px 40px rgba(18, 38, 63, 0.08);
}

.team-agenda-eyebrow {
  display: inline-flex;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #2f5f9f;
  margin-bottom: 8px;
}

.team-agenda-header h2 {
  margin: 0;
  color: #14233f;
  font-size: 30px;
}

.team-agenda-header p {
  margin: 8px 0 0;
  color: #5c6b82;
  max-width: 680px;
  line-height: 1.5;
}

.team-agenda-week-pill {
  min-width: 180px;
  border-radius: 18px;
  background: #ffffff;
  border: 1px solid rgba(45, 73, 115, 0.12);
  padding: 14px 16px;
  color: #6a7485;
  font-size: 12px;
  box-shadow: 0 12px 28px rgba(18, 38, 63, 0.08);
}

.team-agenda-week-pill strong {
  display: block;
  margin-top: 4px;
  color: #17233c;
  font-size: 15px;
}

.team-agenda-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.team-agenda-summary-card {
  border-radius: 22px;
  background: #ffffff;
  padding: 20px;
  border: 1px solid rgba(45, 73, 115, 0.1);
  box-shadow: 0 14px 32px rgba(18, 38, 63, 0.07);
  position: relative;
  overflow: hidden;
}

.team-agenda-summary-card::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 6px;
  opacity: 0.95;
}

.team-agenda-summary-card.green::before {
  background: #2ba66a;
}

.team-agenda-summary-card.blue::before {
  background: #356da8;
}

.team-agenda-summary-card.red::before {
  background: #cf5c5c;
}

.team-agenda-summary-card.yellow::before {
  background: #d7a72f;
}

.team-agenda-summary-card span {
  color: #66758d;
  font-size: 13px;
  font-weight: 700;
}

.team-agenda-summary-card strong {
  display: block;
  margin-top: 8px;
  color: #14233f;
  font-size: 34px;
  line-height: 1;
}

.team-agenda-summary-card p {
  margin: 8px 0 0;
  color: #7a8799;
  font-size: 13px;
}

.team-agenda-card {
  background: #ffffff;
  border: 1px solid rgba(45, 73, 115, 0.1);
  border-radius: 24px;
  padding: 22px;
  box-shadow: 0 16px 36px rgba(18, 38, 63, 0.07);
}

.team-agenda-section-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 18px;
}

.team-agenda-section-header h3 {
  margin: 0;
  color: #17233c;
  font-size: 20px;
}

.team-agenda-section-header p {
  margin: 5px 0 0;
  color: #6d7a8d;
  font-size: 14px;
}

.team-agenda-legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
  color: #6d7a8d;
  font-size: 12px;
  font-weight: 700;
}

.legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  display: inline-block;
  margin-right: -4px;
  align-self: center;
}

.legend-dot.normal {
  background: #356da8;
}

.legend-dot.active {
  background: #2ba66a;
}

.legend-dot.pending {
  background: #d7a72f;
}

.legend-dot.absence {
  background: #cf5c5c;
}

.legend-dot.rest {
  background: #9ca8b8;
}

.team-agenda-table-wrap {
  overflow-x: auto;
}

.team-agenda-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 10px;
  min-width: 980px;
}

.team-agenda-table th {
  color: #6c788c;
  font-size: 12px;
  text-align: left;
  padding: 0 10px 6px;
  vertical-align: bottom;
}

.team-agenda-table th span {
  display: block;
  color: #293a59;
  font-size: 13px;
}

.team-agenda-table th small {
  display: block;
  margin-top: 2px;
  color: #8a96a8;
  font-size: 11px;
  font-weight: 600;
}

.team-agenda-table td {
  background: #f8fafd;
  padding: 10px;
  border-top: 1px solid rgba(45, 73, 115, 0.08);
  border-bottom: 1px solid rgba(45, 73, 115, 0.08);
}

.team-agenda-table td:first-child {
  border-left: 1px solid rgba(45, 73, 115, 0.08);
  border-radius: 16px 0 0 16px;
  min-width: 220px;
}

.team-agenda-table td:last-child {
  border-right: 1px solid rgba(45, 73, 115, 0.08);
  border-radius: 0 16px 16px 0;
}

.team-person-cell {
  display: flex;
  align-items: center;
  gap: 12px;
}

.team-person-avatar {
  width: 40px;
  height: 40px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, #244d83, #a63845);
  color: #ffffff;
  font-weight: 900;
  font-size: 13px;
}

.team-person-cell strong {
  display: block;
  color: #17233c;
  font-size: 14px;
}

.team-person-cell span {
  display: block;
  color: #738095;
  font-size: 12px;
  margin-top: 2px;
}

.schedule-cell {
  min-height: 58px;
  border-radius: 14px;
  padding: 10px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  border: 1px solid transparent;
}

.schedule-cell strong {
  color: #17233c;
  font-size: 13px;
}

.schedule-cell span {
  margin-top: 3px;
  color: #647187;
  font-size: 11px;
  font-weight: 700;
}

.schedule-cell.normal {
  background: #eaf2ff;
  border-color: #cfe0f8;
}

.schedule-cell.active {
  background: #e8f8ef;
  border-color: #bde8cf;
}

.schedule-cell.pending {
  background: #fff7dd;
  border-color: #f0dc9d;
}

.schedule-cell.approved {
  background: #f1ebff;
  border-color: #d7c7ff;
}

.schedule-cell.absence,
.schedule-cell.permission {
  background: #fff0f0;
  border-color: #f2c6c6;
}

.schedule-cell.rest {
  background: #f1f4f8;
  border-color: #dde4ee;
}

.team-agenda-bottom-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
