  top: 18px;
  width: 40px;
  height: 40px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: #eaf2ff;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.45);
}

.visual-announcement-item.important .announcement-ribbon {
  background: #ffedd5;
}

.visual-notes-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.visual-note-item {
  min-height: 220px;
  box-shadow: 0 18px 40px rgba(140, 112, 32, 0.12);
}

.note-postit-pin {
  position: absolute;
  top: 12px;
  right: 16px;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: rgba(15, 36, 66, 0.22);
  box-shadow: 0 2px 0 rgba(255,255,255,0.45) inset;
}

.note-top-badges {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 6px;
}

.completed-badge {
  background: #dcfce7;
  color: #166534;
  border-color: #bbf7d0;
}

.note-color-yellow {
  background: linear-gradient(135deg, #fffdf6, #fff1a8);
  border-color: #f2d26d;
}

.note-color-blue {
  background: linear-gradient(135deg, #f6fbff, #dcecff);
  border-color: #bed4ff;
}

.note-color-green {
  background: linear-gradient(135deg, #f8fff8, #dcf6de);
  border-color: #bfe5c2;
}

.note-color-pink {
  background: linear-gradient(135deg, #fff9fc, #ffe0eb);
  border-color: #f7bfd3;
}

.note-color-purple {
  background: linear-gradient(135deg, #fbf9ff, #eadcff);
  border-color: #d5c1ff;
}

.attachment-gallery {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 0 0 14px;
}

.attachment-gallery.compact {
  grid-template-columns: 1fr;
}

.attachment-card {
  border: 1px solid #dbe3ec;
  border-radius: 16px;
  overflow: hidden;
  background: #ffffff;
}

.attachment-card img,
.attachment-card video {
  width: 100%;
  display: block;
  max-height: 190px;
  object-fit: cover;
  background: #0f172a;
}

.attachment-image-link {
  display: block;
}

.attachment-audio-box,
.attachment-document-box {
  display: grid;
  gap: 10px;
  padding: 14px;
}

.attachment-audio-box audio {
  width: 100%;
}

.attachment-kind-icon {
  width: 36px;
  height: 36px;
  display: inline-grid;
  place-items: center;
  border-radius: 12px;
  background: #eef5ff;
  font-size: 18px;
}

.attachment-document-box strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
}

.attachment-document-box span {
  color: #64748b;
  font-size: 11px;
}

.attachment-card-footer {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
  padding: 10px 12px;
  border-top: 1px solid #edf1f7;
}

.attachment-card-footer span {
  color: #334155;
  font-size: 12px;
  font-weight: 800;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.attachment-card-footer a {
  color: #0f4fc4;
  font-size: 12px;
  font-weight: 900;
  text-decoration: none;
  white-space: nowrap;
}

.board-empty-state {
  min-height: 190px;
}

@media (max-width: 1180px) {
  .workspace-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    max-width: 100%;
  }

  .visual-notes-grid,
  .attachment-gallery {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 800px) {
  .workspace-summary-grid {
    grid-template-columns: 1fr 1fr;
  }

  .workspace-card-side-badge {
    width: 100%;
  }

  .attachment-draft-chip,
  .note-form-toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .visual-announcement-item {
    padding-left: 16px;
    padding-top: 62px;
  }

  .announcement-ribbon {
    left: 16px;
    top: 16px;
  }
}

@media (max-width: 560px) {
  .workspace-summary-grid {
    grid-template-columns: 1fr;
  }

  .visual-notes-grid {
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   MENSAJES INTERNOS
========================================================= */

.internal-messages-page {
  display: grid;
  gap: 18px;
}

.messages-hero {
  align-items: stretch;
}

.messages-hero h1 {
  margin: 4px 0 8px;
  color: #0f2442;
  font-size: 32px;
  letter-spacing: -0.03em;
}

.messages-summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(120px, 1fr));
  gap: 12px;
  min-width: min(100%, 480px);
}

.messages-summary-card {
  position: relative;
  overflow: hidden;
  min-height: 112px;
  display: grid;
  gap: 4px;
  align-content: center;
  border-radius: 20px;
  border: 1px solid #e2e8f0;
  background: #ffffff;
  padding: 16px;
  box-shadow: 0 16px 34px rgba(15, 23, 42, 0.08);
}

.messages-summary-card::after {
  content: "";
  position: absolute;
  right: -24px;
  top: -24px;
  width: 78px;
  height: 78px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.45);
}

.messages-summary-card span {
  font-size: 22px;
}

.messages-summary-card strong {
  color: #0f2442;
  font-size: 30px;
  line-height: 1;
}

.messages-summary-card small {
  color: #526176;
  font-size: 12px;
  font-weight: 900;
}

.messages-summary-card.unread {
  background: linear-gradient(135deg, #fff1f1, #ffffff);
  border-color: #fecaca;
}

.messages-summary-card.inbox {
  background: linear-gradient(135deg, #eaf2ff, #ffffff);
  border-color: #bad0ff;
}

.messages-summary-card.sent {
  background: linear-gradient(135deg, #dcfce7, #ffffff);
  border-color: #bbf7d0;
}

.messages-layout {
  display: grid;
  grid-template-columns: 390px minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}

.messages-compose-panel,
.messages-inbox-panel {
  margin-top: 0;
}

.messages-compose-panel {
  position: sticky;
  top: 24px;
}

.messages-panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 14px;
}

.messages-panel-header span {
  display: block;
  color: #0f4fc4;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.messages-panel-header h3 {
  margin: 0;
  color: #0f2442;
  font-size: 18px;
}

.messages-panel-header button {
  border: 1px solid #dbe7ff !important;
  background: #ffffff !important;
  color: #0f4fc4 !important;
  border-radius: 999px !important;
  padding: 8px 12px !important;
  font-size: 12px !important;
  font-weight: 900 !important;
}

.messages-compose-form {
  display: grid;
  gap: 13px;
}

.messages-compose-form label {
  margin: 0;
  display: grid;
  gap: 7px;
}

.messages-compose-form label > span {
  color: #0f2442;
  font-size: 12px;
  font-weight: 900;
}

.messages-compose-form textarea {
  min-height: 120px;
}

.messages-tabs {
  display: flex;
  gap: 8px;
  padding: 6px;
  border: 1px solid #dce6f5;
  background: #eef4fb;
  border-radius: 999px;
  width: fit-content;
  margin-bottom: 16px;
}

.messages-tabs button {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: none !important;
  background: transparent !important;
  color: #526176 !important;
  border-radius: 999px !important;
  padding: 9px 15px !important;
  font-size: 12px !important;
  font-weight: 900 !important;
}

.messages-tabs button.active {
  background: #ffffff !important;
  color: #0f4fc4 !important;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
}

.messages-tabs button span {
  min-width: 22px;
  height: 22px;
  display: inline-grid;
  place-items: center;
  border-radius: 50%;
  background: #fee2e2;
  color: #b42318;
  font-size: 11px;
}

.messages-content-grid {
  display: grid;
  grid-template-columns: minmax(280px, 0.82fr) minmax(0, 1.18fr);
  gap: 16px;
  align-items: start;
}

.messages-list {
  display: grid;
  gap: 10px;
  max-height: 720px;
  overflow-y: auto;
  padding-right: 4px;
}

.message-list-item {
  width: 100%;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 10px;
  border: 1px solid #e2e8f0 !important;
  border-radius: 16px !important;
  background: #ffffff !important;
  color: inherit !important;
  text-align: left;
  padding: 12px !important;
  transition: 0.18s ease;
}

.message-list-item:hover,
.message-list-item.active {
  border-color: #bad0ff !important;
  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.08);
  transform: translateY(-1px);
}

.message-list-item.unread {
  background: linear-gradient(180deg, #fff9f9, #ffffff) !important;
  border-color: #fecaca !important;
}

.message-list-avatar {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(135deg, #0f4fc4, #ed1c24);
  color: #ffffff;
  font-size: 12px;
  font-weight: 900;
}

.message-list-topline {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

.message-list-topline strong {
  color: #0f2442;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.message-list-topline small {
  color: #94a3b8;
  font-size: 10px;
  white-space: nowrap;
}

.message-list-item span {
  display: block;
  color: #0f4fc4;
  font-size: 12px;
  font-weight: 900;
  margin-top: 4px;
}

.message-list-item p {
  margin: 5px 0 0;
  color: #526176;
  font-size: 12px;
  line-height: 1.35;
  display: -webkit-box;
  line-clamp: 2;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.message-list-item em {
  display: inline-flex;
  width: fit-content;
  margin-top: 8px;
  border-radius: 999px;
  background: #f1f5f9;
  color: #64748b;
  padding: 5px 8px;
  font-size: 10px;
  font-style: normal;
  font-weight: 900;
}

.message-detail-panel {
  min-width: 0;
}

.message-detail-card {
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: linear-gradient(180deg, #ffffff, #fbfdff);
  padding: 18px;
  min-height: 420px;
}

.message-detail-top {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 14px;
}

.message-detail-top h3 {
  margin: 8px 0 0;
  color: #0f2442;
  font-size: 20px;
  line-height: 1.25;
}

.message-detail-top small {
  color: #64748b;
  font-size: 12px;
  white-space: nowrap;
}

.read-status {
  display: inline-flex;
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 11px;
  font-weight: 900;
}

.read-status.read {
  background: #dcfce7;
  color: #166534;
  border: 1px solid #bbf7d0;
}

.read-status.unread {
  background: #fee2e2;
  color: #991b1b;
  border: 1px solid #fecaca;
}

.message-address-box {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}

.message-address-box > div {
  border: 1px solid #e5eaf2;
  border-radius: 14px;
  background: #ffffff;
  padding: 12px;
}

.message-address-box span {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
  margin-bottom: 4px;
}

.message-address-box strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.message-address-box small {
  display: block;
  color: #94a3b8;
  font-size: 11px;
  margin-top: 3px;
  overflow-wrap: anywhere;
}

.message-detail-body {
  margin: 0 0 16px;
  color: #344256;
  font-size: 14px;
  line-height: 1.65;
  white-space: pre-wrap;
}

.message-detail-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 16px;
}

.message-detail-actions button {
  border: 1px solid #b9cdfa !important;
  border-radius: 999px !important;
  background: #ffffff !important;
  color: #0f4fc4 !important;
  padding: 10px 14px !important;
  font-size: 12px !important;
  font-weight: 900 !important;
}

.messages-empty-state {
  min-height: 260px;
}

@media (max-width: 1350px) {
  .messages-layout {
    grid-template-columns: 1fr;
  }

  .messages-compose-panel {
    position: static;
  }
}

@media (max-width: 1050px) {
  .messages-content-grid {
    grid-template-columns: 1fr;
  }

  .messages-list {
    max-height: none;
  }
}

@media (max-width: 760px) {
  .messages-summary-grid,
  .message-address-box {
    grid-template-columns: 1fr;
  }

  .messages-tabs {
    width: 100%;
  }

  .messages-tabs button {
    flex: 1;
    justify-content: center;
  }

  .message-detail-top,
  .message-list-topline {
    flex-direction: column;
    align-items: flex-start;
  }

  .message-detail-top small,
  .message-list-topline small {
    white-space: normal;
  }
}

/* =========================================================
   MENSAJES INTERNOS - VISTA TIPO CHAT
========================================================= */

.chat-messages-page {
  display: grid;
  gap: 18px;
}

.chat-hero {
  align-items: stretch;
}

.chat-summary-grid {
  min-width: min(100%, 520px);
}

.chat-layout {
  display: grid;
  grid-template-columns: 370px minmax(0, 1fr);
  gap: 0;
  padding: 0;
  min-height: 720px;
  overflow: hidden;
}

.chat-sidebar-panel {
  min-width: 0;
  border-right: 1px solid #e5eaf2;
  background: linear-gradient(180deg, #ffffff, #f8fbff);
  display: grid;
  grid-template-rows: auto auto minmax(0, 1fr);
}

.chat-sidebar-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 18px;
  border-bottom: 1px solid #e5eaf2;
}

.chat-sidebar-header span,
.chat-new-conversation-box label > span,
.chat-thread-header span {
  display: block;
  color: #0f4fc4;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.chat-sidebar-header h3,
.chat-thread-header h3 {
  margin: 0;
  color: #0f2442;
  font-size: 18px;
}

.chat-sidebar-header button {
  border: 1px solid #dbe7ff !important;
  background: #ffffff !important;
  color: #0f4fc4 !important;
  border-radius: 999px !important;
  padding: 8px 12px !important;
  font-size: 12px !important;
  font-weight: 900 !important;
}

.chat-new-conversation-box {
  display: grid;
  gap: 12px;
  padding: 14px 18px;
  border-bottom: 1px solid #e5eaf2;
  background: #f8fbff;
}

.chat-new-conversation-box label {
  margin: 0;
}

.chat-new-conversation-box select {
  min-height: 44px;
}

.chat-conversation-list {
  display: grid;
  align-content: start;
  gap: 10px;
  padding: 14px;
  overflow-y: auto;
  max-height: 720px;
}

.chat-conversation-item {
  position: relative;
  width: 100%;
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) auto;
  gap: 11px;
  align-items: center;
  border: 1px solid #e2e8f0 !important;
  border-radius: 18px !important;
  background: #ffffff !important;
  color: inherit !important;
  text-align: left;
  padding: 12px !important;
  transition: 0.18s ease;
}

.chat-conversation-item:hover,
.chat-conversation-item.active {
  border-color: #bad0ff !important;
  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.08);
  transform: translateY(-1px);
}

.chat-conversation-item.unread {
  background: linear-gradient(180deg, #fff9f9, #ffffff) !important;
  border-color: #fecaca !important;
}

.chat-conversation-avatar,
.chat-thread-avatar,
.chat-message-avatar {
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: linear-gradient(135deg, #0f4fc4, #ed1c24);
  color: #ffffff;
  font-weight: 900;
  flex-shrink: 0;
}

.chat-conversation-avatar {
  width: 46px;
  height: 46px;
  font-size: 13px;
}

.chat-conversation-main {
  min-width: 0;
}

.chat-conversation-topline {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

.chat-conversation-topline strong {
  color: #0f2442;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.chat-conversation-topline small {
  color: #94a3b8;
  font-size: 10px;
  white-space: nowrap;
}

.chat-conversation-item p {
  margin: 5px 0 0;
  color: #526176;
  font-size: 12px;
  line-height: 1.35;
  display: -webkit-box;
  line-clamp: 2;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.chat-conversation-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.chat-conversation-meta span {
  display: inline-flex;
  width: fit-content;
  border-radius: 999px;
  background: #f1f5f9;
  color: #64748b;
  padding: 4px 7px;
  font-size: 10px;
  font-weight: 900;
}

.chat-unread-pill {
  min-width: 24px;
  height: 24px;
  display: inline-grid;
  place-items: center;
  border-radius: 50%;
  background: #ed1c24;
  color: #ffffff;
  font-size: 11px;
  font-weight: 900;
}

.chat-thread-panel {
  min-width: 0;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  background: #f8fbff;
}

.chat-thread-header {
  display: grid;
  grid-template-columns: 54px minmax(0, 1fr);
  gap: 13px;
  align-items: center;
  padding: 18px 20px;
  background: #ffffff;
  border-bottom: 1px solid #e5eaf2;
}

.chat-thread-avatar {
  width: 54px;
  height: 54px;
  font-size: 15px;
}

.chat-thread-header small {
  display: block;
  color: #64748b;
  font-size: 12px;
  margin-top: 3px;
  overflow-wrap: anywhere;
}

.chat-thread-messages {
  display: grid;
  align-content: start;
  gap: 12px;
  padding: 22px;
  overflow-y: auto;
  max-height: 620px;
  background:
    radial-gradient(circle at 20% 10%, rgba(15, 79, 196, 0.05), transparent 30%),
    radial-gradient(circle at 90% 90%, rgba(237, 28, 36, 0.05), transparent 30%),
    #f8fbff;
}

.chat-date-separator {
  justify-self: center;
  width: fit-content;
  max-width: 100%;
  border: 1px solid #dbe3ec;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.88);
  color: #64748b;
  padding: 7px 12px;
  font-size: 12px;
  font-weight: 900;
}

.chat-bubble-row {
  display: grid;
  gap: 8px;
  align-items: end;
  max-width: 78%;
}

.chat-bubble-row.incoming {
  grid-template-columns: 34px minmax(0, 1fr);
  justify-self: start;
}

.chat-bubble-row.outgoing {
  grid-template-columns: minmax(0, 1fr);
  justify-self: end;
}

.chat-message-avatar {
  width: 34px;
  height: 34px;
  font-size: 10px;
}

.chat-bubble {
  min-width: 0;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  background: #ffffff;
  padding: 12px 14px;
  box-shadow: 0 10px 24px rgba(15, 23, 42, 0.06);
}

.chat-bubble-row.outgoing .chat-bubble {
  background: linear-gradient(135deg, #0f4fc4, #0a3f9d);
  color: #ffffff;
  border-color: #0f4fc4;
}

.chat-bubble-topline {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-bottom: 6px;
}

.chat-bubble-topline strong {
  color: #0f2442;
  font-size: 12px;
}

.chat-bubble-row.outgoing .chat-bubble-topline strong {
  color: #ffffff;
}

.chat-bubble-topline small {
  color: #94a3b8;
  font-size: 10px;
  white-space: nowrap;
}

.chat-bubble-row.outgoing .chat-bubble-topline small {
  color: rgba(255, 255, 255, 0.78);
}

.chat-bubble p {
  margin: 0;
  color: #344256;
  font-size: 13px;
  line-height: 1.55;
  white-space: pre-wrap;
}

.chat-bubble-row.outgoing .chat-bubble p {
  color: #ffffff;
}

.chat-bubble-status {
  margin-top: 8px;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 900;
  text-align: right;
}

.chat-bubble-row.outgoing .chat-bubble-status {
  color: rgba(255, 255, 255, 0.78);
}

.chat-bubble-status {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

.chat-reply-reference {
  margin-bottom: 8px;
  padding: 8px 10px;
  border-left: 3px solid #0f4fc4;
  border-radius: 10px;
  background: #eef5ff;
  box-shadow: inset 0 0 0 1px rgba(15, 79, 196, 0.08);
}

.chat-bubble-row.outgoing .chat-reply-reference {
  border-left-color: #facc15;
  background: #ffffff;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.16);
}

.chat-reply-reference span,
.chat-reply-preview span {
  display: block;
  color: #0f4fc4;
  font-size: 11px;
  font-weight: 900;
}

.chat-bubble-row.outgoing .chat-reply-reference span,
.chat-bubble-row.outgoing .chat-reply-reference p {
  color: #0f2442;
}

.chat-reply-reference p,
.chat-reply-preview p {
  margin: 2px 0 0;
  max-height: none;
  overflow: hidden;
  color: #475569;
  font-size: 12px;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.chat-reply-button {
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font-size: 10px;
  font-weight: 900;
  opacity: 0.85;
  padding: 0;
}

.chat-reply-button:hover {
  opacity: 1;
  text-decoration: underline;
}

.chat-reply-preview {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  border: 1px solid #d9e2ef;
  border-left: 4px solid #0f4fc4;
  border-radius: 12px;
  background: #f8fbff;
  width: 100%;
  min-height: 58px;
  padding: 12px 14px;
}

.chat-reply-preview > div {
  min-width: 0;
}

.chat-reply-preview button {
  align-self: start;
  border: 0;
  border-radius: 999px;
  background: #e2e8f0;
  color: #334155;
  cursor: pointer;
  font-size: 16px;
  font-weight: 900;
  line-height: 1;
  min-height: 26px;
  min-width: 26px;
  flex: 0 0 auto;
}

.chat-typing-indicator {
  border-top: 1px solid #e5eaf2;
  background: #ffffff;
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
  padding: 8px 18px 0;
}

.chat-bubble .attachment-gallery {
  margin-top: 10px;
  margin-bottom: 6px;
}

.chat-bubble-row.outgoing .attachment-card-footer,
.chat-bubble-row.outgoing .attachment-document-box,
.chat-bubble-row.outgoing .attachment-audio-box {
  color: #0f2442;
}

.chat-composer {
  display: grid;
  gap: 12px;
  padding: 16px 18px 18px;
  background: #ffffff;
  border-top: 1px solid #e5eaf2;
}

.chat-composer textarea {
  width: 100%;
  min-height: 78px;
  border: 1px solid #d9e2ef;
  border-radius: 16px;
  background: #f8fbff;
  color: #0f2442;
  padding: 13px 14px;
  font-size: 14px;
}

.chat-composer textarea:focus {
  outline: none;
  border-color: #0f4fc4;
  box-shadow: 0 0 0 3px rgba(15, 79, 196, 0.12);
}

.chat-composer-tools {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 12px;
  align-items: end;
}

.chat-composer .attachment-picker {
  margin: 0;
}

.chat-composer .attachment-picker-dropzone {
  min-height: auto;
  padding: 12px;
}

.chat-composer .attachment-picker-dropzone > div {
  display: flex;
  gap: 10px;
  align-items: center;
}

.chat-composer .dropzone-icon {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  font-size: 16px;
}

.chat-composer .attachment-picker-dropzone p {
  display: none;
}

.chat-empty-thread {
  align-self: center;
  justify-self: center;
}

.messages-empty-state.compact {
  min-height: 180px;
}

@media (max-width: 1250px) {
  .chat-layout {
    grid-template-columns: 320px minmax(0, 1fr);
  }
}

@media (max-width: 1000px) {
  .chat-layout {
    grid-template-columns: 1fr;
    min-height: auto;
  }

  .chat-sidebar-panel {
    border-right: none;
    border-bottom: 1px solid #e5eaf2;
  }

  .chat-conversation-list,
  .chat-thread-messages {
    max-height: none;
  }

  .chat-bubble-row {
    max-width: 92%;
  }
}

@media (max-width: 720px) {
  .chat-layout {
    margin-left: -4px;
    margin-right: -4px;
  }

  .chat-summary-grid {
    grid-template-columns: 1fr;
  }

  .chat-conversation-topline,
  .chat-bubble-topline {
    flex-direction: column;
    align-items: flex-start;
  }

  .chat-conversation-topline small,
  .chat-bubble-topline small {
    white-space: normal;
  }

  .chat-thread-header {
    grid-template-columns: 44px minmax(0, 1fr);
    padding: 14px;
  }

  .chat-thread-avatar {
    width: 44px;
    height: 44px;
    font-size: 13px;
  }

  .chat-thread-messages {
    padding: 14px;
  }

  .chat-bubble-row {
    max-width: 100%;
  }

  .chat-composer-tools {
    grid-template-columns: 1fr;
  }

  .chat-composer .workspace-primary-button {
    width: 100%;
  }
}

/* =========================================================
   CHAT - PRESENCIA EN LÍNEA / ÚLTIMA CONEXIÓN
========================================================= */

.presence-avatar {
  position: relative;
}

.presence-avatar::after {
  content: "";
  position: absolute;
  right: -1px;
  bottom: -1px;
  width: 12px;
  height: 12px;
  border: 3px solid #ffffff;
  border-radius: 50%;
  background: #94a3b8;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.18);
}

.presence-avatar.online::after {
  background: #16a34a;
}

.presence-avatar.offline::after {
  background: #94a3b8;
}

.presence-badge {
  width: fit-content;
  max-width: 100%;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 7px;
  border: 1px solid #e2e8f0;
  border-radius: 999px;
  background: #f8fafc;
  color: #64748b;
  padding: 5px 10px;
  font-size: 11px;
  font-weight: 900;
  line-height: 1.2;
}

.presence-badge.compact {
  margin: 4px 0 2px;
  padding: 4px 8px;
  font-size: 10px;
}

.presence-badge.online {
  background: #ecfdf3;
  border-color: #bbf7d0;
  color: #166534;
}

.presence-badge.offline {
  background: #f8fafc;
  border-color: #e2e8f0;
  color: #64748b;
}

.presence-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 8px;
  border-radius: 50%;
  background: currentColor;
}

.chat-conversation-item .presence-badge {
  justify-self: start;
}

.chat-thread-header .presence-badge {
  margin-top: 8px;
}

@media (max-width: 760px) {
  .presence-badge {
    white-space: normal;
  }
}

/* =========================================================
   CHAT - NOTIFICACIONES VISUALES DE MENSAJES NO LEÍDOS
========================================================= */

.sidebar-nav button {
  position: relative;
}

.sidebar-nav-label {
  flex: 1;
  min-width: 0;
}

.nav-unread-badge {
  min-width: 26px;
  height: 24px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  padding: 0 8px;
  margin-left: auto;
  background: #ed1c24;
  color: #ffffff;
  border: 2px solid rgba(255, 255, 255, 0.7);
  font-size: 11px;
  font-weight: 900;
  line-height: 1;
  box-shadow: 0 10px 20px rgba(237, 28, 36, 0.24);
}

.sidebar-nav button.active .nav-unread-badge {
  border-color: #ffffff;
  background: #ed1c24;
  color: #ffffff;
}

.messages-title-row {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.messages-title-row h1 {
  margin: 0;
}

.messages-title-unread-badge {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  background: #fee2e2;
  color: #b42318;
  border: 1px solid #fecaca;
  padding: 7px 11px;
  font-size: 12px;
  font-weight: 900;
}

.chat-conversation-item.unread {
  background: linear-gradient(135deg, #fff8f8, #ffffff) !important;
  border-color: #fda4af !important;
  box-shadow: 0 14px 30px rgba(237, 28, 36, 0.08);
}

.chat-conversation-item.unread::before {
  content: "";
  position: absolute;
  left: 0;
  top: 14px;
  bottom: 14px;
  width: 4px;
  border-radius: 999px;
  background: #ed1c24;
}

.chat-conversation-item.unread .chat-conversation-topline strong {
  color: #b42318;
  font-weight: 900;
}

.chat-new-message-tag {
  background: #fee2e2 !important;
  color: #b42318 !important;
  border: 1px solid #fecaca !important;
}

.chat-unread-pill {
  box-shadow: 0 10px 20px rgba(237, 28, 36, 0.24);
}

.mobile-nav-icon-wrap {
  position: relative;
  display: inline-grid;
  place-items: center;
}

.mobile-bottom-nav button.has-unread {
  color: #0f4fc4;
}

.mobile-nav-unread-badge {
  position: absolute;
  top: -9px;
  right: -13px;
  min-width: 20px;
  height: 20px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  padding: 0 6px;
  background: #ed1c24;
  color: #ffffff;
  border: 2px solid #ffffff;
  font-size: 10px;
  font-weight: 900;
  line-height: 1;
  box-shadow: 0 8px 16px rgba(237, 28, 36, 0.24);
}

.mobile-drawer-list button {
  position: relative;
}

.mobile-drawer-badge {
  position: absolute;
  top: 9px;
  right: 9px;
  min-width: 24px;
  height: 22px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  padding: 0 7px;
  background: #ed1c24;
  color: #ffffff;
  border: 2px solid #ffffff;
  font-size: 10px;
  font-weight: 900;
  box-shadow: 0 8px 16px rgba(237, 28, 36, 0.22);
}

@media (max-width: 800px) {
  .messages-title-row {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }
}

/* =========================================================
   TABLERO - NOTIFICACIONES DE ANUNCIOS PENDIENTES
========================================================= */

.nav-announcement-badge {
  background: linear-gradient(135deg, #f97316, #ed1c24);
}

.announcement-pending-strip {
  width: fit-content;
  max-width: 100%;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-top: 14px;
  border: 1px solid #fed7aa;
  border-radius: 999px;
  background: linear-gradient(135deg, #fff7ed, #fff1f1);
  color: #9a3412;
  padding: 9px 13px;
  font-size: 12px;
  font-weight: 900;
  box-shadow: 0 12px 24px rgba(249, 115, 22, 0.10);
}

.announcement-pending-strip span {
  width: 25px;
  height: 25px;
  display: inline-grid;
  place-items: center;
  border-radius: 50%;
  background: #ffedd5;
}

.visual-announcement-item.pending-read {
  border-color: #fed7aa !important;
  background:
    radial-gradient(circle at 94% 12%, rgba(249, 115, 22, 0.11), transparent 28%),
    linear-gradient(180deg, #ffffff, #fffaf4) !important;
  box-shadow: 0 18px 38px rgba(249, 115, 22, 0.11);
}

.visual-announcement-item.pending-read::before {
  content: "";
  position: absolute;
  left: 0;
  top: 16px;
  bottom: 16px;
  width: 5px;
  border-radius: 999px;
  background: linear-gradient(180deg, #f97316, #ed1c24);
}

.visual-announcement-item.pending-read .announcement-ribbon {
  background: #ffedd5;
}

.announcement-unread-tag {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  border-radius: 999px;
  background: #fff7ed;
  color: #c2410c;
  border: 1px solid #fed7aa;
  padding: 6px 9px;
  margin-left: 7px;
  font-size: 11px;
  font-weight: 900;
  vertical-align: middle;
}

@media (max-width: 760px) {
  .announcement-pending-strip {
    width: 100%;
    border-radius: 16px;
    align-items: flex-start;
  }

  .announcement-unread-tag {
    margin-left: 0;
    margin-top: 6px;
  }
}

/* =========================================================
   BUSCADORES EN TABLERO, NOTAS Y MENSAJES
========================================================= */

.board-search-toolbar,
.chat-search-box,
.chat-thread-search-box {
  display: grid;
  gap: 12px;
  margin: 16px 0;
  padding: 14px;
  border: 1px solid #dbe7ff;
  border-radius: 18px;
  background: linear-gradient(180deg, #ffffff, #f8fbff);
}

.notes-search-toolbar {
  border-color: #f3d28a;
  background: linear-gradient(180deg, #ffffff, #fffdf6);
}

.board-search-input,
.chat-search-box label,
.chat-thread-search-box label {
  margin: 0;
  display: grid;
  gap: 8px;
}

.board-search-input span,
.chat-search-box label span,
.chat-thread-search-box label span {
  color: #0f2442;
  font-size: 12px;
  font-weight: 900;
}

.board-search-input input,
.chat-search-box input,
.chat-thread-search-box input {
  width: 100%;
  min-height: 44px;
  border: 1px solid #d9e2ef;
  border-radius: 12px;
  background: #ffffff;
  color: #0f2442;
  padding: 0 13px;
  font-size: 13px;
}

.board-search-input input:focus,
.chat-search-box input:focus,
.chat-thread-search-box input:focus {
  outline: none;
  border-color: #0f4fc4;
  box-shadow: 0 0 0 3px rgba(15, 79, 196, 0.11);
}

.board-filter-pills {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.board-filter-pills button {
  border: 1px solid #d9e2ef;
  background: #ffffff;
  color: #344256;
  border-radius: 999px;
  padding: 8px 12px;
  font-size: 12px;
  font-weight: 900;
}

.board-filter-pills button:hover {
  border-color: #b9cdfa;
  background: #f8fbff;
}

.board-filter-pills button.active {
  background: #0f4fc4;
  color: #ffffff;
  border-color: #0f4fc4;
  box-shadow: 0 8px 18px rgba(15, 79, 196, 0.18);
}

.notes-search-toolbar .board-filter-pills button.active {
  background: #d99a00;
  border-color: #d99a00;
  box-shadow: 0 8px 18px rgba(217, 154, 0, 0.18);
}

.board-search-toolbar > small,
.chat-search-box > small,
.chat-thread-search-box > small {
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
}

.chat-search-box {
  margin: 0 0 14px;
  padding: 12px;
  border-color: #e2e8f0;
}

.chat-thread-search-box {
  margin: 0 0 14px;
  padding: 12px 14px;
  border-color: #e2e8f0;
  background: #f8fbff;
}

.chat-thread-search-box input,
.chat-search-box input {
  min-height: 42px;
}

@media (max-width: 800px) {
  .board-search-toolbar,
  .chat-search-box,
  .chat-thread-search-box {
    padding: 12px;
  }

  .board-filter-pills {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .board-filter-pills button {
    width: 100%;
  }
}

@media (max-width: 520px) {
  .board-filter-pills {
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   PANEL ADMINISTRATIVO DE ANUNCIOS
========================================================= */

.announcement-admin-dashboard {
  margin: 18px 0 20px;
  border: 1px solid #dbe7ff;
  border-radius: 22px;
  background:
    radial-gradient(circle at top right, rgba(15, 79, 196, 0.08), transparent 26%),
    linear-gradient(180deg, #ffffff, #f8fbff);
  padding: 18px;
  box-shadow: 0 16px 34px rgba(15, 23, 42, 0.07);
}

.announcement-admin-dashboard-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 16px;
}

.announcement-admin-dashboard-header span {
  display: block;
  color: #0f4fc4;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 5px;
}

.announcement-admin-dashboard-header h4 {
  margin: 0 0 5px;
  color: #0f2442;
  font-size: 19px;
}

.announcement-admin-dashboard-header p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.45;
}

.announcement-admin-total-badge {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 999px;
  background: #eaf2ff;
  color: #0f4fc4;
  padding: 8px 12px;
  font-size: 12px;
  font-weight: 900;
}

.announcement-admin-metrics {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin-bottom: 16px;
}

.announcement-admin-metrics > div {
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #ffffff;
  padding: 13px;
  min-width: 0;
}

.announcement-admin-metrics span {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 900;
  margin-bottom: 6px;
}

.announcement-admin-metrics strong {
  color: #0f2442;
  font-size: 25px;
  line-height: 1;
}

.announcement-admin-metrics .pending {
  border-color: #fed7aa;
  background: #fff7ed;
}

.announcement-admin-metrics .pending strong {
  color: #f97316;
}

.announcement-admin-toolbar {
  display: grid;
  grid-template-columns: minmax(260px, 0.8fr) minmax(0, 1.2fr);
  gap: 12px;
  align-items: center;
  margin-bottom: 16px;
}

.announcement-admin-search {
  width: 100%;
}

.announcement-admin-filters {
  margin-bottom: 0;
  justify-content: flex-end;
}

.announcement-admin-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  gap: 16px;
  align-items: start;
}

.announcement-admin-table-wrap {
  width: 100%;
  overflow-x: auto;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #ffffff;
}

.announcement-admin-table {
  width: 100%;
  min-width: 900px;
  border-collapse: collapse;
}

.announcement-admin-table th {
  text-align: left;
  color: #64748b;
  background: #f8fafc;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 11px 12px;
  border-bottom: 1px solid #e2e8f0;
  white-space: nowrap;
}

.announcement-admin-table td {
  padding: 12px;
  border-bottom: 1px solid #edf1f7;
  color: #334155;
  font-size: 12px;
  vertical-align: middle;
}

.announcement-admin-table tr.selected td {
  background: #eef5ff;
}

.announcement-admin-title-button {
  border: none !important;
  background: transparent !important;
  color: inherit !important;
  padding: 0 !important;
  text-align: left;
  box-shadow: none !important;
}

.announcement-admin-title-button strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
  margin-bottom: 4px;
}

.announcement-admin-title-button span {
  color: #64748b;
  font-size: 11px;
}

.admin-status-pill {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 6px 9px;
  font-size: 11px;
  font-weight: 900;
}

.admin-status-pill.active {
  background: #dcfce7;
  color: #166534;
  border: 1px solid #bbf7d0;
}

.admin-status-pill.archived {
  background: #f1f5f9;
  color: #64748b;
  border: 1px solid #e2e8f0;
}

.admin-read-progress {
  display: flex;
  align-items: center;
  gap: 7px;
}

.admin-read-progress strong {
  color: #0f2442;
  font-size: 12px;
}

.admin-read-progress span {
  color: #0f4fc4;
  background: #eaf2ff;
  border-radius: 999px;
  padding: 4px 7px;
  font-size: 11px;
  font-weight: 900;
}

.admin-pending-number,
.admin-complete-number {
  display: inline-grid;
  min-width: 26px;
  height: 26px;
  place-items: center;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 900;
}

.admin-pending-number {
  background: #ffedd5;
  color: #c2410c;
}

.admin-complete-number {
  background: #dcfce7;
  color: #166534;
}

.announcement-admin-row-actions {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.announcement-admin-row-actions button {
  border: 1px solid #dbe7ff !important;
  background: #ffffff !important;
  color: #0f4fc4 !important;
  border-radius: 8px !important;
  padding: 7px 9px !important;
  font-size: 11px !important;
  font-weight: 900 !important;
}

.announcement-admin-row-actions button.danger {
  border-color: #fecaca !important;
  color: #b42318 !important;
  background: #fff5f5 !important;
}

.announcement-admin-detail {
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  background: #ffffff;
  padding: 15px;
  position: sticky;
  top: 18px;
}

.announcement-admin-detail-top h5 {
  margin: 10px 0 7px;
  color: #0f2442;
  font-size: 16px;
}

.announcement-admin-detail-top p {
  margin: 0;
  color: #526176;
  font-size: 12px;
  line-height: 1.5;
}

.announcement-admin-detail-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 14px 0;
}

.announcement-admin-detail-stats div {
  border: 1px solid #edf1f7;
  border-radius: 12px;
  background: #f8fbff;
  padding: 10px;
}

.announcement-admin-detail-stats span {
  display: block;
  color: #64748b;
  font-size: 10px;
  font-weight: 900;
  margin-bottom: 5px;
}

.announcement-admin-detail-stats strong {
  color: #0f4fc4;
  font-size: 19px;
}

.announcement-admin-people-grid {
  display: grid;
  gap: 12px;
}

.announcement-admin-people-grid > div {
  border-top: 1px solid #edf1f7;
  padding-top: 12px;
}

.announcement-admin-people-grid strong {
  display: block;
  color: #0f2442;
  font-size: 12px;
  margin-bottom: 8px;
}

.announcement-admin-people-grid p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.45;
}

.reader-person-chip,
.missing-person-chip {
  display: block;
  width: fit-content;
  max-width: 100%;
  border-radius: 999px;
  padding: 6px 9px;
  margin: 6px 0;
  font-size: 11px;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.reader-person-chip {
  background: #dcfce7;
  color: #166534;
}

.missing-person-chip {
  background: #fff7ed;
  color: #c2410c;
}

.announcement-admin-empty {
  padding: 18px;
  color: #64748b;
  text-align: center;
  font-size: 13px;
}

@media (max-width: 1250px) {
  .announcement-admin-layout,
  .announcement-admin-toolbar {
    grid-template-columns: 1fr;
  }

  .announcement-admin-filters {
    justify-content: flex-start;
  }

  .announcement-admin-detail {
    position: static;
  }
}

@media (max-width: 900px) {
  .announcement-admin-dashboard-header {
    flex-direction: column;
  }

  .announcement-admin-total-badge {
    width: 100%;
  }

  .announcement-admin-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 620px) {
  .announcement-admin-metrics,
  .announcement-admin-detail-stats {
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   CHAT POR DEPARTAMENTO
========================================================= */

.department-chat-summary-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.messages-summary-card.group {
  background: linear-gradient(135deg, #ecfeff, #f0fdfa);
  border-color: #99f6e4;
}

.messages-summary-card.group span {
  background: #ccfbf1;
  color: #0f9488;
}

.chat-mode-tabs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  padding: 6px;
  margin: 0 0 14px;
  border: 1px solid #dce6f5;
  border-radius: 999px;
  background: #eef4fb;
}

.chat-mode-tabs button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: none;
  border-radius: 999px;
  background: transparent;
  color: #526176;
  padding: 9px 12px;
  font-size: 12px;
  font-weight: 900;
}

.chat-mode-tabs button.active {
  background: #ffffff;
  color: #0f4fc4;
  box-shadow: 0 8px 18px rgba(15, 23, 42, 0.08);
}

.chat-mode-tabs button span {
  min-width: 20px;
  height: 20px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  padding: 0 7px;
  background: #fee2e2;
  color: #b42318;
  font-size: 11px;
  font-weight: 900;
}

.department-chat-item {
  border-left: 5px solid #0f9488;
}

.department-chat-avatar {
  background: linear-gradient(135deg, #0f9488, #0f4fc4) !important;
  color: #ffffff;
}

.department-chat-label {
  width: fit-content;
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  background: #ccfbf1;
  color: #0f766e;
  padding: 5px 9px;
  font-size: 11px;
  font-weight: 900;
  margin: 2px 0 6px;
}

.department-thread-header {
  border-left: 5px solid #0f9488;
}

.department-thread-header .department-chat-label {
  margin-top: 7px;
}

.department-chat-bubble {
  border-color: #bfeee8;
}

.department-chat-bubble .chat-bubble-status {
  color: #0f766e;
}

@media (max-width: 1100px) {
  .department-chat-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 700px) {
  .department-chat-summary-grid,
  .chat-mode-tabs {
    grid-template-columns: 1fr;
  }
}

/* =========================================================
   CENTRO DE AVISOS - DASHBOARD PRINCIPAL
========================================================= */

.workspace-notice-center {
  display: grid;
  gap: 16px;
  margin: 0 0 22px;
}

.notice-center-hero {
  position: relative;
  overflow: hidden;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 126px;
  gap: 20px;
  align-items: center;
  padding: 22px;
  border: 1px solid #dbe7ff;
  border-radius: 24px;
  background:
    radial-gradient(circle at 95% 12%, rgba(237, 28, 36, 0.12), transparent 26%),
    radial-gradient(circle at 8% 20%, rgba(15, 79, 196, 0.12), transparent 30%),
    linear-gradient(135deg, #ffffff, #f8fbff);
  box-shadow: 0 18px 42px rgba(15, 23, 42, 0.08);
}

.notice-center-hero::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 5px;
  background: linear-gradient(90deg, #0f4fc4, #38bdf8, #ed1c24);
}

.notice-center-kicker,
.notice-center-activity-header span {
  display: block;
  color: #0f4fc4;
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.notice-center-hero h2 {
  margin: 0 0 7px;
  color: #0f2442;
  font-size: clamp(22px, 2.4vw, 31px);
  letter-spacing: -0.03em;
}

.notice-center-hero p {
  max-width: 780px;
  margin: 0;
  color: #526176;
  font-size: 14px;
  line-height: 1.5;
}

.notice-center-total {
  min-height: 104px;
  border-radius: 22px;
  display: grid;
  place-items: center;
  align-content: center;
  text-align: center;
  border: 1px solid #dbe7ff;
  background: #ffffff;
  box-shadow: 0 16px 30px rgba(15, 79, 196, 0.09);
}

.notice-center-total strong {
  display: block;
  color: #0f4fc4;
  font-size: 36px;
  line-height: 1;
}

.notice-center-total span {
  display: block;
  margin-top: 6px;
  color: #64748b;
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.notice-center-total.has-pending {
  border-color: #bad0ff;
  background: linear-gradient(180deg, #ffffff, #eef5ff);
}

.notice-center-total.clear strong {
  color: #16a34a;
}

.notice-center-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.notice-center-card {
  position: relative;
  overflow: hidden;
  display: grid;
  grid-template-columns: 54px minmax(0, 1fr);
  gap: 13px;
  align-items: start;
  min-height: 154px;
  border: 1px solid #e2e8f0;
  border-radius: 20px;
  background: #ffffff;
  padding: 17px;
  text-align: left;
  color: inherit;
  box-shadow: 0 14px 32px rgba(15, 23, 42, 0.07);
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.notice-center-card::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 5px;
}

.notice-center-card:hover {
  transform: translateY(-2px);
  border-color: #b9cdfa;
  box-shadow: 0 18px 38px rgba(15, 23, 42, 0.1);
}

.notice-card-icon {
  width: 52px;
  height: 52px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  font-size: 25px;
  background: #f1f5f9;
}

.notice-center-card strong {
  display: block;
  color: #0f2442;
  font-size: 30px;
  line-height: 1;
  margin-bottom: 6px;
}

.notice-center-card h3 {
  margin: 0 0 6px;
  color: #0f2442;
  font-size: 15px;
}

.notice-center-card p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.4;
}

.notice-center-card b {
  grid-column: 1 / -1;
  align-self: end;
  width: fit-content;
  border-radius: 999px;
  padding: 7px 10px;
  font-size: 11px;
  color: #0f4fc4;
  background: #eef5ff;
}

.notice-center-card.message-card .notice-card-icon,
.notice-activity-item.message > span {
  background: #eaf2ff;
  color: #0f4fc4;
}

.notice-center-card.message-card::after {
  background: #0f4fc4;
}

.notice-center-card.department-card .notice-card-icon,
.notice-activity-item.department > span {
  background: #ccfbf1;
  color: #0f9488;
}

.notice-center-card.department-card::after {
  background: #0f9488;
}

.notice-center-card.announcement-card .notice-card-icon,
.notice-activity-item.announcement > span {
  background: #fff4d8;
  color: #d99a00;
}

.notice-center-card.announcement-card::after {
  background: #d99a00;
}

.notice-center-card.notes-card-mini .notice-card-icon,
.notice-activity-item.note > span {
  background: #ede9fe;
  color: #7c3aed;
}

.notice-center-card.notes-card-mini::after {
  background: #7c3aed;
}

.notice-center-activity-card {
  border: 1px solid #e2e8f0;
  border-radius: 22px;
  background: #ffffff;
  box-shadow: 0 16px 38px rgba(15, 23, 42, 0.07);
  padding: 18px;
}

.notice-center-activity-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid #e5eaf2;
  margin-bottom: 14px;
}

.notice-center-activity-header h3 {
  margin: 0;
  color: #0f2442;
  font-size: 18px;
}

.notice-center-activity-header button {
  border: 1px solid #dbe7ff;
  background: #ffffff;
  color: #0f4fc4;
  border-radius: 999px;
  padding: 9px 13px;
  font-size: 12px;
  font-weight: 900;
}

.notice-center-activity-header button:hover {
  background: #eef5ff;
}

.notice-activity-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.notice-activity-item {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  border: 1px solid #e5eaf2;
  border-radius: 16px;
  background: #fbfdff;
  padding: 12px;
  color: inherit;
  text-align: left;
  transition: 0.18s ease;
}

.notice-activity-item:hover {
  border-color: #b9cdfa;
  background: #ffffff;
  box-shadow: 0 12px 24px rgba(15, 23, 42, 0.07);
}

.notice-activity-item > span {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  font-size: 19px;
  font-weight: 900;
}

.notice-activity-item strong {
  display: block;
  color: #0f2442;
  font-size: 13px;
  line-height: 1.3;
  margin-bottom: 3px;
}

.notice-activity-item p {
  margin: 0;
  color: #64748b;
  font-size: 12px;
  line-height: 1.35;
  overflow: hidden;
  display: -webkit-box;
  line-clamp: 2;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.notice-activity-item small {
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

.notice-center-empty {
  min-height: 94px;
  display: grid;
  place-items: center;
  text-align: center;
  border: 1px dashed #cbd7e6;
  border-radius: 16px;
  background: #f8fbff;
  padding: 18px;
}

.notice-center-empty strong {
  display: block;
  color: #0f2442;
  margin-bottom: 4px;
}

.notice-center-empty p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
}

@media (max-width: 1450px) {
  .notice-center-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1050px) {
  .notice-center-hero {
    grid-template-columns: 1fr;
  }

  .notice-center-total {
    min-height: 84px;
  }

  .notice-activity-list {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 680px) {
  .notice-center-grid {
    grid-template-columns: 1fr;
  }

  .notice-center-card,
  .notice-activity-item {
    grid-template-columns: 1fr;
  }

  .notice-center-activity-header {
    flex-direction: column;
  }

  .notice-center-activity-header button {
    width: 100%;
  }

  .notice-activity-item small {
    white-space: normal;
  }
}

/* =========================================================
   REPORTE DE ERRORES / INCIDENCIAS DEL SISTEMA
========================================================= */

.bug-reports-page {
  display: grid;
  gap: 18px;
}

.bug-reports-header {
  margin-bottom: 0;
}

.bug-kicker {
  display: inline-block;
  color: #0f4fc4;
  background: #eaf2ff;
  border-radius: 999px;
  padding: 6px 11px;
  font-size: 12px;
  font-weight: 900;
  margin-bottom: 10px;
}

.bug-header-summary {
  min-width: 160px;
  border: 1px solid #dbe7ff;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.06);
  padding: 16px;
  text-align: center;
}

.bug-header-summary strong {
  display: block;
  color: #0f4fc4;
  font-size: 34px;
  line-height: 1;
}

.bug-header-summary span {
  display: block;
  color: #64748b;
  font-size: 12px;
  font-weight: 800;
  margin-top: 6px;
}

.bug-message {
  border-radius: 14px;
  padding: 13px 15px;
  font-size: 13px;
  font-weight: 800;
}

.bug-message-success {
  border: 1px solid #bbf7d0;
  background: #f0fdf4;
  color: #166534;
}

.bug-message-error {
  border: 1px solid #fecaca;
  background: #fff1f1;
  color: #991b1b;
}

.bug-metrics-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

.bug-metric-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  min-height: 108px;
  background: #ffffff;
  border: 1px solid #e9eef6;
  border-radius: 16px;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.07);
  padding: 18px;
  overflow: hidden;
}

.bug-metric-card::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 5px;
}

.bug-metric-card > span {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 24px;
  font-weight: 900;
  flex-shrink: 0;
}

.bug-metric-card strong {
  display: block;
  color: #0f2442;
  font-size: 31px;
  line-height: 1;
  margin-bottom: 7px;
}

.bug-metric-card p {
  margin: 0;
  color: #526176;
  font-size: 13px;
  font-weight: 800;
}

.bug-metric-blue > span {
  color: #0f4fc4;
  background: #eaf2ff;
}

.bug-metric-blue::after {
  background: #0f4fc4;
}

.bug-metric-orange > span {
  color: #f97316;
  background: #ffedd5;
}

.bug-metric-orange::after {
  background: #f97316;
}

.bug-metric-red > span {
  color: #ed1c24;
  background: #fee2e2;
}

.bug-metric-red::after {
  background: #ed1c24;
}

.bug-metric-green > span {
  color: #16a34a;
  background: #dcfce7;
}

.bug-metric-green::after {
  background: #16a34a;
}

.bug-reports-layout {
  display: grid;
  grid-template-columns: minmax(360px, 0.85fr) minmax(0, 1.35fr);
  gap: 20px;
  align-items: start;
}

.bug-form-card,
.bug-list-card {
  margin-top: 0;
}

.bug-section-title {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  margin-bottom: 16px;
}

.bug-section-title > span {
  width: 34px;
  height: 34px;
  border-radius: 11px;
  display: grid;
  place-items: center;
  background: #eaf2ff;
  color: #0f4fc4;
  font-weight: 900;
  flex-shrink: 0;
}

.bug-section-title h3 {
  margin: 0 0 5px;
  color: #0f2442;
  font-size: 19px;
}

.bug-section-title p {
  margin: 0;
  color: #64748b;
  font-size: 13px;
  line-height: 1.45;
}

.bug-report-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 15px;
}

.bug-report-form .full,
.bug-evidence-uploader.full,
.bug-form-actions.full {
  grid-column: 1 / -1;
}

.bug-evidence-uploader {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 0.8fr);
  gap: 14px;
}

.bug-dropzone {
  min-height: 170px;
  border: 2px dashed #bad0ff;
  border-radius: 18px;
  background: #f8fbff;
  display: grid;
  place-items: center;
  align-content: center;
  text-align: center;
  padding: 20px;
  margin: 0;
  cursor: pointer;
}

.bug-dropzone input {
  display: none;
}

.bug-dropzone span {
  color: #0f4fc4;
  font-size: 34px;
  line-height: 1;
}

.bug-dropzone strong {
  display: block;
  color: #0f2442;
  margin-top: 8px;
}

.bug-dropzone p {
  margin: 4px 0;
  color: #0f4fc4;
  font-size: 13px;
  font-weight: 900;
}

.bug-dropzone small {
  color: #64748b;
  font-size: 11px;
  line-height: 1.35;
}

.bug-selected-files {
  display: grid;
  align-content: start;
  gap: 9px;
}

.bug-selected-files button {
  width: 100%;
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr) 18px;
  align-items: center;
  gap: 10px;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  background: #ffffff;
  color: #0f2442;
  padding: 10px;
  text-align: left;
}

.bug-selected-files button > span {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 10px;
  font-weight: 900;
}

.bug-selected-files strong {
  display: block;
  color: #0f2442;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.bug-selected-files small {
  color: #64748b;
  font-size: 11px;
}

.bug-selected-files b {
  color: #ed1c24;
  font-size: 17px;
}

.bug-empty-files {
  border: 1px dashed #d9e2ef;
  border-radius: 12px;
  background: #fbfdff;
  color: #64748b;
  padding: 14px;
  font-size: 12px;
  text-align: center;
}

.bug-form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
  padding-top: 4px;
}

.bug-list-header {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

.bug-filters {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) 190px 190px;
  gap: 12px;
  align-items: center;
  margin-bottom: 16px;
}

.bug-filters select {
  height: 46px;
  border: 1px solid #d9e2ef;
  border-radius: 10px;
  background: #ffffff;
  color: #0f2442;
  padding: 0 12px;
  font-weight: 800;
