  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.bug-report-title-row h4 {
  margin: 0;
  color: #0f2442;
  font-size: 17px;
  line-height: 1.25;
}

.bug-report-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.bug-report-meta span {
  display: inline-flex;
