  font-weight: 900;
  line-height: 1.2;
}

.bug-priority-low {
  background: #f1f5f9;
  color: #475569;
  border: 1px solid #e2e8f0;
}

.bug-priority-medium {
  background: #eaf2ff;
  color: #0f4fc4;
  border: 1px solid #bad0ff;
}

.bug-priority-high {
  background: #ffedd5;
  color: #c2410c;
  border: 1px solid #fed7aa;
}

.bug-priority-critical {
  background: #fee2e2;
  color: #b42318;
  border: 1px solid #fecaca;
}

.bug-status-new {
  background: #eaf2ff;
  color: #0f4fc4;
  border: 1px solid #bad0ff;
}

.bug-status-review {
  background: #fff4d8;
  color: #92400e;
  border: 1px solid #fde68a;
}

.bug-status-progress {
  background: #ede9fe;
  color: #7c3aed;
  border: 1px solid #ddd6fe;
}

.bug-status-resolved {
  background: #dcfce7;
  color: #166534;
  border: 1px solid #bbf7d0;
}

.bug-status-muted,
.bug-status-closed {
  background: #f1f5f9;
  color: #475569;
  border: 1px solid #e2e8f0;
}

.bug-evidence-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
  margin: 12px 0;
}

.bug-evidence-item {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  border: 1px solid #dbe7ff;
  border-radius: 13px;
  background: #ffffff;
  padding: 10px;
  text-decoration: none;
}

.bug-evidence-item > span {
  width: 34px;
  height: 34px;
  display: grid;
  place-items: center;
  border-radius: 9px;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 10px;
  font-weight: 900;
}

.bug-evidence-item strong {
  display: block;
  color: #0f2442;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.bug-evidence-item small {
  color: #64748b;
  font-size: 11px;
}

.bug-admin-comment-box {
  border: 1px solid #bbf7d0;
  border-radius: 13px;
  background: #f0fdf4;
  padding: 12px;
  margin-top: 12px;
}

.bug-admin-panel {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid #e5eaf2;
}

.bug-admin-editor {
  display: grid;
  gap: 12px;
  border: 1px solid #dbe7ff;
  border-radius: 14px;
  background: #f8fbff;
  padding: 12px;
}

.bug-admin-editor label {
  margin: 0;
  display: grid;
  gap: 7px;
}

.bug-admin-editor label > span {
  color: #0f2442;
  font-size: 12px;
  font-weight: 900;
}

.bug-admin-editor textarea {
  min-height: 78px;
}

.bug-admin-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
}

@media (max-width: 1450px) {
  .bug-reports-layout {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 1100px) {
  .bug-metrics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .bug-evidence-uploader,
  .bug-filters {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .bug-metrics-grid,
  .bug-report-form {
    grid-template-columns: 1fr;
  }

  .bug-report-form .full,
  .bug-evidence-uploader.full,
  .bug-form-actions.full {
    grid-column: auto;
  }

  .bug-header-summary {
    width: 100%;
  }

  .bug-form-actions,
  .bug-admin-actions {
    flex-direction: column;
  }

  .bug-form-actions button,
  .bug-admin-actions button {
    width: 100%;
  }
}

