.admin-dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr) minmax(360px, 1.25fr);
  gap: 18px;
}

.admin-panel-card {
  min-width: 0;
  background: rgba(255, 255, 255, 0.96);
  border: 1px solid #e1e9f3;
  border-radius: 15px;
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.07);
  padding: 20px;
}

.actions-panel {
  grid-column: 2 / 4;
}

.admin-panel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  margin-bottom: 16px;
}

.admin-panel-header h3 {
  margin: 0;
  color: #071b49;
  font-size: 18px;
}

.admin-panel-header button {
  border: none;
  background: transparent;
  color: #0f70bd;
  font-size: 12px;
  font-weight: 900;
}

.admin-list-stack,
.admin-activity-list,
.approval-list {
  display: grid;
  gap: 12px;
}

.admin-priority-row,
.approval-row {
  width: 100%;
  border: none;
  background: transparent;
  display: grid;
  align-items: center;
  gap: 12px;
  text-align: left;
}

.admin-priority-row {
  grid-template-columns: 46px minmax(0, 1fr) auto;
  padding: 7px 0;
}

.admin-row-icon,
.admin-activity-dot,
.approval-row > span:first-child {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
}

.admin-row-red { background: #fee2e2; color: #ed1c24; }
.admin-row-gold { background: #fff4d8; color: #f59e0b; }
.admin-row-blue { background: #eaf2ff; color: #0f4fc4; }
.admin-row-orange { background: #ffedd5; color: #f97316; }
.admin-row-purple { background: #ede9fe; color: #7c3aed; }
.admin-row-teal { background: #ccfbf1; color: #0f9488; }
.admin-row-green { background: #dcfce7; color: #16a34a; }

.admin-priority-row strong,
.admin-activity-row strong,
.approval-row strong,
.next-action-card strong {
  display: block;
  color: #071b49;
  font-size: 13px;
  line-height: 1.25;
}

.admin-priority-row small,
.admin-activity-row small,
.approval-row small,
.next-action-card small {
  display: block;
  color: #526176;
  font-size: 12px;
  line-height: 1.35;
  margin-top: 3px;
}

.admin-pill {
  border-radius: 8px;
  padding: 7px 10px;
  font-size: 11px;
}

.admin-pill-red { background: #fee2e2; color: #ed1c24; }
.admin-pill-gold { background: #fff4d8; color: #d99a00; }
.admin-pill-blue { background: #eaf2ff; color: #0f4fc4; }
.admin-pill-green { background: #dcfce7; color: #16a34a; }
.admin-pill-orange { background: #ffedd5; color: #f97316; }
.admin-pill-purple { background: #ede9fe; color: #7c3aed; }
.admin-pill-teal { background: #ccfbf1; color: #0f9488; }

.admin-activity-row {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
  padding: 5px 0;
}

.admin-activity-dot {
  width: 24px;
  height: 24px;
  border-radius: 50%;
}

.admin-activity-dot .executive-svg-icon {
  width: 15px;
  height: 15px;
}

.admin-activity-blue { background: #eaf2ff; color: #0f4fc4; }
.admin-activity-green { background: #dcfce7; color: #16a34a; }
.admin-activity-gold { background: #fff4d8; color: #d99a00; }
.admin-activity-orange { background: #ffedd5; color: #f97316; }
.admin-activity-purple { background: #ede9fe; color: #7c3aed; }
.admin-activity-red { background: #fee2e2; color: #ed1c24; }

.admin-activity-row em,
.approval-row em,
.next-action-card em {
  color: #64748b;
  font-size: 11px;
  font-style: normal;
  white-space: nowrap;
}

.status-summary-layout {
  display: grid;
  grid-template-columns: 170px minmax(0, 1fr);
  gap: 22px;
  align-items: center;
}

.status-donut {
  width: 155px;
  height: 155px;
  display: grid;
  place-items: center;
  align-content: center;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px #e5eaf2;
}

.status-donut strong {
  display: block;
  color: #071b49;
  font-size: 28px;
  line-height: 1;
}

.status-donut span {
  display: block;
  color: #64748b;
  font-size: 12px;
  margin-top: -30px;
}

.status-legend-list {
  display: grid;
  gap: 12px;
}

.status-legend-row {
  display: grid;
  grid-template-columns: 10px minmax(0, 1fr) 36px 40px;
  align-items: center;
  gap: 12px;
}

.legend-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
}

.legend-teal { background: #0ea5b7; }
.legend-gold { background: #f59e0b; }
.legend-blue { background: #2563eb; }
.legend-green { background: #22c55e; }

.status-legend-row span,
.status-legend-row small {
  color: #29436f;
  font-size: 12px;
}

.status-legend-row strong {
  color: #071b49;
  font-size: 13px;
}

.approval-row {
  grid-template-columns: 42px minmax(0, 1fr) auto auto;
  padding: 10px 0;
  border-bottom: 1px solid #edf1f7;
}

.approval-row > span:first-child {
  background: #ccfbf1;
  color: #0f9488;
}

.approval-row b {
  border: 1px solid #0ea5b7;
  border-radius: 8px;
  color: #0f70bd;
  padding: 7px 11px;
  font-size: 12px;
}

.next-actions-list-redesign {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.next-action-card {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 14px;
  align-items: center;
  border: none;
  border-radius: 14px;
  background: #ffffff;
  padding: 14px;
  text-align: left;
}

.next-action-card:hover {
  background: #f8fbff;
}

.next-action-date {
  width: 54px;
  height: 62px;
  display: grid;
  place-items: center;
  align-content: center;
  border-radius: 13px;
  background: #eaf2ff;
  color: #071b49;
}

.next-action-date small,
.next-action-date strong {
  display: block;
}

.next-action-date small {
  color: #2563eb;
  font-size: 11px;
  font-weight: 900;
}

.next-action-date strong {
  font-size: 23px;
  line-height: 1;
}

@media (max-width: 1450px) {
  .admin-kpi-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-dashboard-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .status-panel,
  .actions-panel {
    grid-column: auto;
  }

  .next-actions-list-redesign {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 1050px) {
  .app-shell {
    grid-template-columns: 250px minmax(0, 1fr);
  }

  .redesigned-topbar {
    grid-template-columns: 1fr auto;
    gap: 16px;
    padding: 16px 22px;
  }

  .topbar-search {
    grid-column: 1 / -1;
    order: 3;
  }

  .admin-dashboard-proposal {
    padding: 26px 22px;
  }

  .admin-dashboard-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 800px) {
  .app-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    display: none;
  }

  .main-content {
    padding-bottom: 76px;
  }

  .redesigned-topbar {
    display: none;
  }

  .admin-kpi-grid,
  .status-summary-layout {
    grid-template-columns: 1fr;
  }

  .admin-executive-hero {
    flex-direction: column;
  }
}
.admin-activity-teal { background: #ccfbf1; color: #0f9488; }


