/* =========================================================
   REDISEÑO TABLERO GENERAL - LIMPIO Y COMPACTO
========================================================= */

.workspace-dashboard-redesign {
  padding: 34px 38px 42px;
  display: grid;
  gap: 22px;
}

.workspace-redesign-header {
  margin: 0;
  padding: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.workspace-redesign-header h1 {
  margin: 0 0 8px;
  color: #071b49;
  font-size: 32px;
  letter-spacing: -0.035em;
  line-height: 1.12;
}

.workspace-redesign-header p {
  margin: 0;
  color: #526176;
  font-size: 15px;
  line-height: 1.45;
}

.compact-pending-strip {
  width: fit-content;
  margin-top: 12px;
  padding: 9px 13px;
  border-radius: 999px;
  background: #fff7ed;
  border: 1px solid #fed7aa;
  color: #9a3412;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
}

.workspace-clean-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.workspace-clean-metric {
  position: relative;
  min-height: 132px;
  display: grid;
  grid-template-columns: 70px minmax(0, 1fr);
  gap: 18px;
  align-items: center;
  padding: 22px;
  border-radius: 18px;
  border: 1px solid #e1e9f3;
  background: #ffffff;
  box-shadow: 0 16px 40px rgba(15, 23, 42, 0.07);
  color: #071b49;
  text-align: left;
  overflow: hidden;
  transition: 0.18s ease;
}

.workspace-clean-metric:hover {
  transform: translateY(-2px);
  border-color: #c8d7ee;
  box-shadow: 0 20px 45px rgba(15, 23, 42, 0.09);
}

.workspace-clean-metric::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 4px;
}

.workspace-clean-metric.metric-blue::after { background: #0f4fc4; }
.workspace-clean-metric.metric-gold::after { background: #d99a00; }
.workspace-clean-metric.metric-green::after { background: #16a34a; }
.workspace-clean-metric.metric-purple::after { background: #7c3aed; }

.workspace-clean-icon {
  width: 64px;
  height: 64px;
  display: grid;
  place-items: center;
  border-radius: 19px;
  font-size: 30px;
  background: #eaf2ff;
}

.workspace-clean-metric.metric-gold .workspace-clean-icon { background: #fff4d8; }
.workspace-clean-metric.metric-green .workspace-clean-icon { background: #dcfce7; }
.workspace-clean-metric.metric-purple .workspace-clean-icon { background: #ede9fe; }

.workspace-clean-metric strong {
  display: block;
  color: #071b49;
  font-size: 34px;
  line-height: 1;
  margin-bottom: 8px;
}

.workspace-clean-metric small {
  display: block;
  color: #071b49;
  font-size: 14px;
  font-weight: 900;
  line-height: 1.25;
}

.workspace-clean-metric em {
  display: block;
  margin-top: 5px;
  color: #64748b;
  font-size: 13px;
  font-style: normal;
  line-height: 1.25;
}

.workspace-primary-grid-redesign {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
  align-items: start;
}

.workspace-clean-card {
  background: #ffffff;
  border: 1px solid #e1e9f3;
  border-radius: 20px;
  box-shadow: 0 18px 45px rgba(15, 23, 42, 0.07);
  padding: 24px;
  min-width: 0;
  overflow: hidden;
}

.workspace-clean-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 18px;
  padding-bottom: 18px;
  border-bottom: 1px solid #e8edf3;
  margin-bottom: 18px;
}

.workspace-clean-card-header h3 {
  margin: 0 0 6px;
  color: #071b49;
  font-size: 22px;
  letter-spacing: -0.025em;
}

.workspace-clean-card-header p {
  margin: 0;
  color: #526176;
  font-size: 14px;
  line-height: 1.45;
}

.workspace-clean-card-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 12px;
  flex-wrap: wrap;
}

.workspace-clean-card-actions > span {
  display: inline-grid;
  place-items: center;
  min-height: 35px;
  padding: 8px 14px;
  border-radius: 999px;
  background: #eaf2ff;
  color: #0f4fc4;
  border: 1px solid #bad0ff;
  font-size: 13px;
  font-weight: 900;
  white-space: nowrap;
}

.notes-clean-card .workspace-clean-card-actions > span,
.note-empty-button,
.note-action-button {
  background: #fff4d8;
  color: #a16207;
  border-color: #fde68a;
}

.clean-action-button {
  min-height: 38px;
  border-radius: 12px;
  padding: 10px 14px;
  font-size: 13px;
  box-shadow: 0 12px 24px rgba(15, 79, 196, 0.18);
}

.note-action-button {
  box-shadow: 0 12px 24px rgba(217, 154, 0, 0.18);
}

.clean-composer {
  margin-bottom: 18px;
  border: 1px solid #dbe7ff;
  border-radius: 18px;
  background: #f8fbff;
  padding: 18px;
}

.clean-note-composer {
  border-color: #fde68a;
  background: #fffdf6;
}

.clean-toolbar {
  margin: 0 0 16px;
  padding: 0;
  border: none;
  background: transparent;
}

.clean-announcement-list,
.clean-notes-list {
  max-height: 420px;
  overflow-y: auto;
  padding-right: 4px;
}

.workspace-clean-empty {
  min-height: 320px;
  display: grid;
  place-items: center;
  align-content: center;
  text-align: center;
  gap: 10px;
  padding: 28px;
  color: #526176;
}

.clean-empty-illustration-icon {
  width: 108px;
  height: 108px;
  display: grid;
  place-items: center;
  border-radius: 34px;
  background: #eaf2ff;
  color: #0f4fc4;
  font-size: 54px;
  margin-bottom: 10px;
}

.note-empty-illustration .clean-empty-illustration-icon {
  background: #fff4d8;
  color: #d99a00;
}

.clean-empty-illustration-icon.muted {
  background: #f1f5f9;
  color: #94a3b8;
}

.workspace-clean-empty strong {
  color: #071b49;
  font-size: 17px;
}

.workspace-clean-empty p {
  max-width: 460px;
  margin: 0;
  color: #64748b;
  font-size: 14px;
  line-height: 1.45;
}

.clean-empty-button {
  margin-top: 8px;
  border-radius: 999px;
  padding: 10px 16px;
}

.clean-announcement-item,
.clean-note-item {
  border-radius: 16px;
  border: 1px solid #e2e8f0;
  box-shadow: none;
}

.clean-announcement-item + .clean-announcement-item,
.clean-note-item + .clean-note-item {
  margin-top: 12px;
}

.clean-admin-actions,
.clean-note-actions {
  border-top: 1px solid #e8edf3;
  margin-top: 14px;
  padding-top: 12px;
}

.workspace-admin-details {
  margin-top: 18px;
  border: 1px solid #dbe7ff;
  border-radius: 16px;
  background: #f8fbff;
  padding: 12px 14px;
}

.workspace-admin-details > summary {
  color: #0f4fc4;
  font-size: 13px;
  font-weight: 900;
  cursor: pointer;
}

.workspace-admin-details[open] > summary {
  margin-bottom: 14px;
}

.workspace-activity-clean-card {
  min-height: 160px;
}

.compact-activity-header {
  margin-bottom: 0;
}

.workspace-clean-activity-list {
  display: grid;
  gap: 10px;
}

.workspace-clean-activity-item {
  width: 100%;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  border: 1px solid #e8edf3;
  border-radius: 14px;
  background: #ffffff;
  padding: 13px;
  text-align: left;
  transition: 0.18s ease;
}

.workspace-clean-activity-item:hover {
  background: #f8fbff;
  border-color: #c8d7ee;
  transform: translateY(-1px);
}

.workspace-clean-activity-item > span:first-child {
  width: 38px;
  height: 38px;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: #eaf2ff;
}

.workspace-clean-activity-item strong {
  display: block;
  color: #071b49;
  font-size: 14px;
  line-height: 1.25;
}

.workspace-clean-activity-item small {
  display: block;
  color: #64748b;
  font-size: 13px;
  line-height: 1.35;
  margin-top: 3px;
}

.workspace-clean-activity-item em {
  color: #64748b;
  font-style: normal;
  font-size: 12px;
  white-space: nowrap;
}

.compact-clean-empty {
  min-height: 140px;
}

.compact-clean-empty .clean-empty-illustration-icon {
  width: 56px;
  height: 56px;
  font-size: 28px;
  border-radius: 18px;
  margin-bottom: 0;
}

@media (max-width: 1350px) {
  .workspace-clean-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .workspace-primary-grid-redesign {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 800px) {
  .workspace-dashboard-redesign {
    padding: 20px 18px 82px;
  }

  .workspace-clean-metrics {
    grid-template-columns: 1fr;
  }

  .workspace-clean-card-header,
  .workspace-clean-card-actions {
    flex-direction: column;
    align-items: flex-start;
  }

  .workspace-clean-card-actions,
  .clean-action-button {
    width: 100%;
  }

  .workspace-clean-metric {
    grid-template-columns: 58px minmax(0, 1fr);
    min-height: 112px;
  }

  .workspace-clean-icon {
    width: 54px;
    height: 54px;
    font-size: 25px;
  }

  .workspace-clean-activity-item {
    grid-template-columns: 42px minmax(0, 1fr);
  }

  .workspace-clean-activity-item em {
    grid-column: 2;
  }
}

