/* =========================================================
   AJUSTES TABLERO GENERAL - SIMETRÍA Y MENÚ LATERAL
========================================================= */

/* Mantiene el color institucional del menú visible al hacer scroll. */
.sidebar {
  position: sticky;
  top: 0;
  height: 100vh;
  min-height: 100vh;
  align-self: start;
}

/* Evita que aparezca un espacio blanco debajo de la columna del menú en vistas largas. */
.app-shell {
  background:
    linear-gradient(90deg, #071f4f 0, #071f4f 292px, #f5f7fb 292px, #f5f7fb 100%);
}

.app-shell.sidebar-collapsed {
  background:
    linear-gradient(90deg, #071f4f 0, #071f4f 92px, #f5f7fb 92px, #f5f7fb 100%);
}

/* Hace que Tablero de anuncios y Mis notas personales queden del mismo alto. */
.workspace-primary-grid-redesign {
  align-items: stretch;
}

.workspace-primary-grid-redesign > .workspace-clean-card {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.workspace-primary-grid-redesign .clean-announcement-list,
.workspace-primary-grid-redesign .clean-notes-list,
.workspace-primary-grid-redesign .workspace-clean-empty {
  flex: 1;
}

.notes-clean-card .workspace-clean-empty {
  min-height: 0;
}

/* En pantallas pequeñas se conserva el comportamiento normal. */
@media (max-width: 1050px) {
  .sidebar {
    position: relative;
