/* =========================================================
   AJUSTE MENÚ LATERAL - STICKY CON PATRÓN INSTITUCIONAL
========================================================= */

/* Quitamos el relleno sólido agregado antes para que no se vea una franja plana. */
.app-shell,
.app-shell.sidebar-collapsed {
  position: relative;
  background: #f5f7fb;
}

/* Mantiene una capa fija con el mismo patrón del menú detrás de la columna izquierda. */
.app-shell::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 292px;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 18% 8%, rgba(255, 255, 255, 0.16), transparent 28%),
    radial-gradient(circle at 95% 18%, rgba(237, 28, 36, 0.22), transparent 34%),
    radial-gradient(circle at 15% 95%, rgba(237, 28, 36, 0.16), transparent 30%),
    linear-gradient(180deg, #123f8c 0%, #0a2f70 45%, #071f4f 100%);
}

.app-shell.sidebar-collapsed::before {
  width: 92px;
}

.sidebar {
  position: sticky;
  top: 0;
  height: 100vh;
  min-height: 100vh;
  align-self: start;
  z-index: 2;
  background:
    radial-gradient(circle at 18% 8%, rgba(255, 255, 255, 0.16), transparent 28%),
    radial-gradient(circle at 95% 18%, rgba(237, 28, 36, 0.22), transparent 34%),
    radial-gradient(circle at 15% 95%, rgba(237, 28, 36, 0.16), transparent 30%),
    linear-gradient(180deg, #123f8c 0%, #0a2f70 45%, #071f4f 100%);
}

.main-content,
.redesigned-main-content {
  position: relative;
  z-index: 1;
}

@media (max-width: 1050px) {
  .app-shell::before,
  .app-shell.sidebar-collapsed::before {
    display: none;
  }

  .sidebar {
    position: relative;
    height: auto;
    min-height: auto;
  }
}

/* =========================================================
   AJUSTE FINAL MENÚ LATERAL - FIJO, A LA MANO Y SIN CORTES
========================================================= */

.app-shell {
  position: relative;
  grid-template-columns: 292px minmax(0, 1fr);
  background: #f5f7fb;
}

.app-shell.sidebar-collapsed {
  grid-template-columns: 92px minmax(0, 1fr);
}

.app-shell::before {
  content: "";
  position: fixed;
  inset: 0 auto 0 0;
  width: 292px;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 18% 8%, rgba(255, 255, 255, 0.16), transparent 28%),
    radial-gradient(circle at 95% 18%, rgba(237, 28, 36, 0.22), transparent 34%),
    radial-gradient(circle at 15% 95%, rgba(237, 28, 36, 0.16), transparent 30%),
    linear-gradient(180deg, #123f8c 0%, #0a2f70 45%, #071f4f 100%);
}

.app-shell.sidebar-collapsed::before {
  width: 92px;
}

.sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  width: 292px;
  height: 100dvh;
  min-height: 100dvh;
  overflow-y: auto;
  overflow-x: hidden;
  z-index: 5;
  background:
    radial-gradient(circle at 18% 8%, rgba(255, 255, 255, 0.16), transparent 28%),
    radial-gradient(circle at 95% 18%, rgba(237, 28, 36, 0.22), transparent 34%),
