}

.sidebar::-webkit-scrollbar-track {
  background: transparent;
}

.sidebar::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.22);
  border-radius: 999px;
}

.sidebar::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 18% 8%, rgba(255, 255, 255, 0.12), transparent 28%),
    radial-gradient(circle at 95% 18%, rgba(237, 28, 36, 0.15), transparent 34%),
    radial-gradient(circle at 15% 95%, rgba(237, 28, 36, 0.12), transparent 30%);
  opacity: 1;
}

.sidebar::after {
  content: "";
  position: absolute;
  left: -100px;
  bottom: -120px;
  width: 360px;
  height: 360px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.08);
  pointer-events: none;
}

.app-shell.sidebar-collapsed .sidebar {
  width: 92px;
}

.sidebar-brand-panel,
.sidebar-collapse-button,
.sidebar-nav,
.sidebar-help-card {
