  .app-shell.sidebar-collapsed {
    grid-template-columns: 1fr;
  }

  .app-shell::before,
  .app-shell.sidebar-collapsed::before {
    display: none;
  }

  .sidebar,
  .app-shell.sidebar-collapsed .sidebar {
    position: relative;
    inset: auto;
    width: 100%;
    height: auto;
    min-height: auto;
    overflow: visible;
  }
}

/* =========================================================
